package com.cuber.bookvoice

import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.media.AudioManager
import android.media.audiofx.LoudnessEnhancer
import android.os.Handler
import android.os.Looper
import android.os.SystemClock
import android.speech.tts.TextToSpeech
import android.speech.tts.UtteranceProgressListener
import android.speech.tts.Voice
import java.io.File
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors

/**
 * Плеер озвучки, в котором звук играет САМО приложение, а не движок синтеза.
 *
 * Зачем. Пока голос произносил движок TextToSpeech напрямую, аудио числилось
 * за процессом движка — Android не считал BookVoice «плеером» и не отдавал
 * ему медиа-кнопки (гарнитура, «волшебное касание»): они уходили последнему
 * настоящему плееру (YouTube/Nekogram). Лог диагностики это подтвердил:
 * кнопка не доходила до приложения ни разу.
 *
 * Как теперь. Движок TTS только СИНТЕЗИРУЕТ предложение в wav-файл, а файл
 * проигрывает наш плеер (Media3 ExoPlayer, см. [FilePlayback]). Раз звук
 * физически играет из нашего процесса, система видит BookVoice как настоящий
 * плеер и отдаёт кнопки нам.
 *
 * Чтобы между предложениями не было пауз на синтез, фразы готовятся заранее:
 * пока играет текущая, читалка подсказывает через [onNeedNext] текст следующей,
 * и мы синтезируем её в файл. С msg4472 впрок держится не одна фраза, а
 * очередь из [prefetchDepth]: у тестеров на Poco и realme движок синтеза
 * замирал на 12–15 с (экран заблокирован), и с одной заготовкой это слышалось
 * как пауза, а с тремя — проходит незаметно.
 */
class SpeechPlayer(context: Context) {

    private val appContext = context.applicationContext
    private val main = Handler(Looper.getMainLooper())

    // ——— ЕДИНИЦЫ РЕЧИ: состояние (08.10.2026) ———
    //
    // ВАЖНО, ГДЕ ЭТИ ПОЛЯ ОБЪЯВЛЕНЫ. Конструктор класса зовёт start() →
    // resetPipeline(), а инициализаторы свойств выполняются по порядку объявления:
    // поле, объявленное НИЖЕ конструктора, в этот момент ещё null. 08.10.2026 на
    // этом приложение падало при запуске (NPE на playedKeys.clear() в
    // resetPipeline). Поэтому состояние единиц речи живёт здесь, у самого верха, —
    // НЕ переносить его вниз, к своим функциям.

    /** Сколько кусков у фразы с этой позицией. Заполняется тогда, когда чтение
     *  называет куски фразы ([speak], [prefetchRest]). */
    private val phraseParts by lazy { HashMap<Long, Int>() }

    /** Последняя позиция и кусок, которые просили говорить: по ним нумеруются
     *  куски — второй кусок той же фразы получает номер 1 и так далее. */
    private var lastAskedPos = -1L
    private var lastAskedPart = -1

    /** Номер куска звучащей сейчас единицы и её ключ. */
    private var playingPart = 0
    private var playingKey = -1L

    /** Ключи единиц, уже прозвучавших в ЭТОМ проходе чтения. Проход начинается
     *  заново на любом действии человека (продолжить, повторить, шаг назад,
     *  прыжок) и на старте чтения. Правило: вперёд единица звучит один раз. */
    private val playedKeys by lazy { HashSet<Long>() }

    /** Последняя доигравшая единица — по ней считаем, какая обязана звучать
     *  следующей, когда список плеера уже опустел. */
    private var lastPlayedPos = -1L
    private var lastPlayedPart = -1

    /** Что сообщили чтению в последнем «доиграла»: место и кусок единицы, а
     *  также был ли это её последний кусок. По этим числам чтение решает,
     *  двигать ли место в книге (см. `ReaderEngine.onPlayerDone`). */
    var lastDonePos: Long = -1L
        private set
    var lastDonePart: Int = -1
        private set
    var lastDoneLast: Boolean = true
        private set

    /** О чём уже писали в журнал: строки про порядок не должны повторяться на
     *  каждой фразе, иначе журнал не читается. */
    private val orderLogged by lazy { HashSet<String>() }

    /** Когда фразу ОТДАЛИ движку в прямом чтении (мс, [SystemClock.elapsedRealtime]).
     *
     *  08.10.2026, жалоба тестера (сборка 234): движок-прослойка `dev.msvoice.tts`
     *  принимал фразу и мгновенно отвечал «готово», не сказав ни слова. За полторы
     *  секунды чтение ушло на семьдесят предложений вперёд — «книга прокручивается
     *  без чтения». Считать это молчанием было нечем: `directStartedAt` заполняется
     *  по сигналу «начал говорить», а этот движок его вовсе не слал.
     *  Здесь время ЗАКАЗА — оно есть всегда, поэтому по нему и считаем.
     *
     *  ОБЪЯВЛЕНО ЗДЕСЬ, У ВЕРХА, и через by lazy — потому что [resetPipeline]
     *  чистит эту карту, а его зовёт конструктор (init → start). Поле, объявленное
     *  ниже конструктора, в этот момент ещё null, и приложение падало при запуске
     *  (так вышло дважды: 08.10.2026 утром на playedKeys и вечером на directAskedAt
     *  — сборка 252e вылетала у Сержа и у тестера). by lazy закрывает этот класс
     *  ошибок совсем: значение создаётся при первом обращении, где бы поле ни
     *  стояло. НЕ переносить вниз и не убирать lazy. */
    private val directAskedAt by lazy { HashMap<Long, Long>() }

    /** Сколько фраз подряд движок «прочитал», не подав признаков речи. Отдельный
     *  счётчик от `silentInRow`: там явный отказ движка (ошибка, пустой файл),
     *  здесь — отчёт «готово» без звука (см. [ackLooksSilent]). */
    private var ackSilentInRow = 0

    /** Сколько раз писали в журнал про «ответил раньше звука» (без подозрения). */
    private var ackEarlyLogged = 0

    /** Сколько раз за сессию написали «отчитался быстрее, чем можно произнести»
     *  (см. [directAckHoldMs]). Отдельно от [ackEarlyLogged]: тот про движки,
     *  которые играют звук сами, а этот — про отчёт без звука вовсе. */
    private var ackFastLogged = 0

    /** Сколько раз писали в журнал про проверку «сломанный движок» (см.
     *  [queueDirect]). Ограничено: иначе журнал распухнет — фраз в книге много. */
    private var brokenEngineLogged = 0

    /** То же для проверки «движок отказывается» (см. [queueDirect]). */
    private var brokenRefusedLogged = 0

    private var tts: TextToSpeech? = null
    private var ready = false
    private var engineReadyCallback: ((Boolean) -> Unit)? = null

    /** Пакет текущего движка синтеза (null — системный по умолчанию). */
    var enginePackage: String? = null
        private set

    var speed: Float = 1f
        set(value) {
            if (field == value) return
            field = value
            tts?.setSpeechRate(value)
            // 24.09.2026: заготовки сделаны прежней скоростью, и играть их
            // прежним темпом нельзя (см. [Prepared]). Выбрасываем сразу, а не
            // по одной на подходе: иначе три устаревшие фразы подряд собирались
            // бы заново без упреждения и чтение спотыкалось бы на каждой.
            dropStaleRate()
            // 29.09.2026: и сам звучащий файл подтягиваем на ходу — иначе новая
            // скорость слышна только с начала следующей фразы. У ExoPlayer темп
            // меняется его собственными параметрами, с сохранением высоты голоса.
            //
            // Файл звучит уже на скорости [exoPlayingRate] (его так записал
            // движок), поэтому плееру задаём отношение к новому ползунку: иначе
            // скорость применилась бы дважды — и движком, и плеером. Реплике
            // книжный ползунок не указ: у неё своя скорость.
            if (playingFile?.let { roleOfFile(it) } != Pending.Role.REPLY) {
                runCatching {
                    filePlayer.setSpeed((value / exoPlayingRate).coerceIn(0.25f, 4f))
                }
            }
            // 05.10.2026: в прямом чтении движок держит СВОЮ очередь, и темп в ней
            // застыл прежним — её надо перечитать (см. [onDirectRateChanged]).
            onDirectRateChanged()
        }

    /** Высота голоса (тон). Норма = 1.0. Движку задаётся для СЛЕДУЮЩЕГО синтеза,
     *  а уже звучащую фразу доводит плеер ([exoSyncSpeed]) — иначе новая высота
     *  слышна только с начала следующей фразы.
     *
     *  29.09.2026 (Серж: «кручу тон — срабатывает не мгновенно, а с задержкой
     *  большущей»): пока ползунок не выбрасывал заготовки, прежним тоном доигрывало
     *  ВСЁ, что стоит впереди (три-четыре фразы, до полусотни секунд звука), и ещё
     *  звучащая фраза. Теперь заготовки выбрасываются, а звучащая дотягивается. */
    var pitch: Float = 1f
        set(value) {
            val v = value.coerceIn(0.25f, 4f)
            if (field == v) return
            field = v
            tts?.setPitch(v)
            // Заготовки сделаны прежним тоном — играть их нельзя (та же причина,
            // что у смены скорости, поэтому и чистка та же).
            dropStaleRate()
            // Реплике книжный ползунок не указ: у неё своя высота.
            if (playingFile?.let { roleOfFile(it) } != Pending.Role.REPLY) {
                runCatching {
                    filePlayer.setPitch((v / exoPlayingPitch).coerceIn(0.25f, 4f))
                }
            }
        }

    /** Короткие паузы между предложениями (msg4402, просьба тестера
     *  @Spartach72). Мы озвучиваем каждое предложение отдельным файлом, и по
     *  краям движок оставляет тишину — в чтении по предложениям она слышна как
     *  пауза; здесь обрезаем эту тишину, оставляя короткие хвосты.
     *  msg4416: вторая половина той же правки живёт в ReaderEngine — соседние
     *  короткие предложения уходят в движок одной фразой. Обрезка работает не
     *  на всех движках (у DariyaNeural тишины по краям нет вовсе), но файл не
     *  портит, поэтому не выключается — галочку убрали (msg5254).
     *  msg5254: галочка «Короткие паузы между предложениями» убрана из настроек
     *  Сергеем — склейка и обрезка работают всегда, как было по умолчанию. */
    /** #57: альтернативный способ озвучки — фразу целиком отдаём движку
     *  ([fallbackDirect] как основной путь, проба для сравнения на слух,
     *  msg5401/5409). Обычно у нас наоборот: движок только готовит файл, а
     *  играет наш плеер.
     *
     *  Что при этом выключается: наши заготовки ([requestPrefetch]) — их
     *  работу движок делает сам. Сторож молчания продолжает работать, но своей
     *  веткой ([armDirectWatch]):
     *  он надзирает за прямой речью, а не за синтезом в файл, поэтому лестница
     *  мер «переспрос → перезапуск движка» здесь не взводится.
     *
     *  По умолчанию ВЫКЛ — настройка тестовая, обычное чтение не меняется. */
    var altDirect: Boolean = false
        set(value) {
            val was = field
            field = value
            // 30.09.2026: включился прямой режим — тихий поток встаёт вместе с ним.
            // В этом режиме звук играет движок, и без тихого потока система не
            // видит нас играющими: кнопки на наушниках уходят чужому плееру.
            // 24.10.2026: сам поток НЕ включаем (просьба Сержа: «пускай по
            // умолчанию будет выключена») — только пишем причину в журнал.
            if (value && !was) {
                KeepAwake.noteDirectNeedsSilence(appContext, "выбран альтернативный способ озвучки")
            }
        }

    /** Голос медленный — сетевой или помеченный медленным ([netSynth]).
     *
     *  Нужно читалке: такому голосу она отдаёт фразы ПО ОДНОМУ предложению
     *  (просьба Сержа 06.10.2026: «сделай чтобы по одному предложению, чтобы
     *  паузы были поменьше»). Склейка до четырёх предложений — это фраза на
     *  10-15 секунд речи, и у сетевого голоса первое звучание приходило через
     *  всё время её сборки: в журнале 00:12 первая фраза в 166 знаков зазвучала
     *  через 15,3 с. Одно предложение собирается в разы быстрее, поэтому звук
     *  начинается раньше, и каждая пауза короче. */
    val readsSlowly: Boolean get() = netSynth

    /** Сетевой движок оказался не в состоянии отдавать файлы — читаем его
     *  голосом напрямую, как в альтернативном способе (29.09.2026).
     *
     *  Почему так. Просьба Сержа: «что если сделать так, чтобы сетевому
     *  синтезатору посылалась по одной фразе, как в альтернативной озвучке».
     *  Журнал 02:16 подтвердил: у сетевого голоса mstrans файл не приходит ни за
     *  5 секунд, ни после переспроса — каждая фраза кончалась прямой речью, то
     *  есть мы каждый раз делали лишний круг: заказ файла, ожидание, переспрос,
     *  и только потом то, что работает сразу. Смысла в этом круге нет.
     *
     *  Решение по ОПЫТУ, а не по названию движка: пока файлы приходят, работаем
     *  файлами (у них бесшовный стык и свой плеер), а если движок дважды подряд
     *  не отдал файл — переходим на прямую речь и запоминаем это для пары
     *  «движок + голос». Пометка переживает перезапуск приложения. */
    private var netDirect = false

    /** Стоит ли на нынешней паре «движок + голос» пометка «файлов не отдаёт».
     *  Ставится в [applySpeedAndVoice]; по ней решаем, вести ли прямое чтение
     *  по одной фразе и пересоздавать ли соединение при смене скорости
     *  (см. [directAhead], [renewEngineOnRate]). */
    private var markedPairNoFiles = false

    /** Движок помечен как «файлов не отдаёт» ЦЕЛИКОМ, потому что своего голоса у
     *  него не выбирают (см. [decideDirectMode]). Ставится там же, читается в
     *  журнале о переходе на прямое чтение. */
    private var engineMarkedNoFiles = false

    /** Принудительный способ чтения из опытных настроек ([ExpertPrefs.forceMode]).
     *  Читается [applyForceMode] — на старте чтения и при применении голоса.
     *
     *  06.10.2026, просьба Сержа: «дать синтезатору каким способом читать... и
     *  чтобы без всяких проверок, что там установлено в этих синтезаторах».
     *  Обычно путь выбирает опыт, и это мешает опыту: помеченный движок нельзя
     *  заставить идти файлами, а исправный — читать голосом. Здесь ручка поверх
     *  всей автоматики. */
    private var forceMode: Int = ExpertPrefs.MODE_AUTO

    /** Читать движку напрямую: так у нас ТЕПЕРЬ ПО УМОЛЧАНИЮ (24.10.2026 — обычный
     *  способ, как у @Voice), либо сетевой движок не отдаёт файлы (см. [netDirect]). */
    private val directMode: Boolean get() = when (forceMode) {
        ExpertPrefs.MODE_DIRECT -> true
        ExpertPrefs.MODE_FILE -> false
        else -> altDirect || netDirect
    }

    /** Читаем ли СЕЙЧАС голосом движка (прямой путь). Нужно читалке: с 24.10.2026
     *  в обычном режиме фраза = ОДНО предложение, чтобы пауза и откат повторяли
     *  только его (решение Сержа: «пусть повтор текущей фразы» станет коротким). */
    val directNow: Boolean get() = directMode

    /** Почему читаем напрямую — словами. Ставится там, где решается [netDirect]
     *  ([applySpeedAndVoice], [markNetDirect]).
     *
     *  06.10.2026, просьба Сержа: «у меня сейчас сетевой синтезатор, и я не могу
     *  определять по галочке... хочу понимать, каким способом читается». Галочка
     *  отвечает только за СВОЙ выбор, а прямой режим включается и сам — по этому
     *  тексту человек (и журнал) видит настоящую причину. */
    private var directWhyText: String? = null

    /** Каким способом читаю СЕЙЧАС, словами; null — файловым (обходным).
     *  Читает [ReadingMode] — и строку настроек, и ответ вслух. */
    val directWhy: String?
        get() = when {
            forceMode == ExpertPrefs.MODE_DIRECT -> "так выбрано в опытных настройках: только движком"
            forceMode == ExpertPrefs.MODE_FILE -> null
            altDirect -> "обычный способ: голосом движка, как у @Voice"
            netDirect -> directWhyText ?: "движок не отдаёт файлы"
            else -> null
        }

    /** Почему читаю обычным способом, словами. Нужно, когда ручка опытных
     *  настроек велит идти файлами, хотя движок помечен как «файлов не отдаёт»:
     *  без этой строки ответ вслух противоречил бы пометке. */
    val fileWhy: String?
        get() = when {
            forceMode == ExpertPrefs.MODE_FILE -> "так выбрано в опытных настройках: только файлом"
            else -> null
        }

    /** Движок и голос, о которых говорит [directWhy], — чтобы ответ вслух был
     *  про конкретную пару, а не «вообще». */
    val pairLabel: String
        get() = "движок ${enginePackage ?: "системный"}, голос ${selectedVoiceName ?: "не назван"}"

    /** Голос, к которому относится [directWhy]. Нужен [ReadingMode]: после смены
     *  голоса или движка плеер ещё держит ответ о ПРЕЖНЕЙ паре, и по нему нельзя
     *  судить о той, что выбрана в настройках сейчас. */
    val pairVoice: String?
        get() = selectedVoiceName

    /** Каким способом читаем — в журнал, при смене ответа (10.10.2026).
     *
     *  Зачем. Способ выбирается САМ по опыту с парой «движок + голос», и в
     *  журнале этого не было видно: по строке «альтернативный способ: отдаю фразу
     *  движку» нельзя понять, ПОЧЕМУ читаем движком (галочка, ручка опытных
     *  настроек или пометка «файлов не отдаёт»). Разбор журнала тестера
     *  10.10.2026 упёрся именно в это: было ясно, что способ прямой, и непонятно,
     *  откуда он взялся. Строк ровно столько, сколько смен способа за сеанс. */
    private var modeLoggedFor: String? = null

    private fun logReadingMode() {
        val why = directWhy ?: fileWhy ?: "движок файлы отдаёт"
        val tag = "${enginePackage ?: "системный"}|${selectedVoiceName ?: ""}|$directMode|$why"
        if (tag == modeLoggedFor) return
        modeLoggedFor = tag
        Diag.log(
            appContext, "tts",
            "способ чтения: " + (
                if (directMode) "прямой — фразу целиком играет движок"
                else "обычный — движок готовит файл, играем мы"
                ) + "; причина: $why; $pairLabel"
        )
    }

    /** Идёт ли звук прямо сейчас. Нужно пробе движка из опытных настроек
     *  ([EngineProbe]): во время чтения она бессмысленна и мешает чтению. */
    val sounding: Boolean
        get() = if (directMode) {
            directSpeakingText != null || directQueue.isNotEmpty()
        } else {
            playingFile != null || !readyQueue.isEmpty()
        }

    /** Есть ли ещё не отзвучавшее: звук сейчас, заготовки в очереди или заявка,
     *  которую ждёт чтение. Нужно остановке чтения: она обязана ГАСИТЬ плеер, а
     *  не только ставить признак (см. `ReaderEngine.stopAtEnd`). */
    val pendingSound: Boolean
        get() = sounding || exoPending.isNotEmpty() || awaitingPlayText != null

    /** Звучит «проба голоса» — ровно ОДНА фраза с текущего места, дальше тишина
     *  и пауза (ставит читалка, см. `ReaderEngine.startSpeakingCurrent(preview)`).
     *
     *  Зачем это знать плееру. В пробе он заказывал заготовки впрок, как при
     *  обычном чтении: файлы следующих фраз уезжали в список ExoPlayer, и после
     *  конца пробной фразы плеер играл их сам. Читалка при этом уже считала, что
     *  чтение стоит (место не двигалось, кнопка «Начать чтение»), — снаружи это
     *  выглядело так, что книга читается «каким-то другим потоком», а пауза и
     *  остановка по включению экрана ничего не делают (жалоба тестера
     *  19.10.2026). Пока идёт проба, впрок не заказываем ничего: куски самой
     *  фразы заказывает [prefetchRest], и их это не касается. */
    var previewOnly = false

    /** Текст фразы, которая звучит прямо сейчас. */
    private var playingText: String? = null
    private var playingPos: Long = -1L

    /** Файл звучащей фразы и скорость, которой он сделан. Нужны паузе: файл при
     *  паузе никуда не удаляется, и продолжение можно начать с него же, не
     *  заставляя движок синтезировать ту же фразу второй раз (см.
     *  [pauseKeepingPhrase]). */
    private var playingFile: File? = null
    private var playingRate: Float = 1f

    /** Сколько раз за сессию журналируем пустой звук от движка (не спамить). */
    private var emptySoundLogged = 0

    /** Сколько пустых файлов подряд пришло от нынешней пары «движок + голос».
     *  Дошло до [EMPTY_SOUND_HITS] — файловый путь у неё считаем провалившимся
     *  (см. [synthFinished] и [markNetDirect]). Сбрасывается на любом файле со
     *  звуком. */
    private var emptySoundFails = 0

    /** Размеры готовых файлов по тексту фразы (скорость, которой файл сделан →
     *  сколько в нём байт). Нужны, чтобы заметить движок, который НАШУ скорость
     *  не применяет: одна и та же фраза на разных скоростях обязана давать файлы
     *  разного размера, а если размер не поехал — движок читает по своим
     *  настройкам (см. [noteRateIgnored]). Ключ — текст, храним последние
     *  [RATE_MEMO_MAX]. */
    private val fileBytesByText = LinkedHashMap<String, Pair<Float, Long>>()

    /** Сколько пар «одна фраза на двух скоростях — одинаковый размер» набралось
     *  подряд и писали ли уже итог за эту сессию. */
    private var rateIgnoredPairs = 0
    private var rateIgnoredLogged = false

    /** Сколько тишины оставлять на стыке фраз, мс (msg5604).
     *
     *  Обрезка ([trimSilence]) снимает тишину, которую движок дописал по краям
     *  файла: у сетевых голосов Google её 518–680 мс на фразу, и без обрезки
     *  чтение шло «с паузами». Раньше остаток был прибит гвоздями (50 мс в
     *  голове + 83 мс в хвосте) — теперь его задаёт строка «Пауза между
     *  фразами» в настройках: значение делится между хвостом текущей фразы и
     *  головой следующей. 0 — срезать всю тишину, что дописал движок.
     *
     *  Чего настройка НЕ может: если движок паузу не молчанием, а интонацией
     *  (тянет последний слог) — тишины по краям нет вовсе, обрезка отступает
     *  (trimBail 9), и значение ничего не меняет. */
    var pauseKeepMs: Int = 130

    /** Громкость собственного звука (0..2; 1 = полная, как у системы).
     *  Умножается на системную громкость медиа. Применяется сразу к играющему
     *  предложению и к каждому следующему при старте.
     *
     *  26.09.2026: ползунок пускает до 200%, но плеер громче единицы не умеет —
     *  поэтому всё, что выше 100%, домножается в самом звуке при синтезе
     *  (см. trimSilence). Так тихий движок можно поднять, а не только убавить. */
    var volume: Float = 1f
        set(value) {
            val v = value.coerceIn(0f, 2f)
            val wasLoud = field > 1f
            field = v
            // Звучит ExoPlayer — громкость у него своя.
            runCatching { filePlayer.setVolume(v) }
            // 30.09.2026: выше 100% в ПРЯМОМ режиме движок не умеет — добавку
            // делает наш усилитель (см. [applyDirectBoost]).
            applyDirectBoost()
            if (wasLoud != (v > 1f)) {
                // Подстройка перешла через 100%: уже готовые фразы сделаны по
                // прежнему правилу — не играем их, иначе смена слышна не сразу.
                dropStaleReply()
            }
        }

    // ---------------- Усилитель прямого звука (30.09.2026) ----------------
    //
    // Приём взят у @Voice Aloud Reader: приложение заводит себе звуковой сеанс
    // (AudioManager.generateAudioSessionId), отдаёт его движку вместе с фразой
    // (KEY_PARAM_SESSION_ID) и вешает на этот сеанс LoudnessEnhancer.
    //
    //  Зачем. Ползунок громкости пускает до 200%. В файловом способе всё, что выше
    //  100%, домножается в самом звуке при синтезе (см. trimSilence) — работает,
    //  но требует пересборки готовых фраз. В прямом способе звук играет движок, и
    //  такого рычага у нас не было вовсе: параметр громкости движку больше единицы
    //  не передать, и тихий сетевой голос поднять было нечем. Усилитель живёт
    //  отдельно от звука: он прибавляет громкость уже играющему, и пересборка не
    //  нужна.
    //
    //  Что важно знать: усилитель умеет только ПРИБАВЛЯТЬ (убавляет по-прежнему
    //  параметр громкости), номер сеанса движок может и проигнорировать — тогда в
    //  прямом режиме ничего не меняется, вреда нет; на части прошивок эффект
    //  недоступен — тогда в журнал уходит строка, и мы больше не пробуем.

    /** Номер звукового сеанса, который отдаём движку. 0 — система не дала. */
    private var boostSession = 0
    private var boostEffect: LoudnessEnhancer? = null

    /** Усилитель не удался — второй раз не пробуем (в журнале уже сказано). */
    private var boostBroken = false

    /** Какая добавка уже объявлена в журнале: пишем только на изменение. */
    private var boostLoggedMb = Int.MIN_VALUE

    /** Сколько добавки просит ползунок, мБ. 0 — не выше 100%, добавка не нужна.
     *  Берём большее из двух громкостей (книги и реплик): сеанс у нас один. */
    private fun boostWantedMb(): Int = maxOf(
        if (volume > 1f) Math.round((volume - 1f) * 2400f) else 0,
        if (replyVolume > 1f) Math.round((replyVolume - 1f) * 2400f) else 0,
    )

    private fun boostSessionId(): Int {
        if (boostSession != 0) return boostSession
        boostSession = runCatching {
            (appContext.getSystemService(Context.AUDIO_SERVICE) as AudioManager)
                .generateAudioSessionId()
        }.getOrDefault(0)
        return boostSession
    }

    /** Привести усилитель в соответствие с ползунком. Зовётся на смену громкости
     *  и перед прямой речью — вызов безвреден и дёшев. */
    private fun applyDirectBoost() {
        val want = boostWantedMb()
        if (want <= 0) {
            if (boostLoggedMb != Int.MIN_VALUE) {
                runCatching { boostEffect?.enabled = false }
                Diag.log(appContext, "sound", "усилитель прямого звука выключен (громкость не выше 100%)")
                boostLoggedMb = Int.MIN_VALUE
            }
            return
        }
        if (boostBroken) return
        val session = boostSessionId()
        if (session <= 0) {
            boostBroken = true
            Diag.log(appContext, "sound", "усилитель прямого звука не вышел: система не дала звуковой сеанс")
            return
        }
        var e = boostEffect
        if (e == null) {
            val r = runCatching { LoudnessEnhancer(session) }
            e = r.getOrNull()
            if (e == null) {
                boostBroken = true
                Diag.log(appContext, "sound", "усилитель прямого звука недоступен: ${r.exceptionOrNull()}")
                return
            }
            boostEffect = e
            Diag.log(
                appContext, "sound",
                "усилитель прямого звука готов: сеанс $session, его же отдаю движку в параметрах speak"
            )
        }
        runCatching {
            e.setTargetGain(want)
            e.enabled = true
        }
        if (boostLoggedMb != want) {
            Diag.log(
                appContext, "sound",
                "усилитель прямого звука: добавка $want мБ (громкость ${Math.round(volume * 100)}%)"
            )
            boostLoggedMb = want
        }
    }

    private var selectedVoiceName: String? = null

    /** Вызывается на главном потоке, когда предложение дочитано до конца. */
    var onDone: (() -> Unit)? = null

    /** Возвращает ВСЕ куски фразы, которые прозвучат через [offset] фраз вперёд
     *  (1 — следующая), в порядке озвучки, или null, если книга кончилась.
     *  Зовётся на главном потоке, без побочных эффектов.
     *
     *  05.10.2026: возвращаем не один текст, а список кусков — у фразы с прямой
     *  речью их два и больше (слова автора и реплики), и каждый должен быть готов
     *  заранее и стоять в очереди на своём месте.
     *
     *  msg4472: параметр появился вместе с очередью заготовок. Раньше мы
     *  синтезировали ровно одну фразу вперёд, и каждая заминка движка (в логе
     *  тестера — 12–15 с раз в минуту-полторы, экран заблокирован) слышалась
     *  как пауза: играть было нечего. Теперь держим [PREFETCH_DEPTH] фраз
     *  готовыми, и заминка проходит незаметно — звук идёт из заготовок.
     *
     *  08.10.2026: вместе с текстом и позицией приходит НОМЕР КУСКА (третье
     *  значение) — ключ единицы речи (см. [Units.key]). Без него заготовка
     *  теряла своё место в порядке: куски одной фразы неотличимы по позиции. */
    var onNeedNext: ((Int) -> List<Triple<String, Long, Int>>?)? = null

    /** Стартовая позиция фразы, которая прозвучит сразу после позиции [pos] —
     *  или null, если дальше читать нечего (07.10.2026, см. [exoTopUp]).
     *
     *  Зачем: список у ExoPlayer играется по порядку, и заготовка, вставшая в
     *  него через одну фразу, звучит раньше очереди. Чтение считает фразы по
     *  «доиграла», уезжает вперёд, и та же фраза позже заказывается и звучит
     *  ВТОРОЙ раз (жалоба Сержа 07.10.2026 «фразы повторяются», журнал 00:35).
     *  Длину фразы и порядок знает только читалка — у неё и спрашиваем. */
    var onNeedAfter: ((Long) -> Long?)? = null

    val isReady: Boolean get() = ready

    // ——— СПИСОК ГОЛОСОВ СПРАШИВАЕМ В СТОРОНЕ (24.10.2026, сборка 260) ———
    //
    // Жалоба Сержа: «переключил синтезатор — приложение предлагает закрыть или
    // подождать». Телефон записал три зависания за вечер, и во всех трёх главный
    // поток стоял в `TextToSpeech.getVoices(...)`: это запрос к САМОМУ ДВИЖКУ по
    // binder'у, и медленный движок отвечает секундами. Пока он думает, мы не
    // рисуем экран и не принимаем касания — Android и показывает «закрыть или
    // подождать». Заодно из-за этого рвалась фраза: пока поток стоял, сторож
    // считал речь оборванной и заказывал её заново (её и слышно дважды).
    //
    // ПРАВИЛО: `tts.voices` с главного потока не спрашиваем НИКОГДА. Спрашиваем
    // [refreshVoices] отдельным потоком, а здесь держим последний полученный
    // список. [voices] теперь читается мгновенно и безопасно откуда угодно.

    /** Последний полученный от движка список голосов (см. [refreshVoices]). */
    @Volatile private var voiceCache: List<Voice> = emptyList()

    /** Один поток на все вопросы к движку о голосах: заказы к движку не должны
     *  копиться и мешать друг другу. */
    private val voiceIo: ExecutorService = Executors.newSingleThreadExecutor { r ->
        Thread(r, "bookvoice-voices").apply { isDaemon = true }
    }

    /** Дольше этого движок список голосов думать не должен — попадает в журнал
     *  (см. [refreshVoices]). */
    private val voicesSlowMs = 700L

    /** Спросить у движка список голосов. Ответ кладём в [voiceCache], [then]
     *  зовём на главном потоке — когда ответ пришёл или движок молчит. */
    fun refreshVoices(then: (() -> Unit)? = null) {
        val t = tts
        if (t == null || !ready) {
            then?.let { cb -> main.post { cb() } }
            return
        }
        voiceIo.execute {
            val from = SystemClock.elapsedRealtime()
            val list = runCatching { t.voices?.toList() }.getOrNull()
            // Пустой ответ не затирает прежний список: движок мог ответить «не
            // готово», а голоса, которые он называл раньше, никуда не делись.
            if (!list.isNullOrEmpty() || voiceCache.isEmpty()) voiceCache = list.orEmpty()
            // Строка для будущих разборов: сколько движок думал над списком. Если
            // однажды снова начнут приходить «закрыть или подождать», по ней сразу
            // видно, тот ли это запрос (см. шапку [voiceCache]).
            val took = SystemClock.elapsedRealtime() - from
            if (took > voicesSlowMs) {
                Diag.log(
                    appContext, "tts",
                    "движок отдавал список голосов $took мс — в стороне это пустяк, " +
                        "а на главном потоке было бы «закрыть или подождать»",
                )
            }
            main.post { then?.invoke() }
        }
    }

    val voices: List<Voice> get() = voiceCache

    /** Голоса ДВИЖКА РЕПЛИК — тем же правилом, что и [voiceCache]: спрашиваем в
     *  стороне ([refreshReplyVoices]), читаем мгновенно. */
    @Volatile private var replyVoiceCache: List<Voice> = emptyList()

    /** Спросить список голосов у движка реплик (в стороне от главного потока). */
    private fun refreshReplyVoices() {
        val t = replyTts ?: return
        if (!replyReady) return
        voiceIo.execute {
            val list = runCatching { t.voices?.toList() }.getOrNull()
            if (!list.isNullOrEmpty() || replyVoiceCache.isEmpty()) replyVoiceCache = list.orEmpty()
        }
    }

    /** Пакет системного движка по умолчанию (может быть null до инициализации). */
    val defaultEngine: String?
        get() = tts?.defaultEngine

    /** Все установленные движки: пары (пакет, название). */
    val engines: List<Pair<String, String>>
        get() {
            val merged = LinkedHashMap<String, String>()
            for ((pkg, label) in queryEngines(appContext)) merged.putIfAbsent(pkg, label)
            tts?.engines?.forEach { e ->
                val name = e.name ?: return@forEach
                val label = e.label?.takeIf { it.isNotBlank() } ?: name
                merged.putIfAbsent(name, label)
            }
            return merged.toList().sortedBy { it.second.lowercase() }
        }

    // ---------- Пайплайн «синтез в файл → играет плеер» ----------

    /** Каталог временных файлов синтеза. У КАЖДОГО экземпляра он свой
     *  (30.09.2026). Прежде каталог был один на всех, и временный плеер,
     *  который поднимается в панели «Голос» для пробы голоса, при закрытии
     *  вычищал его ЦЕЛИКОМ — вместе с заготовками читалки. В журнале Сержа
     *  (00:47:23) это ровно и видно: он на ходу менял голос реплик, прогремело
     *  «закрываю плеер», файл, уже отданный плееру чтения, исчез с диска —
     *  и на нём вышло «Source error» (см. [exoListener.onError]). */
    private val synthDir = File(
        File(appContext.cacheDir, "tts_speech"),
        "p${instanceSeq.getAndIncrement()}",
    ).apply {
        if (!exists()) mkdirs()
    }

    // ---------------- Файлы играет ExoPlayer (28.09.2026) ----------------

    /** Плеер Media3 (см. [FilePlayback]). Поднимается лениво. */
    private val filePlayer: FilePlayback by lazy { FilePlayback(appContext) }

    /** Сколько заготовок отдано ExoPlayer ВПЕРЁД от звучащей фразы, и счётчик
     *  заявок для него: по ним понимаем, есть ли что играть дальше. */
    private var exoAhead = 0
    private var exoSeq = 0L

    /** ЗЕРКАЛО того, что уже отдано ExoPlayer и ещё не доиграло, в порядке
     *  звучания (первая — та, что звучит сейчас). Нужно затем, чтобы при вопросе
     *  чтения «играй вот эту фразу» понимать: она уже стоит впереди (тогда просто
     *  ждём) или её в списке нет (тогда выбрасываем хвост и дописываем её).
     *  Без него приходилось перезапускать список, и всё, что впереди, гибло —
     *  это и была потеря текста в сборке 187. */
    private val exoPending = ArrayDeque<Prepared>()

    /** Темп ФАЙЛА, который звучит сейчас. Движок пишет файл уже на нужной
     *  скорости ([Prepared.rate]), поэтому плееру остаётся только довести темп до
     *  нынешнего ползунка: играть такой файл на самой скорости — значит применить
     *  её дважды. Жалоба Сержа «словил очередную глюк после кручения скорости»
     *  (29.09.2026) — про это: в списке рядом лежали файлы, сделанные на 0.9, 1.2
     *  и 1.8, а плеер тянул их все на 1.2. */
    private var exoPlayingRate = 1f

    /** Тон ФАЙЛА, который звучит сейчас: движок записал его на этой высоте голоса,
     *  и плееру задаётся отношение «нужный тон / тон файла» ([exoSyncSpeed]).
     *  29.09.2026: без этого смена тона слышна только со следующей фразы. */
    private var exoPlayingPitch = 1f

    /** Тон, на котором записан файл — по имени файла (движок пишет файл уже с
     *  нужной высотой голоса, см. [pitch]). Набор подчищаем, когда разрастается:
     *  имена короткие, но за долгое чтение их набирается много. */
    private val filePitches = HashMap<String, Float>()

    private fun rememberFilePitch(name: String, pitch: Float) {
        if (filePitches.size > 400) filePitches.clear()
        filePitches[name] = pitch
    }

    private fun filePitchOf(f: java.io.File): Float = filePitches[f.name] ?: 1f

    /** Какая высота голоса нужна этой роли: у реплик своя. */
    private fun pitchFor(role: Pending.Role): Float =
        if (role == Pending.Role.REPLY) replyPitch else pitch

    /** Сторож «звук не начался»: молчание лечим прямой речью. */
    private var exoStartToken = 0

    /** Сторож «звука нет, а читать должны» (см. [armSoundWatch]). */
    private var soundWatchToken = 0

    /** Последний текст, который попросили говорить. */
    private var currentText: String? = null
    private var currentPos: Long = -1L

    /** Номер куска того, что попросили говорить (см. [Units.key]). */
    private var currentPart = 0

    /** Текст, чей синтез ещё идёт, а по завершении его надо СРАЗУ играть
     *  (speak() попросил, готового файла не было). */
    private var awaitingPlayText: String? = null
    private var awaitingPos: Long = -1L

    /** Номер куска той фразы, которую ждёт чтение (см. [isAwaited]). -1 — «любой
     *  кусок этой позиции»: так ставят там, где кусок неизвестен, и это
     *  безопаснее, чем не сыграть жданную фразу вовсе. */
    private var awaitingPart = -1

    /** Это та единица речи, которую ждёт чтение? Сверяем и кусок: у фразы с
     *  прямой речью кусков несколько, и по одной позиции они неразличимы. */
    private fun isAwaited(p: Pending): Boolean =
        p.text == awaitingPlayText && p.pos == awaitingPos &&
            (awaitingPart < 0 || p.part == awaitingPart)

    /** Тексты, которые синтезируются впрок (пока играет другое предложение).
     *
     *  29.09.2026, просьба Сержа: «можем ли мы три фразы одновременно
     *  синтезировать, чтобы готовых фраз было больше». Раньше в работе была
     *  РОВНО ОДНА заготовка (одно поле вместо набора): движок получал заявку
     *  только после того, как отдавал предыдущую, и очередь наполнялась по одной.
     *  Теперь заявок в работе может быть несколько — столько, сколько мест в
     *  очереди ([maxInFlight]), и движок сам решает, делать их подряд или
     *  параллельно: у сетевых голосов он это умеет.
     *
     *  Порядок набора = порядок заказа = порядок звучания, поэтому набор
     *  упорядоченный. 05.10.2026: считаем ФРАЗЫ, а не куски, — у фразы с прямой
     *  речью кусков два и больше, и они занимают одну позицию.
     *
     *  23.10.2026 (рефакторинг «текст — не опознание»). Отдельного набора здесь
     *  больше НЕТ: единственный источник правды о заявках — [pending]. Раньше тут
     *  лежала карта «ТЕКСТ → позиция», и в книге с одинаковыми репликами («— Да.»)
     *  она путала две разные фразы: вторую не заказывали, а ответ движка
     *  приписывали не той заявке. Теперь «в работе» — это заявка с ключом единицы
     *  речи ([Pending.key]) и признаком «заказана впрок» ([Pending.prefetch]),
     *  а не текст. */
    private fun fileInFlight(key: Long): Pending? =
        if (key < 0) {
            null
        } else {
            pending.values.firstOrNull {
                it.kind == Pending.Kind.FILE && !it.cancelled && it.key == key
            }
        }

    /** Заявка на файл для единицы БЕЗ места в книге (служебная фраза, страховка):
     *  ключа у неё нет (-1), и различить её можно только по тексту. Это
     *  единственное место, где текст остаётся опознанием, — и только потому, что
     *  у такой единицы больше ничего нет. Фразы книги сюда не попадают. */
    private fun fileInFlightText(text: String): Pending? =
        pending.values.firstOrNull {
            it.kind == Pending.Kind.FILE && !it.cancelled && it.pos < 0 && it.text == text
        }

    /** Какая-либо заявка на файл по этой единице уже в работе. */
    private fun fileInFlightAny(pos: Long, part: Int, text: String): Pending? {
        val key = Units.key(pos, part)
        return fileInFlight(key) ?: if (key < 0) fileInFlightText(text) else null
    }

    /** Сколько заявок на файл сейчас в работе (для журнала). */
    private fun fileInFlightCount(): Int =
        pending.values.count { it.kind == Pending.Kind.FILE && !it.cancelled }

    /** Ключ той единицы речи, которую сейчас ЖДЁТ чтение; -1 — никто не ждёт.
     *  [awaitingPart] = -1 означает «любой кусок этой позиции» — тогда считаем
     *  нулевой (нужно только для сверок вроде «звучащая ли это единица»). */
    private fun awaitingKey(): Long =
        if (awaitingPlayText == null) -1L else Units.key(awaitingPos, awaitingPart.coerceAtLeast(0))

    /** Сколько заявок держим у движка одновременно. У сетевого — все места
     *  очереди (в этом весь смысл: файлы готовятся, пока звучит текущая фраза),
     *  у локального по-прежнему одна: он готовит файл за доли секунды, и
     *  несколько заявок разом только путали бы сторожа молчания. */
    private val maxInFlight: Int get() = if (netSynth) prefetchDepth else 1

    /** Заранее подготовленная фраза (см. [prewarm]): она одна и только она —
     *  очередь впрок, пока чтение не идёт, не растёт. */
    private var prewarmOnly = false

    /** Фраза, сохранённая паузой для мгновенного продолжения: файл уже готов и
     *  движку не нужно синтезировать её второй раз (см. [pauseKeepingPhrase]). */
    private var keptPhrase: Prepared? = null

    /** С какого места продолжать сохранённую паузой фразу: у ExoPlayer позиция
     *  точная, и повторять начало фразы незачем. */
    private var keptPositionMs = 0L

    /** Последние сыгранные фразы: их звук НЕ стирается сразу, как было раньше, а
     *  ждёт в этом кэше (07.10.2026, просьба Сержа «давай сделаем только второе» —
     *  кэш двух-трёх последних фраз; мысль взята у MyTTS, где сыгранный звук
     *  держат и играют из памяти без нового синтеза).
     *
     *  Зачем. «Повторить фразу», шаг назад («Пред.») и продолжение после паузы
     *  сейчас заказывают фразу у движка ЗАНОВО: на MyTTS это доли секунды, на
     *  TeraTTS — секунды, и человек слышит тишину там, где просто хотел услышать
     *  ещё раз. Из кэша звук идёт сразу.
     *
     *  Держим [PLAYED_CACHE_MAX] штук: повтор и шаг назад — это одна-две фразы,
     *  а каждая занимает до ~1 МБ (файл 24 кГц). Каталог тот же временный
     *  ([synthDir]) и при закрытии читалки стирается целиком, поэтому за память
     *  телефона можно не следить: больше трёх файлов тут не живёт. */
    private val playedCache = ArrayDeque<Prepared>()

    /** Очередь уже синтезированных фраз — готовы к мгновенному старту, в том
     *  порядке, в каком прозвучат (msg4472). Раньше здесь лежала ровно одна
     *  заготовка: её хватало на паузу между фразами, но не на заминку движка,
     *  которая длится дольше самой фразы.
     *
     *  [rate] — скорость, которой сделан файл (24.09.2026). Раньше сверять её
     *  было негде, и после смены скорости до трёх фраз доигрывали прежним
     *  темпом; теперь такая заготовка выбрасывается, а не звучит. */
    private data class Prepared(
        val text: String,
        val file: File,
        val rate: Float,
        /** Чей голос сделал заготовку: у реплик своя скорость, и «прежней
         *  скорости» надо сверять со СВОЕЙ, а не с книжной (26.09.2026: из-за
         *  этого встык выбрасывал каждую репликовую заготовку — в журнале
         *  Сержа 195 отказов против 2 удачных прицепок, и это слышалось
         *  паузами на каждой реплике). */
        val role: Pending.Role = Pending.Role.MAIN,
        /** Номер заявки, по которой сделан файл (30.09.2026). Нужен, чтобы
         *  отдавать фразы плееру в порядке ЗАКАЗА, а не в порядке готовности:
         *  книга и реплики синтезируются разными движками, и медленная реплика
         *  иначе приезжает после следующей книжной фразы (см. [exoTopUp]). */
        val req: Long = 0L,
        /** Позиция фразы в книге (глава * 1 000 000 + предложение). Нужна, чтобы
         *  НЕ путать одинаковые по тексту фразы из разных мест книги (30.09.2026,
         *  жалоба Сержа «читал „Письмо в ЖЭК“ дважды»: защита от повторов сверяла
         *  только текст и выбрасывала соседнее «Еще через год мужики сказали:»
         *  как дубликат, от этого порядок сбивался и уже прочитанное звучало вновь). */
        val pos: Long = -1L,
        /** Номер КУСКА фразы (08.10.2026, см. [Units.key]): 0 — сама фраза
         *  (или её первый кусок), 1 и дальше — слова автора и реплики, «хвост»
         *  после укороченной первой фразы. Вместе с [pos] даёт ключ единицы речи,
         *  по которому теперь идёт и опознание, и порядок. */
        val part: Int = 0,
    ) {
        /** Ключ единицы речи — опознание и порядок (см. [Units.key]). */
        val key: Long get() = Units.key(pos, part)
    }

    private val readyQueue = ArrayDeque<Prepared>()

    /** Сколько фраз держим готовыми. Три — это 8–15 с звука при фразе в 4–6 с,
     *  то есть ровно длина заминок из лога тестера (12–15 с). Больше не нужно:
     *  растёт только задержка реакции на прыжок по тексту.
     *
     *  29.09.2026: у сетевого движка пробовали пять мест — глубину вернули к
     *  трём. Дело не в числе мест, а в том, что заявок в работе была одна
     *  (см. [maxInFlight]): теперь их столько же, сколько мест в очереди, и
     *  файлы готовятся, пока звучит текущая фраза.
     *
     *  06.10.2026: число вынесено в опытные настройки ([ExpertPrefs.prefetch]) —
     *  по умолчанию те же три, но владелец может уменьшить (меньше греется
     *  процессор у локального нейродвижка) или увеличить (ровнее стыки). Читаем
     *  настройку каждый раз, а не один раз при создании: значение меняется на
     *  ходу, из окна настроек. */
    private val prefetchDepth: Int get() = ExpertPrefs.prefetch(appContext)

    /** Сколько фраз держать у движка впереди в ПРЯМОМ чтении.
     *
     *  06.10.2026 (разбор журналов с движком MultiTTSLexx). Обычно это
     *  [prefetchDepth]: движок берёт фразы подряд, и стык выходит без паузы.
     *  Но есть движки-прослойки (MultiTTSLexx), которые играют звук САМИ и
     *  отчитываются о фразе раньше, чем она дозвучала. Им запас вперёд не нужен
     *  и вреден: на пачке фраз чтение убегало вперёд на главу (журнал 18:07:32 —
     *  тридцать фраз за полсекунды). Такому движку отдаём ровно одну фразу и
     *  следующую — только по «эта закончилась», как это делает FBReader (там
     *  такого запаса нет вовсе: каждая фраза посылается с очисткой очереди).
     *
     *  Решение принимается по пометке пары ([markedPairNoFiles]) — то есть по
     *  факту, а не по имени движка. Руками это можно перебить в опытных
     *  настройках ([ExpertPrefs.OnePhrase]). */
    private val directAhead: Int
        get() = when (ExpertPrefs.onePhrase(appContext)) {
            ExpertPrefs.ONE_ALWAYS -> 1
            ExpertPrefs.ONE_NEVER -> prefetchDepth
            else -> if (markedPairNoFiles) 1 else prefetchDepth
        }

    private var reqSeq = 0L
    private val pending = HashMap<Long, Pending>()

    /** Очередь фраз, ОТДАННЫХ движку в альтернативном способе (прямая речь),
     *  в порядке звучания; здесь только заявки вида [Pending.Kind.DIRECT].
     *
     *  msg (23.09.2026, просьба Сергея: «если синтезатору посылаешь предложение
     *  за предложением, может, читает всё без пауз»). Раньше в этом режиме мы
     *  отдавали движку ровно одну фразу и ждали «закончил» — на стыке слышалась
     *  пауза, а если движок молчал, мы считали срок по длине фразы. Теперь
     *  держим у движка впереди [prefetchDepth] фраз: он берёт их подряд, пауз
     *  нет, а срок нужен только один — на всю очередь (см. [armDirectWatch]).
     *
     *  Место в книге от очереди не страдает: каждая фраза отдаётся со своим
     *  номером, движок сообщает «закончил» по каждой отдельно, и закладку
     *  читалки двигает тот же [onDone], что и раньше. */
    private val directQueue = ArrayDeque<Long>()

    /** Очередь движка встала из-за того, что поднимается движок реплик:
     *  заказ повторим сами (27.09.2026, см. [retryDirectLater]). */
    private var directWaitReply = false

    /** Почему движок НЕ взял фразу в прямой очереди (24.10.2026, см.
     *  [queueDirect] и [speakDirectQueued]): «не готов», «отказался (код 3)» и
     *  т. п. Нужна для журнала: без неё жалоба «книжка убежала» разбиралась
     *  догадками — в журнале не было ни одной строки про отказ. */
    private var directRefusedReason: String? = null

    /** Заявка фразы, которую чтение назвало ПОСЛЕДНЕЙ, и текст фразы, которая
     *  ЗВУЧИТ прямо сейчас (29.09.2026).
     *
     *  Нужны, потому что очередь и место чтения двигаются вразнобой: движок берёт
     *  фразу из своей очереди и сообщает «начал» раньше, чем до нас дошло «доиграла»
     *  предыдущей, — а место чтения сдвигает именно оно. Из-за этого [topUpDirectQueue]
     *  считал, сколько фраз стоит впереди, по одному лишь размеру очереди, и мог
     *  заказать ту же фразу второй раз: в журнале Сержа (13:41:28) фраза в 80 знаков
     *  попала в очередь дважды, прозвучала дважды, а следующую мы потом оборвали
     *  командой «стоп» — на слух это и есть «бред с речью». */
    private var directAskedId: Long? = null
    private var directSpeakingText: String? = null

    /** КАКАЯ ЕДИНИЦА РЕЧИ звучит прямо сейчас ([Units.key]): место и кусок.
     *  23.10.2026, рефакторинг прямого пути. До него прямой путь опознавал фразы
     *  по ТЕКСТУ: короткие реплики в книгах повторяются дословно («— Да.»,
     *  «— Нет.»), и по тексту нельзя понять ни «это та же фраза», ни «это уже
     *  другая». Теперь и сверки, и отчёт «доиграла» идут по ключу, как в файловом
     *  пути. -1 — фраза без места (служебная, страховка): тогда опознание по тексту,
     *  другого не остаётся. */
    private var directSpeakingPos = -1L
    private var directSpeakingPart = 0

    /** Ключ звучащей единицы; -1 — места нет (см. [directSpeakingPos]). */
    private val directSpeakingKey: Long get() = Units.key(directSpeakingPos, directSpeakingPart)

    /** Куски ТЕКУЩЕЙ фразы, которые чтение попросило прочитать после головы
     *  (слова автора, хвост реплики, «хвост» после укороченной фразы).
     *
     *  Зачем помнить. Прямой путь отдаёт движку фразу ЦЕЛИКОМ — сначала голову,
     *  потом эти куски, — и только потом заказывает следующие фразы. Без этого
     *  хвост попадал в очередь ПОСЛЕ следующей фразы, и чтение, попросив его,
     *  гасило очередь движка (`tts.stop()`) посреди чужой речи: на слух — фраза
     *  обрывается и начинается заново. Здесь же эти куски переживают смену
     *  скорости в прямом чтении (см. [restartDirectForRate]). */
    private var currentRest: List<String> = emptyList()

    /** Заявка, которую [queueDirect] отдала движку последней: по ней чтение и
     *  [directAskedId] узнают, какая фраза считается «текущей» у движка. */
    private var lastDirectQueuedId: Long? = null

    /** Скорость сменилась, а очередь движка отдана прежним темпом
     *  (см. [onDirectRateChanged]). */
    private var directRateStale = false

    /** Смена скорости ждёт, пока человек отпустит ползунок: пока его двигают,
     *  перечитывать фразу на каждом шаге незачем (см. [restartDirectForRate]). */
    private val directRateRunnable = Runnable { restartDirectForRate() }

    /** До какого знака фразы дошёл сетевой движок ([onRangeStart] слушателя).
     *  Нужно для журнала: по этой метке видно, ГДЕ он запнулся (жалоба
     *  05.10.2026 «пауза после слова „еду“», журнал 21:52). */
    private val directHeardTo = HashMap<Long, Int>()

    /** Засечки кусков речи для журнала перерывов внутри фразы (см. [onRangeStart]):
     *  время последнего сообщения и его знаки. Нужны, чтобы назвать ЗНАКИ, на
     *  которых встала пауза (просьба Сержа 06.10.2026). */
    private val directRangeAt = HashMap<Long, Long>()
    private val directRangeChunk = HashMap<Long, Long>()

    // ---------- Сторож молчания (msg4077) ----------

    /** Движок или плеер могут не отозваться ВООБЩЕ: в логе пользователя
     *  (RMX3472, Android 14, v0.4.24) чтение встало на «старт чтения (предл. 131)»
     *  и дальше ни звука, ни ошибки — ни `onDone`, ни `onError`. Ждать вечно
     *  нельзя: читалка замолкает насовсем. Токены гасят только свой сторож —
     *  событие на одном этапе не отменяет надзор за другим.
     *
     *  29.09.2026: надзор за синтезом у сетевого движка ведётся ПО КАЖДОЙ
     *  заявке отдельно — заявок в работе несколько. Раньше токен был один, и
     *  взведение надзора за следующей заявкой гасило надзор за предыдущей:
     *  одна из фраз оставалась без сторожа вовсе. */
    private val synthWatchTokens = HashMap<String, Long>()
    private var directWatchToken = 0L

    /** Перезапусков движка подряд из-за молчания (сбрасывается удачной речью). */
    private var retriesInRow = 0

    /** Сколько фраз ПОДРЯД движок не дал вовсе — ни файла со звуком, ни прямой
     *  речи (см. [noteSilentPhrase]). Сбрасывается, как только прозвучала любая
     *  фраза. */
    private var silentInRow = 0

    /** Позиция первой из этих фраз: с неё продолжится чтение, когда движок
     *  оживёт (или когда человек сам вернётся к чтению). */
    private var silentFromPos = -1L

    /** Сколько раз ПОДРЯД движок вернул ОТКАЗ синтеза (ошибку). Это не молчание:
     *  отказ — ответ движка, и двух подряд достаточно, чтобы сказать человеку,
     *  что синтезатор не работает (16.10.2026, сборка 264x, см. [noteSynthError]).
     *  Сбрасывается, когда фраза правда прозвучала. */
    private var errorInRow = 0

    /** Первая фраза после начала чтения ещё не прозвучала: её ждём коротко (см.
     *  [noteSilentPhrase]). Ставится на холодном старте, снимается, когда фраза
     *  прозвучала или чтение встало. */
    private var coldPhrasePending = false

    /** Движок перестал отвечать — чтение встало, но и вперёд не идёт. Зовётся с
     *  позицией, на которой кончился звук ([silentFromPos]).
     *
     *  05.10.2026, журнал 22:43 (жалоба Сержа: «книжка очень быстро побежала
     *  вперёд»). У него заглючил TeraTTS: на КАЖДУЮ заявку движок мгновенно
     *  отвечал «готово», файла не писал, а прямая речь отвечала отказом. Мы
     *  каждую такую фразу молча пропускали и шли дальше — за 9 секунд чтение
     *  ушло с главы 6 на главу 21 (тысячи фраз, в журнале 530 КБ), а человек не
     *  услышал ни звука и не узнал, что случилось. Теперь: одна пропущенная
     *  фраза — как было; две подряд — поднимаем движок заново; пять подряд —
     *  останавливаем чтение, говорим об этом вслух и оставляем место там, где
     *  звук кончился. */
    var onEngineSilent: ((Long) -> Unit)? = null

    /** Сетевой ли движок с выбранным голосом (29.09.2026).
     *
     *  Жалоба Сержа: с сетевым синтезатором (MultiTTS, голос mstrans-…) в
     *  ОБЫЧНОМ режиме озвучки «громадные паузы», а в альтернативном —
     *  нормально. Журнал 01:13 объяснил: сетевой голос готовит файл за 2–4 с
     *  вместо долей секунды, наш сторож молчания считал это обрывом,
     *  переспрашивал фразу, дважды перезапускал движок (а перезапуск выбрасывал
     *  заявку, которая как раз была в пути) и в итоге бросал фразу на прямую
     *  речь — 14 с на фразу вместо трёх. За те же 40 с в журнале четыре фразы
     *  вместо шестнадцати.
     *
     *  Поэтому у сетевого сроки ожидания длиннее, а перезапуска движка нет
     *  вовсе. У локальных движков всё остаётся как было: они и работают. */
    private var netSynth = false

    /** Про сетевой ли движок ЗАЯВИЛ САМ (флаг голоса) — в отличие от
     *  [netSynth], куда входит и наша пометка «медленный». Нужно понять, надо
     *  ли ещё учиться: заявленному сетевому пометка не нужна. */
    private var netDeclared = false

    // ---------- Сроки ожидания: одно место на все «сколько ждать» ----------
    //
    // 05.10.2026, упрощение (Серж: «не перемудрили ли мы с нагромождением кучи
    // правил»). До этого сроки лежали в девятнадцати константах, и каждая ветка
    // сама выбирала «сетевой или локальный»: `if (netSynth) A else B` стояло в
    // восьми местах, так что правка одного числа требовала помнить про второе
    // (а иногда и про третье — у сетевого были свои границы). Теперь классов
    // движка два, ЛОКАЛЬНЫЙ и МЕДЛЕННЫЙ (сетевой или помеченный медленным,
    // см. [netSynth]), и все числа лежат в двух строках ниже. Числа перенесены
    // один в один: поведение то же, менялось только место.
    //
    // Почему у медленного всё длиннее, а перезапусков нет вовсе: перезапуск
    // движка выбрасывает заявку, которая уже в сети, и вместо трёх секунд
    // выходит четырнадцать (журнал Сержа 01:13). Разбор по каждому числу —
    // docs/HISTORY.md, сборки 236-245.

    /** Сроки ожидания одного класса движка. Поля названы по вопросам, на
     *  которые отвечают, а не по прежним константам. */
    private data class Timing(
        /** Окно прогрева нового голоса: движок поднимает голос, не трогаем. */
        val warmupMs: Long,
        /** Окно терпения на холодный старт: прыжок, начало чтения, смена голоса. */
        val coldStartMs: Long,
        /** Сколько ждать, что движок НАЧНЁТ прямую фразу (без сигнала «начал»). */
        val directStartMs: Long,
        /** Запас и хвост к расчётному времени звучания в прямом чтении. */
        val directFactor: Float,
        val directTailMs: Long,
        /** Сколько движку писать фразу в файл: доля времени звучания и границы. */
        val synthFactor: Float,
        val synthMinMs: Long,
        val synthMaxMs: Long,
        /** Срок сторожа после переспроса фразы. */
        val reaskMs: Long,
        /** Своя оценка темпа речи, пока нет замера: знаков в секунду. */
        val charsPerSec: Float,
        /** Сколько движок пишет ОДИН знак, мс (0 — не считаем: у сетевого своё). */
        val expectMsPerChar: Long,
        /** Срок для заявки, стоящей в очереди за другими (0 — ветка не наша). */
        val queueMs: Long,
        /** Сколько раз подряд можно перезапустить движок (0 — нельзя вовсе). */
        val restarts: Int,
        /** После скольких молчащих фраз подряд поднимаем движок заново. */
        val silentRestartAt: Int,
        /** После скольких молчащих фраз подряд встаём и говорим человеку. */
        val silentStopAt: Int,
    )

    /** Локальный движок: голос уже на устройстве, фразы пишутся долями секунды
     *  (13-секундная фраза собралась за 0,95 с), потерянную заявку лечит
     *  переспрос и перезапуск. Срок на старт прямой фразы — две секунды: движок
     *  подаёт сигнал «начал говорить» за доли секунды, и Сергей 23.09.2026
     *  попросил короче («6 секунд — это очень много»); было 180 с на всё, то есть
     *  три минуты тишины.
     *
     *  17.10.2026 (просьба Сержа: «если локальный синтезатор, то не делаем такую
     *  большую паузу, если он не читает», а потом «давай локальный поменьше ещё»):
     *  холодный старт 8 → 5 с (первый заход), окно прогрева 6 → 3 с, ожидание файла 6 → 3 с,
     *  старт прямой фразы 2 → 1,5 с, переспрос 1 → 0,8 с, а встаём уже после ТРЁХ
     *  молчащих фраз (было пять). Локальный движок отвечает за доли секунды — по
     *  журналам 13-секундная фраза пишется за 0,95 с, — поэтому три с половиной
     *  секунды на первую фразу это уже «сбоит», а не «думает».
     *
     *  ЧТО НЕ РЕЖЕМ: замер пары (`firstPrepMs`) по-прежнему может поднять окно —
     *  если движок один раз честно готовил фразу долго, срок берётся от замера
     *  плюс три секунды, а не из этой таблицы. Поэтому TeraTTS с его 4,6 с на
     *  длинную фразу и MyTTS с двадцатью секундами на первую не наказываются. */
    private val LOCAL_TIMING = Timing(
        warmupMs = 3_000L,
        coldStartMs = 5_000L,
        directStartMs = 1_500L,
        directFactor = 1.4f,
        directTailMs = 3_000L,
        synthFactor = 0.25f,
        synthMinMs = 1_500L,
        synthMaxMs = 3_000L,
        reaskMs = 800L,
        charsPerSec = 15f,
        expectMsPerChar = 20L,
        queueMs = 0L,
        restarts = 2,
        silentRestartAt = 2,
        silentStopAt = 3,
    )

    /** Сетевой голос и помеченный медленным: заявка идёт сетевым кругом, первая
     *  после смены голоса доспевает за 5-6 с, файл готовится 2-4 с. Ждём долго
     *  и движок НЕ перезапускаем ([Timing.restarts] равен нулю). Старт прямой
     *  фразы — восемь секунд: в журнале 02:39 сетевая фраза не начиналась и за
     *  две, хотя просто готовилась.
     *
     *  17.10.2026 (Серж: «а если сетевой синтезатор долго не говорит, то немножко
     *  меньше»): холодный старт 12 → 9 с, прогрев 12 → 10 с, старт прямой фразы
     *  8 → 6 с, ожидание очереди 20 → 15 с, встаём после четырёх молчащих фраз
     *  (было пять). Это подстраховка, а не основа: у пары с замером срок берётся
     *  от замера (`firstPrepMs + 3 с`), поэтому медленный движок по-прежнему
     *  получит своё время. */
    private val SLOW_TIMING = Timing(
        warmupMs = 10_000L,
        coldStartMs = 9_000L,
        directStartMs = 6_000L,
        directFactor = 1.3f,
        directTailMs = 6_000L,
        synthFactor = 0.5f,
        synthMinMs = 5_000L,
        synthMaxMs = 8_000L,
        reaskMs = 3_000L,
        charsPerSec = 5f,
        expectMsPerChar = 0L,
        queueMs = 15_000L,
        restarts = 0,
        silentRestartAt = 2,
        silentStopAt = 4,
    )

    /** 24.10.2026: срок ожидания СЕТЕВОГО голоса, выставленный человеком
     *  (строка за дверью, как «Network timeout (sec, 0: default)» у @Voice).
     *  0 — таблицу не трогаем, живём по [SLOW_TIMING]. */
    private var netTimeoutMs: Long = 0L

    /** 24.10.2026: сколько раз повторять запрос к сетевому голосу, прежде чем
     *  считать, что он не отвечает (у @Voice «Retry count, if error downloading»
     *  1…10). 1 — как было: одна попытка и перезапуск движка. */
    private var netRetries: Int = 1

    /** Число повторов запроса из настроек (1…10). */
    var retries: Int
        get() = netRetries
        set(value) {
            val v = value.coerceIn(1, 10)
            if (v == netRetries) return
            netRetries = v
            Diag.log(appContext, "voice", "повторов запроса к сетевому голосу: $v")
        }

    /** Сколько повторов уже израсходовано в этой череде молчащих фраз. */
    private var silentRetries = 0

    /** Срок ожидания сетевого голоса из настроек; меняется на ходу. */
    var netTimeout: Long
        get() = netTimeoutMs
        set(value) {
            val v = value.coerceIn(0L, NET_TIMEOUT_MAX_MS)
            if (v == netTimeoutMs) return
            netTimeoutMs = v
            Diag.log(
                appContext, "voice",
                if (v == 0L) "срок сетевого голоса: по таблице (${SLOW_TIMING.coldStartMs} мс)"
                else "срок сетевого голоса из настроек: $v мс"
            )
        }

    /** Сроки по нынешнему движку с нынешним голосом. 24.10.2026: у сетевого
     *  голоса окно прогрева и холодный старт можно задать настройкой — иначе
     *  «долгие паузы» на медленной сети не подкрутить (как у @Voice:
     *  «Network timeout (sec, 0: default)»). */
    private val timing: Timing
        get() {
            if (!netSynth) return LOCAL_TIMING
            if (netTimeoutMs <= 0L) return SLOW_TIMING
            val ms = netTimeoutMs
            return SLOW_TIMING.copy(warmupMs = ms, coldStartMs = ms)
        }

    /** Сколько раз подряд движок не отдал фразу даже после переспроса и
     *  перезапусков. На втором таком разе помечаем его медленным — с этого
     *  момента к нему отношение как к сетевому. Одного раза мало: локальный
     *  движок иногда теряет одну заявку, и перезапуск для него — рабочая мера. */
    private var slowHits = 0

    /** Сетевой ли голос по его собственному флагу. Движки врут редко, но
     *  проверяем через runCatching: старые версии флага не имеют. */
    private fun voiceIsNetwork(v: Voice?): Boolean =
        runCatching { v?.isNetworkConnectionRequired == true }.getOrDefault(false)

    /** Ключ пометки «медленный»: движок и голос вместе. Голос в ключе не зря —
     *  в одном движке (MultiTTS, Google) сетевые и локальные голоса соседствуют,
     *  и пометка на сетевом не должна менять поведение локального. */
    private fun synthMark(): String = "${enginePackage ?: "системный"}|${selectedVoiceName ?: ""}"

    /** Пометки в настройках чтения — одно место на чтение и запись (упрощение
     *  05.10.2026: прежде три функции сами ходили в SharedPreferences, хотя
     *  делали одно и то же). Ключи и вид набора прежние, поэтому пометки,
     *  накопленные на телефоне, остаются в силе. */
    private fun marks(key: String): Set<String> = runCatching {
        appContext.getSharedPreferences("reader", Context.MODE_PRIVATE)
            .getStringSet(key, emptySet()) ?: emptySet()
    }.getOrDefault(emptySet())

    private fun putMarks(key: String, value: Set<String>) {
        runCatching {
            appContext.getSharedPreferences("reader", Context.MODE_PRIVATE)
                .edit().putStringSet(key, value).apply()
        }
    }

    /** Пометки «этот движок с этим голосом медленный»: ждём его по-сетевому. */
    private fun slowMarks(): Set<String> = marks(KEY_SLOW_SYNTH)

    /** Пометки «этому движку с этим голосом файлы не заказывать» — читаем его
     *  голосом напрямую (см. [netDirect]). */
    private fun directMarks(): Set<String> = marks(KEY_DIRECT_SYNTH)

    /** Сколько РАЗНЫХ голосов этого движка уже попали в пометку «файлов не
     *  отдаёт» (см. [markNetDirect]). Ключ пометки — «движок|голос», поэтому
     *  считаем по части до разделителя: движок в имени пакета разделителя не
     *  содержит.
     *
     *  30.09.2026 (сборка 227). Зачем считать по движку, а не по паре. У сетевых
     *  голосов одного движка (MultiTTS с голосами mstrans) файловый путь не
     *  работает НИ У ОДНОГО: движок просто не умеет synthesizeToFile. А пометка
     *  ставится на пару «движок + голос», поэтому каждый НОВЫЙ голос снова
     *  платил за пробу файла — в журнале Сержа 08:12 это ровно 5,1 с тишины
     *  перед первой фразой, и ещё 5,1 с перед второй, и только потом чтение шло
     *  без пауз. Два провалившихся голоса — уже приговор движку: третьему
     *  пробовать нечего. */
    private fun engineFileFailVoices(): Int {
        val eng = enginePackage ?: "системный"
        return directMarks().count { it.substringBefore('|') == eng }
    }

    /** У движка уже есть голос, не отдавший файл, а голос сам заявляет сеть:
     *  второй заход за файлом не делаем (см. [onSynthWatchdog]). Ставится в
     *  [applySpeedAndVoice]. */
    private var netSuspectEngine = false

    /** Запомнить, что файловый путь у этой пары «движок + голос» не работает, и
     *  перейти на прямую речь СРАЗУ, не дожидаясь перезапуска движка. */
    private fun markNetDirect(reason: String) {
        // Принудительный способ (см. [forceMode]) отменяет и опыт, и пометки:
        // что человек выбрал, тем и читаем. Иначе ручка «только файлом» на
        // помеченном движке сама же себя и отменяла бы.
        if (forceMode != ExpertPrefs.MODE_AUTO) {
            Diag.log(
                appContext, "tts",
                "движок не отдал файл ($reason), но способ выбран принудительно " +
                    "(${ExpertPrefs.forceModeLabel(forceMode)}) — пометку не ставлю, способ не меняю"
            )
            return
        }
        val key = synthMark()
        if (!directMarks().contains(key)) {
            // Оставляем как было: набор + ключ (порядок в наборе не важен).
            putMarks(KEY_DIRECT_SYNTH, directMarks() + key)
        }
        netFileFails = 0
        if (netDirect) return
        netDirect = true
        directWhyText = "движок не отдал файл ($reason)"
        // 24.10.2026: тихий поток сам не поднимаем (просьба Сержа), только
        // отмечаем причину в журнале — см. [KeepAwake.noteDirectNeedsSilence].
        KeepAwake.noteDirectNeedsSilence(appContext, "движок файлов не отдаёт — читаю его голосом")
        Diag.log(
            appContext, "tts",
            "движок файлов не отдаёт ($reason) — читаю его голосом напрямую, " +
                "как в альтернативном способе"
        )
        dropFilePipeline("переход на прямой способ")
    }

    /** Отменить всё файловое разом: заявки, надзоры, заготовки.
     *
     *  Переход на прямое чтение должен быть ЧИСТЫМ (29.09.2026). Мало перестать
     *  заказывать новые файлы: уже заказанные движок продолжит синтезировать и
     *  будет занят ими, пока мы ждём звука, — в журнале 02:30 из-за этого
     *  замолчала даже прямая речь (сторож насчитал 8 с на фразу в три секунды). */
    private fun dropFilePipeline(reason: String) {
        pending.entries.removeAll { (_, p) ->
            if (p.kind == Pending.Kind.FILE) {
                p.cancelled = true
                runCatching { p.file?.delete() }
                true
            } else {
                false
            }
        }
        forgetAllSynthWatches()
        clearPrefetch()
        Diag.log(appContext, "tts", "файловый конвейер выброшен ($reason)")
    }

    /** Решение «читаем напрямую?» по нынешней паре, пометкам и принудительной
     *  настройке. Одно место на оба входа: применение голоса
     *  ([applySpeedAndVoice]) и смену ручки ([applyForceMode]) — иначе слова в
     *  журнале и поведение разъедутся. */
    private fun decideDirectMode(): Pair<Boolean, String?> {
        val engineFails = engineFileFailVoices()
        val pairMarked = directMarks().contains(synthMark())
        // 06.10.2026 (журнал 21:38, «открыл книжку — она заговорила»). У движка
        // может не быть НАШЕГО голоса вовсе: у прослойки MultiTTSLexx голос один
        // и выбирает его она сама, поэтому в ключе пометки голос пустой. Прежняя
        // пометка на «движок|ru» тогда не совпадала, движок снова шёл файловым
        // путём и опять говорил сам. Раз голос нам неизвестен, судим по движку:
        // есть у него хоть один голос без файлов — этому тоже файлов не будет.
        // Так можно только при ПУСТОМ голосе: у MultiTTS сетевые голоса без
        // файлов, а локальные того же движка файлы отдают, и приговор движку
        // целиком сломал бы им файловый путь.
        val engineMarked = engineFails >= 1 && selectedVoiceName.isNullOrBlank()
        markedPairNoFiles = pairMarked || engineMarked
        engineMarkedNoFiles = engineMarked
        val now = when (forceMode) {
            ExpertPrefs.MODE_FILE -> false
            ExpertPrefs.MODE_DIRECT -> true
            ExpertPrefs.MODE_NET_DIRECT -> netDeclared
            else -> markedPairNoFiles || (netDeclared && engineFails >= ENGINE_NO_FILES_VOICES)
        }
        val why = when {
            !now -> null
            forceMode == ExpertPrefs.MODE_DIRECT ->
                "так выбрано в опытных настройках: только движком"
            forceMode == ExpertPrefs.MODE_NET_DIRECT ->
                "голос сам заявляет сеть, а в опытных настройках выбрано «сетевые — движком»"
            pairMarked -> "этому движку с этим голосом файлы не заказываю: помечено в прошлый раз"
            engineMarked -> "движок файлов не отдаёт (помечен на другом голосе, а свой " +
                "голос у него не выбирается)"
            else -> "движок не отдаёт файлы ни одним сетевым голосом (без файлов уже $engineFails)"
        }
        return now to why
    }

    /** Имя движка, по которому ищем принудительный способ чтения
     *  ([ExpertPrefs.forceMode]). Когда наш движок не выбран (читаем движком по
     *  умолчанию), берём его настоящее имя у системы: иначе профиль, поставленный
     *  этому движку в настройках, не нашёлся бы. */
    private fun modeEngine(): String? = enginePackage
        ?: runCatching { tts?.defaultEngine }.getOrNull()
        ?: ExpertPrefs.defaultEngine(appContext)

    /** Перечитать принудительный способ из опытных настроек (см. [forceMode]).
     *
     *  Зовётся на старте чтения и при применении голоса/движка: ручку меняют в
     *  окне настроек, а плеер живёт дольше одной книги. НА ХОДУ путь не меняем —
     *  смена на середине фразы означала бы обрыв звука; поэтому это отдельный
     *  вход, а не сеттер. */
    fun applyForceMode() {
        val now = ExpertPrefs.forceMode(appContext, modeEngine())
        if (now == forceMode) return
        val wasDirect = directMode
        forceMode = now
        val (netDirectNow, why) = decideDirectMode()
        netDirect = netDirectNow
        directWhyText = why
        Diag.log(
            appContext, "tts",
            "принудительный способ чтения: ${ExpertPrefs.forceModeLabel(now)}" +
                " (было ${if (wasDirect) "прямое чтение" else "файлы"})"
        )
        // Конвейер прежнего способа больше не нужен: его заявки всё равно не
        // прозвучат так, как ожидает читалка.
        switchPipeline(wasDirect)
    }

    /** Способ сменился (файлы ↔ прямой): выбросить конвейер прежнего пути, чтобы
     *  его заявки не спутали чтение, и включить тихий поток для прямого. Одно
     *  место на оба входа: [applyForceMode] и [applySpeedAndVoice]. */
    private fun switchPipeline(wasDirect: Boolean) {
        if (directMode && !wasDirect) {
            dropFilePipeline("переход на прямой способ чтения")
            KeepAwake.noteDirectNeedsSilence(appContext, "выбран прямой способ чтения")
        } else if (!directMode && wasDirect) {
            flushDirectQueue("переход на обычный способ чтения")
        }
    }

    /** Запомнить, что этот движок с этим голосом медленный. Дальше к нему
     *  отношение как к сетевому: ждём долго, движок не перезапускаем. Пометка
     *  переживает перезапуск приложения: иначе первый плохой случай в каждой
     *  книге начинался бы заново. */
    private fun markSlowSynth(reason: String) {
        val key = synthMark()
        if (slowMarks().contains(key)) return
        putMarks(KEY_SLOW_SYNTH, slowMarks() + key)
        // Переключаемся на сетевые сроки сразу, не дожидаясь смены голоса или
        // перезапуска движка: [applySpeedAndVoice] узнал бы о пометке только
        // тогда, а следующая фраза уже идёт.
        netSynth = true
        Diag.log(
            appContext, "tts",
            "движок помечен медленным ($reason): $key — жду его дольше, перезапуска не делаю"
        )
    }

    /** Снять пометку «этот движок с этим голосом медленный», если она есть
     *  (05.10.2026). Нужна она затем, что смену голоса мы раньше закрывали
     *  переспросом и перезапуском движка — и эти наши промахи честно копились в
     *  пометки. В журнале Сержа 16:51:54 движок TeraTTS уже был «помечен
     *  медленным» и от этого считался сетевым с длинными сроками и прямым
     *  чтением вместо файлов. Голос, ответивший сразу после смены, доказал
     *  обратное — пометку с него снимаем. Настоящая медлительность вернётся
     *  своей дорогой: две заминки подряд снова её поставят. */
    private fun forgetSlowMark(reason: String) {
        val key = synthMark()
        val known = slowMarks()
        if (!known.contains(key)) return
        putMarks(KEY_SLOW_SYNTH, known - key)
        Diag.log(appContext, "tts", "пометку «медленный» с этого голоса снимаю ($reason)")
    }

    /** Текст, который надо переспросить, когда движок поднимется после перезапуска. */
    private var retryAfterRestart: String? = null
    private var retryAfterRestartPos: Long = -1L
    private var retryAfterRestartPart = 0

    /** Фраза, которую надо перечитать ГОЛОСОМ движка, когда он поднимется после
     *  пересоздания соединения из-за смены скорости (см. [restartDirectForRate]).
     *  Отдельно от [retryAfterRestart]: тот перечитывает файлом, а тут движок
     *  файлов не отдаёт вовсе. */
    private var retryDirectAfterRestart: String? = null

    /** Куски фразы, которую надо перечитать после пересоздания соединения
     *  (см. [restartDirectForRate]): без них хвост фразы снова встал бы в очередь
     *  после следующих фраз и стоил бы `tts.stop()` посреди живой речи. */
    private var retryDirectAfterRestartRest: List<String> = emptyList()

    /** Сколько раз движок уже терял заявку на КОНКРЕТНЫЙ текст (msg4103): первый
     *  обрыв лечим повторной заявкой без перезапуска движка, второй — следующей
     *  мерой (перезапуск локального движка, прямая речь у сетевого). Пауза этот
     *  след НЕ сбрасывает (msg5309): иначе лестница мер начиналась бы заново на
     *  каждом «продолжить». Снимают его доспевший синтез и перезапуск движка
     *  ([resetPipeline]).
     *
     *  Почему счёт на каждый текст, а не одна общая ячейка (29.09.2026). Раньше
     *  здесь лежало одно поле `softRetriedText`, и удачный синтез ЛЮБОЙ другой
     *  фразы его обнулял. Журнал 08:48 показал, чем это кончается: заявку на
     *  фразу «Сафонова:…» движок потерял, мы её переспросили, тут же доспела
     *  соседняя фраза — метка стёрлась, и на втором обрыве той же фразы вместо
     *  перехода на прямую речь она была переспрошена снова. Чтение стояло молча
     *  6,5 с, пока Серж не тронул ползунок скорости, и предложение в итоге
     *  потерялось. Теперь счёт свой у каждого текста: соседняя фраза ему не указ. */
    private val synthMisses = HashMap<String, Int>()

    /** Сколько раз движок терял заявку на [text]. */
    private fun synthMissesOf(text: String): Int = synthMisses[text] ?: 0

    /** Забыть обрывы по [text]: синтез доспев, движок отозвался. */
    private fun forgetSynthMisses(text: String) {
        synthMisses.remove(text)
    }

    /** [rate] — скорость, с которой этот файл ЗАКАЗАН у движка (msg5979). Держим
     *  её при заявке, а не читаем текущую при завершении: смена скорости не
     *  выбрасывает уже готовые заготовки, и фраза из очереди могла быть
     *  синтезирована на прежней. */
    private class Pending(
        val kind: Kind,
        val text: String,
        val file: File?,
        val rate: Float = 1f,
        /** Чей голос читает фразу: основной или репликовый. Нужен сторожу:
         *  замолчавший движок реплик лечится не перезапуском основного. */
        val role: Role = Role.MAIN,
        /** Позиция фразы в книге (см. [Prepared.pos]). */
        val pos: Long = -1L,
        /** Номер куска фразы (см. [Prepared.part]). */
        val part: Int = 0,
    ) {
        enum class Kind { FILE, DIRECT }
        enum class Role { MAIN, REPLY }
        var cancelled = false

        /** Заявка заказана ВПРОК ([requestPrefetch], [prefetchRest], [prewarm]),
         *  а не по просьбе чтения. По этому признаку [synthFinished] решает, копить
         *  ли файл в [readyQueue] или считать синтез осиротевшим. Раньше это
         *  выяснялось по тексту в отдельном наборе — и одинаковые фразы путались. */
        var prefetch = false

        /** Ключ единицы речи (см. [Units.key]) — опознание заявки. */
        val key: Long get() = Units.key(pos, part)
    }

    /** Поколение запусков движка. Ответ об инициализации приходит от КОНКРЕТНОГО
     *  запуска, а слушатель у нас один на всех: без номера поколения ответ
     *  ПРЕЖНЕГО движка принимался за ответ нового. Так и получалось «проблема с
     *  переключением синтезаторов» (жалоба тестера): при смене движка мы гасим
     *  прежний (`shutdown`), а если он в этот момент ещё инициализировался, его
     *  ответ приходит с ошибкой — и мы объявляем ошибкой НОВЫЙ движок: тост
     *  «Движок не запустился, вернул системный» и откат на системный движок. */
    private var engineGen = 0L

    /** Ответ движка об инициализации. [gen] — какой запуск отвечает: ответ
     *  прежнего запуска (мы уже переключились) отбрасываем. */
    private fun onEngineInit(gen: Long, status: Int) {
        if (gen != engineGen) {
            Diag.log(
                appContext, "tts",
                "ответ прежнего запуска движка (поколение $gen из $engineGen, " +
                    "status=$status) — игнорирую: сейчас ${enginePackage ?: "системный"}"
            )
            return
        }
        val ok = status == TextToSpeech.SUCCESS && tts != null
        ready = ok
        // 0.4.82: ответ пришёл с успехом, но движок уже погашен (shutdown во
        // время запуска). Раньше это молчало и выглядело как «движок не
        // запустился» — теперь причина названа прямо.
        if (status == TextToSpeech.SUCCESS && tts == null) {
            Diag.log(
                appContext, "tts",
                "движок ${enginePackage ?: "системный"}: ответ пришёл, но плеер уже " +
                    "погашен (shutdown во время запуска) — считаю отказом"
            )
        }
        // 0.4.75: засечка «движок поднялся» — без неё в журнале не видно, чем
        // кончилось переключение синтезатора (в присланном журнале были только
        // последствия — страховка прямой речью и поздние голоса).
        Diag.log(
            appContext, "tts",
            "движок ${enginePackage ?: "системный"}: init status=$status, готов=$ok"
        )
        if (ok) {
            // 24.10.2026: строку про голоса и языки печатаем из ОТВЕТА, который
            // придёт в стороне (см. [refreshVoices]) — прежде [logVoiceLanguages]
            // сам спрашивал движок и вешал главный поток.
            tts?.setOnUtteranceProgressListener(object : UtteranceProgressListener() {
                // msg1818: засечка фактического старта произнесения движком —
                // для сопоставления с фразой TalkBack «управление мультимедиа».
                // 23.09.2026: этим же сигналом пользуется надзор за прямой
                // речью — до него срок ждём один, после него считаем по длине
                // фразы (см. directSpeechStarted).
                override fun onStart(utteranceId: String?) {
                    Diag.log(appContext, "tts", "onStart: движок начал речь ($utteranceId)")
                    // 07.10.2026: движок взялся за первую фразу — по этой засечке
                    // узнаём, сколько он её готовил (см. [noteFirstPrep]).
                    if (firstPrepFromMs != 0L) {
                        noteFirstPrep(SystemClock.elapsedRealtime() - firstPrepFromMs)
                    }
                    val id = utteranceId?.toLongOrNull()
                    main.post { directSpeechStarted(id) }
                }

                override fun onDone(utteranceId: String?) {
                    val id = utteranceId?.toLongOrNull() ?: return
                    main.post { synthFinished(id) }
                }

                @Deprecated("Deprecated in Java")
                override fun onError(utteranceId: String?) {
                    val id = utteranceId?.toLongOrNull() ?: return
                    main.post { synthFailed(id, -1) }
                }

                override fun onError(utteranceId: String?, errorCode: Int) {
                    val id = utteranceId?.toLongOrNull() ?: return
                    main.post { synthFailed(id, errorCode) }
                }

                // 05.10.2026: часть движков сама сообщает, какой кусок фразы
                // звучит. Если сообщает — по метке в журнале видно, до какого
                // знака дело дошло (см. [noteSpokenRate]). Кто не сообщает, тот
                // и не позовёт: метки просто не будет.
                //
                // 06.10.2026 (просьба Сержа: «смотри, какие где паузы происходят,
                // на каких знаках»): пишем в журнал ПЕРЕРЫВЫ между кусками речи —
                // движок готовит фразу кусками, и пауза слышна между ними. По
                // строке видно и сколько длился перерыв, и на каких знаках он
                // встал: «внутри фразы перерыв 1,8 с: говорил знаки 40…52, дальше
                // с 52…71». Обычные сообщения (их десятки на фразу) молчат, иначе
                // журнал распухнет; и первое сообщение показывает, через сколько
                // после «начал речь» пошёл звук.
                override fun onRangeStart(
                    utteranceId: String?, start: Int, end: Int, frame: Int,
                ) {
                    val id = utteranceId?.toLongOrNull() ?: return
                    if (end > (directHeardTo[id] ?: 0)) directHeardTo[id] = end
                    if (pending[id]?.kind != Pending.Kind.DIRECT) return
                    val now = SystemClock.elapsedRealtime()
                    val prevAt = directRangeAt.put(id, now)
                    val prevChunk = directRangeChunk.put(
                        id, (start.toLong() shl 32) or (end.toLong() and 0xffffffffL)
                    )
                    val text = pending[id]?.text ?: return
                    if (prevAt == null) {
                        val from = directStartedAt[id]
                        if (from != null) {
                            Diag.log(
                                appContext, "tts",
                                "звук пошёл через ${now - from} мс после «начал речь» " +
                                    "(фраза ${text.length} знаков)"
                            )
                        }
                        return
                    }
                    if (now - prevAt < RANGE_PAUSE_MS) return
                    val ps = (prevChunk!! shr 32).toInt()
                    val pe = prevChunk.toInt()
                    Diag.log(
                        appContext, "tts",
                        "внутри фразы перерыв ${"%.1f".format((now - prevAt) / 1000f)} с: " +
                            "говорил знаки $ps…$pe, дальше с $start…$end; " +
                            "фраза ${text.length} знаков «${text.take(50)}»"
                    )
                }
            })
            // msg3550: список голосов движок отдаёт не в момент init, а позже —
            // выбранный голос (в т.ч. свой у книги) в этот момент поставить
            // нечем. Публичного уведомления «список готов» в SDK нет (сборка
            // 0.4.25: setOnVoicesChangedListener не резолвится), поэтому
            // спрашиваем сами несколько раз.
            applySpeedAndVoice()
            // 24.10.2026: список голосов спрашиваем В СТОРОНЕ и только потом
            // ставим выбранный голос окончательно (см. [voiceCache]). Именно этот
            // запрос вешал главный поток на 5-7 секунд — телефон показывал
            // «закрыть или подождать».
            refreshVoices {
                logVoiceLanguages()
                if (voiceCache.isEmpty()) {
                    waitForVoices(voiceWaitSteps.size)
                } else {
                    applySpeedAndVoice()
                }
            }
            // Сторож (msg4077): движок перезапущен после молчания — переспросить
            // фразу, которую он не досказал. Скорость и голос уже применены
            // выше. Состояние «эту фразу ждут» восстанавливаем руками: start()
            // его обнулил (resetPipeline), а synthFinished играет только то, что
            // ждут.
            retryAfterRestart?.let { t ->
                retryAfterRestart = null
                currentText = t
                currentPos = retryAfterRestartPos
                currentPart = retryAfterRestartPart
                awaitingPlayText = t
                awaitingPos = retryAfterRestartPos
                awaitingPart = retryAfterRestartPart
                synthToFile(t, retryAfterRestartPos, retryAfterRestartPart)
            }
            // Пересоздали соединение ради смены скорости (см.
            // [restartDirectForRate]) — фразу перечитываем ГОЛОСОМ: файлов этот
            // движок не отдаёт. 23.10.2026: единицей речи целиком, вместе с её
            // кусками — иначе хвост фразы снова попал бы в очередь после
            // следующей фразы и стоил бы `tts.stop()` посреди живой речи.
            retryDirectAfterRestart?.let { t ->
                retryDirectAfterRestart = null
                currentText = t
                currentPos = retryAfterRestartPos
                currentPart = retryAfterRestartPart
                Diag.log(
                    appContext, "tts",
                    "движок поднят заново ради смены скорости — читаю фразу его голосом"
                )
                speakDirectQueued(
                    t, retryAfterRestartPos, retryAfterRestartPart,
                    userAsked = true, rest = retryDirectAfterRestartRest,
                )
                retryDirectAfterRestartRest = emptyList()
            }
        } else {
            retryAfterRestart?.let {
                retryAfterRestart = null
                Diag.log(appContext, "tts", "движок не поднялся после перезапуска (status=$status)")
            }
        }
        engineReadyCallback?.invoke(ok)
        engineReadyCallback = null
    }

    init {
        start(null)
        // Свои временные файлы от прошлого запуска процесса (номер экземпляра
        // повторяется) — чистим при старте. Чужие каталоги не трогаем.
        runCatching { synthDir.listFiles()?.forEach { it.delete() } }
    }

    /** Переключиться на движок [pkg] (null — системный по умолчанию). */
    fun setEngine(pkg: String?, onResult: ((Boolean) -> Unit)? = null) {
        if (pkg == enginePackage && ready) {
            onResult?.invoke(true)
            return
        }
        // 0.4.75: засечка смены движка (см. жалобу «проблема с переключением
        // синтезаторов»). Дальше по журналу видно, поднялся ли новый движок,
        // когда приехали голоса и каким голосом он заговорил.
        Diag.log(
            appContext, "tts",
            "переключаю движок: ${enginePackage ?: "системный"} → ${pkg ?: "системный"}"
        )
        engineReadyCallback = onResult
        // 19.10.2026, то же правило, что у смены голоса: уходящий движок забирает
        // свой звук с собой. Паузная фраза, кэш сыгранных, очередь и заявки
        // сделаны ПРЕЖНИМ движком — после смены играть их нельзя, иначе
        // продолжение начинается прежним синтезом (см. [selectVoice]).
        dropPrepared()
        // 05.10.2026: новый движок поднимается не мгновенно, и первая его фраза
        // тоже не скорая — на это время даём окно прогрева ([armVoiceWarmup]),
        // иначе сторож успевал переспросить фразу и перезапустить движок прямо
        // во время загрузки (см. разбор в [voiceWarmUntilMs]).
        armVoiceWarmup("смена движка")
        start(pkg, rememberAwaiting = false)
    }

    private fun start(pkg: String?, rememberAwaiting: Boolean = true) {
        val gen = ++engineGen
        // 05.10.2026 (журнал 20:12: чтение замолчало на 11 с). Перезапуск движка
        // выбрасывает всё, что было в работе, — в том числе фразу, которую ждёт
        // чтение. Прежде её запоминали только тогда, когда сторож сработал именно
        // по ней; если же перезапуск вызвала заготовка впрок, жданная фраза
        // пропадала вместе с конвейером, и чтение молчало до вмешательства
        // человека. Теперь запоминаем её при любом перезапуске — кроме смены
        // движка: там фразу перечитывает читалка ([ReaderEngine.restartAfterSwitch]),
        // и второй заказ был бы повтором.
        if (rememberAwaiting && awaitingPlayText != null && retryAfterRestart == null) {
            retryAfterRestart = awaitingPlayText
            retryAfterRestartPos = awaitingPos
            retryAfterRestartPart = if (awaitingPart >= 0) awaitingPart else currentPart
            Diag.log(
                appContext, "tts",
                "перезапуск движка: фразу, которую ждёт чтение, перечитаю после подъёма"
            )
        }
        // 05.10.2026 (журнал 18:18: чтение встало насовсем). Перезапуск движка
        // застал его за живой речью (разовая прямая речь): после [resetPipeline]
        // заявки в pending нет, «доиграла» по оборванной фразе не придёт, и чтение
        // ждёт вечно — оно так и простояло 19 с, пока Серж не нажал паузу. Значит,
        // запоминаем фразу и перечитываем её файлом, как только движок поднимется
        // (тем же путём, что [retryAfterRestart] для потерянных заявок на файл).
        if (directSpeakingText != null && retryAfterRestart == null) {
            retryAfterRestart = directSpeakingText
            retryAfterRestartPos = if (directSpeakingPos >= 0) directSpeakingPos else currentPos
            retryAfterRestartPart = directSpeakingPart
            Diag.log(
                appContext, "tts",
                "перезапуск движка застал его за живой речью — перечитаю эту фразу файлом"
            )
        }
        enginePackage = pkg
        runCatching { tts?.stop() }
        runCatching { tts?.shutdown() }
        tts = null
        ready = false
        pending.clear()
        resetPipeline()
        // Слушатель свой у каждого запуска: он отвечает за КОНКРЕТНЫЙ движок
        // (см. [engineGen]). Общий слушатель путал ответы, и переключение
        // синтезатора сваливалось на системный движок.
        val listener = TextToSpeech.OnInitListener { status -> main.post { onEngineInit(gen, status) } }
        tts = runCatching {
            if (pkg != null) TextToSpeech(appContext, listener, pkg)
            else TextToSpeech(appContext, listener)
        }.getOrNull()
        if (tts == null) {
            // Движок не создался вовсе (нет такого пакета, отключён, упал) —
            // конструктор не бросает исключение наружу всегда, а ответа от
            // слушателя в этом случае не будет: без этой ветки вызывающий ждал бы
            // ответа вечно (в журнале у тестера это выглядело как «не
            // переключается»).
            Diag.log(
                appContext, "tts",
                "движок ${pkg ?: "системный"} не создался вовсе — отвечаю отказом"
            )
            main.post {
                if (gen == engineGen) {
                    engineReadyCallback?.invoke(false)
                    engineReadyCallback = null
                }
            }
        }
    }

    // ---------- Реплики другим голосом (26.09.2026) ----------
    //
    //  Разбор: реплика — предложение, начинающееся с длинного тире (Roles).
    //  Голос у реплик свой и, если человек так захотел, у них свой ДВИЖОК:
    //  второй экземпляр TextToSpeech, поднятый лениво, при первой реплике.
    //
    //  Почему отдельный экземпляр, а не переключение голоса на одном. У нас до
    //  трёх синтезов в работе сразу (prefetchDepth): голос выставляется на самом
    //  объекте TextToSpeech, и переключение между фразами отдало бы чужой голос
    //  той фразе, что уже в работе. Своим экземпляром такого не бывает вовсе —
    //  каждая фраза уходит в тот движок, который её и прочитает. Так же сделано
    //  в @Voice Aloud Reader: у каждого голоса-псевдонима свой движок
    //  (движок, язык, имя голоса), а не переключение на лету.
    //
    //  Числа для замера: сколько фраз прочитано основным голосом, сколько
    //  репликовым и сколько раз реплику спасал основной. Без них спор «тормозит
    //  или нет» остаётся спором.

    /** Читать ли реплики вторым голосом. Ставит читалка из настроек. */
    private var replyOn = false
    private var replyEnginePackage: String? = null
    private var replyVoiceName: String? = null

    private var replyTts: TextToSpeech? = null
    private var replyReady = false
    private var replyGen = 0L
    private var replyStarting = false

    /** Свои скорость, тон и громкость у реплик (26.09.2026, просьба Сергея:
     *  «свои ползунки для реплик»). Скорость и тон уходят в репликовый движок,
     *  громкость ставится нашему плееру, когда звучит репликовая фраза. */
    var replySpeed: Float = 1f
    var replyPitch: Float = 1f
    var replyVolume: Float = 1f
        set(value) {
            field = value.coerceIn(0f, 2f)
            // 30.09.2026: у реплик громкость выше 100% тоже поднимает усилитель
            // прямого звука (сеанс у нас один на оба голоса).
            applyDirectBoost()
        }

    /** Файлы, сделанные движком реплик: по имени файла видно, какую громкость
     *  ставить в момент звука. Набор подчищаем, когда разрастётся, — имена
     *  короткие («s_12.wav»), но за долгое чтение их набирается много. */
    private val replyFiles = HashSet<String>()

    /** Какой репликовый голос уже выставлен на экземпляре и о каком уже
     *  предупредили в журнале (26.09.2026): без этого смена голоса могла
     *  «не подхватиться» молча. */
    private var replyVoiceApplied: String? = null
    private var replyVoiceWarned: String? = null

    /** Какая громкость положена этому файлу: у реплик своя, у книги общая.
     *  Плеер больше единицы не принимает — выше 100% домножается в звуке. */
    private fun volumeFor(f: File): Float {
        val v = if (f.name in replyFiles) replyVolume else volume
        return v.coerceIn(0f, 1f)
    }

    /** Движок реплик отказал (не создался, не поднялся, потерял фразу). Тогда до
     *  конца сеанса реплики читает основной голос: тишина хуже, чем один голос. */
    private var replyBroken = false

    /** Сколько раз ПОДРЯД движок реплик молчал (29.09.2026). Первый промах —
     *  ждём ещё раз, второй — отказываемся от ролей до конца сеанса: одна
     *  потерянная заявка сетевого голоса не должна лишать книгу ролей. */
    private var replyMisses = 0

    /** Когда снова пробовать поднять отказавший движок реплик ([maybeReviveReplyEngine]). */
    private var replyRetryAt = 0L

    private var mainPhrases = 0
    private var replyPhrases = 0
    private var replyFalls = 0

    /** Признак «репликовый движок работает» — для строки настроек. */
    val replyEngineReady: Boolean get() = replyReady && replyTts != null

    /** Фраз прочитано основным голосом, репликовым и сколько реплик спасено
     *  основным: строка для журнала. */
    fun replyCountersLine(): String =
        "фраз основным $mainPhrases, реплик вторым $replyPhrases, спасал основной $replyFalls"

    /** Настройка реплик: включены ли, каким движком и каким голосом читать.
     *  Меняется на ходу — движок реплик пересобирается лениво, при первой реплике. */
    fun setReplyVoice(enabled: Boolean, engine: String?, voice: String?) {
        if (enabled == replyOn && engine == replyEnginePackage && voice == replyVoiceName) return
        // Смена движка реплик требует ПЕРЕСОЗДАТЬ экземпляр: старый остаётся
        // привязан к прежнему движку, и голос нового в нём просто не находится —
        // на слух это «выбрал другой голос, а читает прежний» (жалоба Сержа
        // 26.09.2026). Раньше экземпляр пересобирался только при выключении.
        val engineChanged = engine != replyEnginePackage
        val voiceChanged = voice != replyVoiceName
        replyOn = enabled
        replyEnginePackage = engine
        replyVoiceName = voice
        replyBroken = false
        replyVoiceApplied = null
        replyVoiceWarned = null
        Diag.log(
            appContext, "tts",
            "реплики: ${if (enabled) "другим голосом" else "выключены"}, " +
                "движок ${engine ?: "системный"}, голос ${voice ?: "движковый"} (${replyCountersLine()})"
        )
        if (!enabled || engineChanged) dropReplyEngine()
        // Готовые заготовки сделаны прежним голосом — не играем их: иначе после
        // смены голоса несколько фраз звучат старым, и кажется, что выбор не
        // подхватился (та же жалоба).
        if (voiceChanged || engineChanged) dropStaleReply()
    }

    /** Выбросить заготовки, сделанные прежним репликовым голосом. Текущий звук
     *  не трогаем: он уже играет, и обрывать его незачем. */
    private fun dropStaleReply() {
        clearPrefetch()
        // 29.09.2026: в новом пути заготовки лежат не только в очереди, но и в
        // списке плеера — без этой чистки прежним голосом (или прежней громкостью
        // выше 100%, которая домножается в самом звуке) доигрывало бы всё, что уже
        // отдано плееру. Звучащую фразу не трогаем.
        exoDropTail()
        keptPhrase?.let { runCatching { it.file.delete() } }
        keptPhrase = null
    }

    /** Движок реплик, если он уже готов. Пока поднимается — null, и реплику
     *  читает основной голос: чтение не должно ждать второго движка. */
    private fun replyInstance(): TextToSpeech? {
        if (replyReady && replyTts != null) return replyTts
        if (!replyStarting) startReply()
        return null
    }

    /** Поднять движок реплик ЗАРАНЕЕ — пока в книге ещё не встретилась ни одна
     *  реплика (27.09.2026, просьба Сержа: «держи два синтезатора наготове,
     *  чтобы пауз не было»). Зовётся, когда окно читалки открыто и звук первой
     *  фразы готовится впрок, — то есть за секунды до чтения. Так к первой
     *  реплике движок уже готов, и ждать его не приходится вовсе. Ничего не
     *  делает, если реплики выключены или движок уже поднят. */
    fun prepareReplyEngine() {
        // Свой экземпляр нужен только для ДРУГОГО движка: у одного и того же движка
        // роли читает он сам, взяв голос реплик на время фразы (29.09.2026).
        if (!replyOn || !replyNeedsOwnInstance() || replyBroken) return
        replyInstance()
    }

    /** Читают ли реплики второй голос ПО НАШЕМУ ЗАМЫСЛУ: режим включён и движок
     *  не отказал. В отличие от [replyEngineReady] верно и пока движок
     *  поднимается — по этому признаку читалка решает, делить ли фразу на
     *  голоса (см. ReaderEngine.chunkSpan). */
    val replyVoicesActive: Boolean get() =
        replyOn && (!replyNeedsOwnInstance() || !replyBroken)

    // ---- Ожидание репликового движка (27.09.2026) ----
    //
    //  Жалоба Сержа по журналу: самая первая реплика после нажатия «читать»
    //  звучала голосом книги. Причина видна в счётчике: движок реплик ещё
    //  поднимался, а конвейер уже заказал ему фразу — заказ ушёл основному
    //  движку («фраз основным 2» к моменту готовности второго). Теперь реплику
    //  не отдаём чужому голосу, а ждём: заказ повторяется сам, через
    //  [REPLY_WAIT_STEP_MS]. Ждём не дольше [REPLY_WAIT_MS], после чего движок
    //  считается отказавшим и реплики, как и раньше, читает основной.

    /** Фраза, из-за которой ждём движок реплик (null — не ждём). */
    private var replyWaitText: String? = null
    private var replyWaitPos: Long = -1L
    private var replyWaitPart = 0

    /** С какого момента ждём: по нему видно, не пора ли перестать. */
    private var replyWaitFrom = 0L

    /** Повтор синтеза уже назначен — второй раз не назначаем. */
    private var replyWaitPosted = false

    /** Поднять движок реплик и сказать, ждать ли его ещё.
     *  true — фразу пока НЕ заказываем: повторим сами, когда движок поднимется.
     *  false — ждать нечего: движок поднялся (или отказал) — читаем как обычно. */
    private fun waitForReply(text: String, pos: Long = -1L, part: Int = 0): Boolean {
        if (replyReady && replyTts != null) return false
        if (replyBroken) return false
        val now = System.currentTimeMillis()
        if (replyWaitText != text) {
            replyWaitText = text
            replyWaitPos = pos
            replyWaitPart = part
            replyWaitFrom = now
        }
        if (now - replyWaitFrom > REPLY_WAIT_MS) {
            replyWaitText = null
            replyBroken = true
            Diag.log(
                appContext, "tts",
                "движок реплик не поднялся за $REPLY_WAIT_MS мс — читаю реплики основным голосом"
            )
            return false
        }
        replyInstance() // заодно поднимаем движок, если ещё не начинали
        if (replyReady && replyTts != null) return false
        if (!replyWaitPosted) {
            replyWaitPosted = true
            main.postDelayed({
                replyWaitPosted = false
                val t = replyWaitText
                // Фраза всё ещё ждёт нас? Иначе заказ не нужен: человек ушёл
                // вперёд, поставил паузу или закрыл книгу.
                // 23.10.2026: сверка по ЕДИНИЦЕ РЕЧИ (место + кусок), а не по
                // «есть такой текст в работе»: одинаковых реплик в книге много.
                if (t != null &&
                    (awaitingPlayText == t ||
                        fileInFlight(Units.key(replyWaitPos, replyWaitPart)) != null ||
                        keptPhrase?.text == t)
                ) {
                    synthToFile(t, replyWaitPos, replyWaitPart)
                }
            }, REPLY_WAIT_STEP_MS)
        }
        return true
    }

    /** Забыть про ожидание движка реплик (пауза, прыжок, смена настройки). */
    private fun forgetReplyWait() {
        replyWaitText = null
        replyWaitFrom = 0L
    }

    private fun startReply() {
        replyStarting = true
        val gen = ++replyGen
        runCatching { replyTts?.shutdown() }
        replyTts = null
        replyReady = false
        val pkg = replyEnginePackage
        val listener = TextToSpeech.OnInitListener { status -> main.post { onReplyInit(gen, status) } }
        replyTts = runCatching {
            if (pkg != null) TextToSpeech(appContext, listener, pkg)
            else TextToSpeech(appContext, listener)
        }.getOrNull()
        if (replyTts == null) {
            replyStarting = false
            replyBroken = true
            Diag.log(
                appContext, "tts",
                "движок реплик ${pkg ?: "системный"} не создался — читаю реплики основным голосом"
            )
        }
    }

    private fun onReplyInit(gen: Long, status: Int) {
        if (gen != replyGen) return
        replyStarting = false
        val t = replyTts
        // 30.09.2026: было `if (!ok || t == null)`, где ok уже включал t != null —
        // компилятор честно ругался «условие всегда ложно». Пишем проверку так,
        // чтобы после неё t был точно не null (иначе дальше его не разыменовать).
        if (status != TextToSpeech.SUCCESS || t == null) {
            replyReady = false
            replyBroken = true
            Diag.log(
                appContext, "tts",
                "движок реплик ${replyEnginePackage ?: "системный"}: init status=$status — " +
                    "читаю реплики основным голосом"
            )
            return
        }
        replyReady = true
        t.setOnUtteranceProgressListener(object : UtteranceProgressListener() {
            override fun onStart(utteranceId: String?) {
                // В альтернативном способе эта весть продлевает надзор за прямой
                // речью; для синтеза в файл directSpeechStarted сам разберётся,
                // что это не его заявка.
                val id = utteranceId?.toLongOrNull() ?: return
                main.post { directSpeechStarted(id) }
            }

            override fun onDone(utteranceId: String?) {
                val id = utteranceId?.toLongOrNull() ?: return
                main.post { synthFinished(id) }
            }

            @Deprecated("Deprecated in Java")
            override fun onError(utteranceId: String?) {
                val id = utteranceId?.toLongOrNull() ?: return
                main.post { synthFailed(id, -1) }
            }

            override fun onError(utteranceId: String?, errorCode: Int) {
                val id = utteranceId?.toLongOrNull() ?: return
                main.post { synthFailed(id, errorCode) }
            }
        })
        applyReplyParams(t)
        Diag.log(
            appContext, "tts",
            "движок реплик готов: ${replyEnginePackage ?: "системный"}, " +
                "голос ${t.voice?.name ?: "движковый"} (${replyCountersLine()})"
        )
        // Голоса у чужого движка приезжают позже init (как и у основного) —
        // тогда выбранный голос поставить нечем. Спрашиваем в СТОРОНЕ (24.10.2026:
        // на главном потоке этот запрос вешал окно) и ещё раз применяем настройки.
        refreshReplyVoices()
        main.postDelayed({ if (replyReady) applyReplyParams(replyTts) }, 700)
    }

    /** Скорость, тон и выбранный голос на репликовом экземпляре. Зовётся перед
     *  каждой репликой: так настройки остаются верными, даже если скорость
     *  поменяли на ходу, и не нужен отдельный пересбор при смене голоса. */
    private fun applyReplyParams(t: TextToSpeech?) {
        if (t == null) return
        runCatching {
            val name = replyVoiceName
            if (name != null && !(replyVoiceApplied == name && t.voice?.name == name)) {
                // 24.10.2026: голос ищем в готовом списке, полученном в стороне;
                // пусто — просим список и применим его на следующей реплике.
                val v = replyVoiceCache.firstOrNull { it.name == name }
                if (v != null) {
                    t.voice = v
                    replyVoiceApplied = name
                    if (replyVoiceWarned == name) replyVoiceWarned = null
                    Diag.log(appContext, "tts", "реплики: голос применён — $name")
                } else if (replyVoiceWarned != name) {
                    if (replyVoiceCache.isEmpty()) {
                        // Список ещё не приехал — это не «движок не знает голос».
                        refreshReplyVoices()
                    } else {
                    // Молчать тут нельзя: именно это выглядит как «выбрал голос, а
                    // читает прежний». Пишем, сколько голосов движок вообще отдал.
                    replyVoiceWarned = name
                    Diag.log(
                        appContext, "tts",
                        "движок реплик ${replyEnginePackage ?: "системный"} не знает голос $name " +
                            "(голосов у него ${replyVoiceCache.size}) — читаю его голосом"
                    )
                    }
                }
            }
            // Скорость и тон — СВОИ у реплик: книжные ползунки их не трогают.
            // Задаём их ПОСЛЕ голоса: установка голоса сбрасывает темп к значению
            // по умолчанию (см. [applySpeedAndVoice]), и раньше наши настройки
            // реплик до движка не доезжали.
            t.setSpeechRate(replySpeed)
            t.setPitch(replyPitch)
        }
    }

    /** Взять ОСНОВНОЙ экземпляр в долг под реплику (29.09.2026).
     *
     *  Так делают и другие читалки: когда оба голоса живут в одном движке, второго
     *  экземпляра не заводят — ставят голос перед заказом фразы. Движок запоминает
     *  голос вместе с заявкой, поэтому сразу после заказа мы возвращаем книжный
     *  голос ([restoreMainParams]) и книжные фразы не страдают.
     *
     *  Почему это лучше второго экземпляра: два экземпляра ОДНОГО движка теряют
     *  заявки (журнал 20:10: движок реплик молчал, роли пропали до конца книги),
     *  и держать его «разогретым» приходилось костылями. */
    private fun borrowMainForReply(t: TextToSpeech) {
        runCatching {
            val name = replyVoiceName
            if (name != null) {
                // 24.10.2026: голос берём из готового списка (см. [voiceCache]).
                val v = voiceCache.firstOrNull { it.name == name }
                if (v != null) {
                    t.voice = v
                    replyVoiceApplied = name
                } else if (replyVoiceWarned != name) {
                    replyVoiceWarned = name
                    Diag.log(
                        appContext, "tts",
                        "движок не знает голос реплик $name (голосов у него ${voiceCache.size}) — " +
                            "реплики звучат его голосом"
                    )
                }
            }
            t.setSpeechRate(replySpeed)
            t.setPitch(replyPitch)
        }
    }

    /** Вернуть основному экземпляру книжные голос, скорость и тон. */
    private fun restoreMainParams(t: TextToSpeech) {
        runCatching {
            val name = selectedVoiceName
            if (name != null) {
                // 24.10.2026: из готового списка (см. [voiceCache]).
                val v = voiceCache.firstOrNull { it.name == name }
                if (v != null) t.voice = v
            }
            t.setSpeechRate(speed)
            t.setPitch(pitch)
        }
    }

    /** Нужен ли репликам СВОЙ экземпляр движка. Не нужен, когда реплики выбраны в
     *  том же движке, что книга: второй экземпляр одного движка только теряет
     *  заявки (29.09.2026, см. [borrowMainForReply]). */
    private fun replyNeedsOwnInstance(): Boolean = replyEnginePackage != enginePackage

    /** Отказавший движок реплик пробуем поднять снова — по делу, а не таймером:
     *  встретилась очередная реплика, значит он опять нужен. Не чаще раза в
     *  [REPLY_RETRY_MS], иначе на каждом отказавшем движке мы бы его пересобирали. */
    private fun maybeReviveReplyEngine() {
        val now = SystemClock.elapsedRealtime()
        if (now < replyRetryAt || replyStarting) return
        replyRetryAt = now + REPLY_RETRY_MS
        replyBroken = false
        replyMisses = 0
        Diag.log(appContext, "tts", "движок реплик: пробую поднять снова")
        replyInstance()
    }

    /** Скорость, которой синтезируется фраза этой роли: у реплик своя. По ней же
     *  проверяется, не устарела ли готовая заготовка. */
    private fun rateFor(role: Pending.Role): Float = if (role == Pending.Role.REPLY) replySpeed else speed

    /** Погасить движок реплик (смена настройки, отказ, закрытие книги). Заявки,
     *  что были в работе, отменяем: их файлы уже никому не нужны. */
    private fun dropReplyEngine() {
        val mine = pending.filterValues { it.role == Pending.Role.REPLY }
        mine.forEach { (id, p) ->
            p.cancelled = true
            p.file?.delete()
            pending.remove(id)
        }
        replyGen++
        replyStarting = false
        replyReady = false
        forgetReplyWait()
        runCatching { replyTts?.stop() }
        runCatching { replyTts?.shutdown() }
        replyTts = null
    }

    /** Начать озвучивать одно предложение. Вызывается с главного потока.
     *
     *  [userAsked] — фразу попросил ЧЕЛОВЕК (старт чтения, продолжение после
     *  паузы, «повторить», шаг назад, прыжок), а не само чтение по ходу книги.
     *  Это различие решает две вещи: из кэша сыгранных фразу отдаём только по
     *  просьбе человека (вперёд повтор не нужен) и с этого места начинается
     *  новый проход, в котором единицы снова могут звучать (см. [playedKeys]).
     *
     *  [rest] — остальные куски ЭТОЙ ЖЕ фразы (слова автора, реплика, «хвост»
     *  после укороченной первой фразы). В файловом пути их заказывает
     *  [prefetchRest]; в прямом пути их НАДО отдать движку сразу за головой —
     *  иначе они попадут в его очередь после следующих фраз, и когда чтение
     *  попросит их, придётся гасить очередь (`tts.stop()`) посреди живой речи:
     *  на слух — фраза обрывается и начинается заново. */
    fun speak(
        text: String,
        pos: Long = -1L,
        userAsked: Boolean = true,
        rest: List<String> = emptyList(),
    ) {
        val t = tts
        if (t == null || !ready || text.isBlank()) return
        // 08.10.2026: человек просит фразу — она начинается С НАЧАЛА, то есть с
        // нулевого куска. Без этого счётчик кусков продолжался с прежнего
        // обращения к ТОЙ ЖЕ фразе (пауза → продолжить, «повторить», возврат на
        // то же место): голова фразы получала номер 1, сохранённый паузой звук
        // не находился (сверка идёт по ключу), фраза синтезировалась заново, а
        // хвост и следующее предложение путались местами. В журнале это видно
        // как «кусок 1» у первой половины фразы (13:55:59, предл. 43).
        if (userAsked) {
            lastAskedPos = -1L
            lastAskedPart = -1
        }
        val part = nextPartFor(pos)
        currentText = text
        currentPos = pos
        currentPart = part
        currentRest = rest
        if (userAsked) playedKeys.clear()
        // Читалка просит фразу — упреждающая подготовка ([prewarm]) своё дело
        // сделала, дальше очередь наполняется обычным порядком.
        prewarmOnly = false
        logReadingMode()

        // #57: альтернативный способ — наш конвейер не участвует вовсе.
        // Фразу целиком отдаём движку (он и синтезирует, и играет), поэтому
        // здесь же отпускаем всё своё: играющий плеер и заготовки.
        if (directMode) {
            releaseMedia()
            clearPrefetch()
            awaitingPlayText = null
            Diag.log(
                appContext, "sound",
                // 06.10.2026: темп пишем вместе с фразой — по этой строке и по
                // замеру ([noteSpokenRate]) видно, послушался ли движок нового
                // числа. Без него разбор жалобы «скорость не работает» упирался
                // в догадки (журнал с MultiTTSLexx).
                "альтернативный способ: отдаю фразу движку (${text.length} знаков, " +
                    "скорость ${RateSteps.label(speed)}): ${text.take(40)}"
            )
            speakDirectQueued(text, pos, part, userAsked, rest)
            return
        }

        // Файловый путь: своя логика очереди, список плеера НЕ перезапускаем
        // (см. [speakExo]).
        speakExo(text, pos, part, userAsked)
    }

    /** Остановить озвучку: тишина сразу, onDone не вызывается. */
    fun stop() {
        currentText = null
        awaitingPlayText = null
        // Проба голоса кончилась (или её оборвали) — запас впрок снова обычный
        // (см. [previewOnly]).
        previewOnly = false
        // 08.10.2026: остановка (пауза, прыжок, конец книги) обрывает фразу —
        // следующее обращение к ней читается с НАЧАЛА, с нулевого куска. Иначе
        // продолжение после паузы получало номер 1, сохранённый паузой звук не
        // находился и фраза синтезировалась заново (см. [speak]).
        lastAskedPos = -1L
        lastAskedPart = -1
        prewarmOnly = false
        // 08.10.2026: засечки заказов прямой речи и счётчик «отчитался без звука»
        // начинаем заново — пауза обрывает проход (см. [directAskedAt]).
        directAskedAt.clear()
        ackSilentInRow = 0
        // Ожидание репликового движка снимаем: пауза и прыжок — новая вводная,
        // срок ожидания считаем заново (27.09.2026).
        forgetReplyWait()
        // Сохранённую паузой фразу здесь не трогаем: её ставит
        // [pauseKeepingPhrase] уже ПОСЛЕ остановки. Настоящий стоп (прыжок,
        // закрытие книги) её выбрасывает — продолжать с неё больше нечего.
        keptPhrase?.let { runCatching { it.file.delete() } }
        keptPhrase = null
        // msg4103: заявка, которая была «в полёте», здесь же и отменяется —
        // tts.stop() её гасит, а pending ниже чистится. Метку «синтез идёт»
        // снимаем вместе с ней: иначе speak() того же предложения (пауза →
        // продолжить) ждал бы ответа по заявке, которой уже нет, и чтение
        // замолкало бы навсегда. Именно это и видно в логе пользователя
        // (ivona.tts): pause → «старт чтения (предл. 145)» → тишина.
        // 23.10.2026: отдельного набора «в работе» больше нет — заявки живут в
        // [pending], и чистить его отдельно не надо (сами заявки отменяются ниже).
        // msg5309: а вот след лестницы мер ([synthMisses]) пауза НЕ стирает.
        // Раньше стирала — и у тестера Ивана это съедало всю эскалацию: он жмёт
        // паузу через 5–12 с, сторож не успевает досчитать, а после продолжения
        // фраза получала чистый лист и снова только переспрос, до перезапуска
        // движка дело не доходило ни разу. Теперь фразу, которую движок уже
        // терял, после продолжения стерегут коротким запалом и до перезапуска
        // доходят сразу. Чужой фразе след не мешает: сравнение идёт по тексту,
        // а снимают его доспевший синтез и перезапуск движка (resetPipeline).
        // Сторож молчания (msg4077): тишина попрошена — надзор снимаем, чтобы
        // он не «оживил» чтение, которое владелец только что остановил.
        forgetAllSynthWatches()
        directWatchToken++
        retryAfterRestart = null
        // 07.10.2026: засечку «сколько движок готовит первую фразу» снимаем —
        // после паузы или прыжка она бы считала время стоянки (см. [noteFirstPrep]).
        firstPrepFromMs = 0L
        clearPrefetch()
        releaseMedia()
        // Останавливаем и сам движок: иначе запасное прямое произнесение
        // (fallbackDirect) пауза не прерывает — фраза «дочитывалась» до конца,
        // а следующая глава накладывалась на её хвост.
        runCatching { tts?.stop() }
        // 26.09.2026: в альтернативном способе реплики мог читать ВТОРОЙ движок,
        // и свою очередь он дочитывал даже после паузы — «нажал остановить, а он
        // говорит». Гасим и его: пауза обязана замолчать целиком.
        runCatching { replyTts?.stop() }
        // Незавершённые синтезы больше никому не нужны: отменяем и удаляем их
        // файлы, чтобы после tts.stop() они не осиротели в pending.
        pending.values.forEach { it.cancelled = true; it.file?.delete() }
        pending.clear()
        directQueue.clear()
        // Звук погашен — «какая фраза звучит» и «что просило чтение» пусто
        // (29.09.2026, см. [directAskedId]).
        directAskedId = null
        directSpeakingText = null
        directSpeakingPos = -1L
        directSpeakingPart = 0
        currentRest = emptyList()
        lastDirectQueuedId = null
        // 08.10.2026: след прохода снимаем. После паузы продолжение — это уже
        // просьба человека (чтение зовёт [speak] с userAsked = true), и та же
        // фраза обязана звучать снова; а после прыжка проход другой вовсе.
        playedKeys.clear()
        lastPlayedPos = -1L
        lastPlayedPart = -1
    }

    fun selectVoice(name: String) {
        // Окно прогрева нужно только тогда, когда голос и правда СМЕНИЛСЯ: тот же
        // голос применяют и повторно (книга открылась, движок перезапустился), и
        // ждать там нечего — голос уже поднят.
        val changed = name != selectedVoiceName
        selectedVoiceName = name
        if (changed) {
            // 19.10.2026, жалоба Сержа: «остановка чтения не сбрасывает последний
            // буфер (или синтезированный файл): остановил, поменял голос, запустил
            // снова — последняя единица звучит старым синтезом». Чистку делаем
            // ЗДЕСЬ, в самом переключении голоса, а не в одном из путей его смены
            // (панель, настройки, восстановление при открытии книги): так её не
            // обойдёт ни одно окно. Паузный файл, кэш трёх сыгранных, список
            // плеера и заявки прежнего голоса выбрасываются сразу, до всякого
            // ожидания движка. Перечитывает текущую фразу читалка
            // ([ReaderEngine.restartAfterSwitch]).
            dropPrepared()
            armVoiceWarmup("смена голоса")
        }
        applySpeedAndVoice()
    }

    /** До какого времени даём движку поднять новый голос или сам новый движок
     *  ([armVoiceWarmup]). Пока срок идёт, сторож синтеза только ждёт: ни
     *  переспроса, ни перезапуска движка — и то и другое выбрасывает уже
     *  начатую работу. Срок снимается сам, как только придёт первая фраза
     *  нового голоса ([synthFinished]); не пришла — по истечении срока дальше
     *  идёт обычная лестница мер.
     *
     *  05.10.2026, разбор журнала Сержа (TeraTTS, ru.tolyos.teratts). Прежде
     *  здесь стояла гонка за 2,5 с: сторож не дожидался и лечил смену голоса
     *  переспросом фразы и перезапуском движка. Смена голоса стоила 13-18 с
     *  тишины (16:38:36 → 16:38:49, 16:49:04 → 16:49:22, 16:51:01 → 16:51:19),
     *  а звук появлялся ровно тогда, когда мы переставали дёргать движок: у
     *  него в этот момент как раз догружался новый голос. Удачные смены того же
     *  голоса — 0,55 с и 1,96 с, то есть дело не в движке, а в нашем сроке. */
    private var voiceWarmUntilMs = 0L

    /** Когда новый голос попросили (для честной цифры в журнале). */
    private var voiceWarmFromMs = 0L

    /** Сколько длится текущее окно (см. [armVoiceWarmup]). */
    private var voiceWarmMs = 0L

    /** Открыто ли окно сменой голоса или движка (а не холодным стартом). Нужно
     *  затем, что снимать пометку «медленный» можно только после смены: там её и
     *  заработали наши же промахи. Холодный старт пометку не трогает. */
    private var voiceWarmBySwitch = true

    /** Когда мы отдали движку первую фразу после старта или смены (см.
     *  [noteFirstPrep]); 0 — замер сейчас не идёт. */
    private var firstPrepFromMs = 0L

    private fun armVoiceWarmup(reason: String, ms: Long = voiceWarmFuseMs(), bySwitch: Boolean = true) {
        val now = SystemClock.elapsedRealtime()
        val use = warmWindow(ms)
        voiceWarmFromMs = now
        voiceWarmMs = use
        voiceWarmUntilMs = now + use
        voiceWarmBySwitch = bySwitch
        // Засечка «сколько движок готовит первую фразу»: закрытие окна в
        // [synthFinished] или первый `onStart` скажут точное число, а
        // [noteFirstPrep] запомнит его по паре «движок + голос».
        firstPrepFromMs = now
        Diag.log(
            appContext, "tts",
            "даю движку ${voiceWarmMs / 1000} с на загрузку ($reason)" +
                (if (use > ms) " — движок уже показывал, что готовит первую фразу ${(use - FIRST_PREP_MARGIN_MS) / 1000} с" else "") +
                " — в это время не переспрашиваю фразу и не перезапускаю движок"
        )
    }

    /** Окно терпения с поправкой на замер: движок, который первую фразу готовит
     *  двадцать секунд (свой разбор текста, загрузка модели), получает свои
     *  двадцать три, а не общие восемь. Замер — по паре «движок + голос»
     *  (см. [ExpertPrefs.firstPrepMs]); иначе окно остаётся прежним.
     *
     *  07.10.2026, разбор журнала 01:18: без этой поправки наши восемь секунд
     *  истекали, и лестница мер начинала переспрашивать фразу и ПЕРЕСОЗДАВАТЬ
     *  движок ровно в тот момент, когда он ещё готовил: вместо двадцати секунд
     *  выходило больше, а первая фраза звучала прямой речью.
     *
     *  Откат: убрать вызов `warmWindow` (вернуть `ms` как было) — всё остальное
     *  не зависит; пометки снимаются строкой «забыть пометки движка» в опытных
     *  настройках. */
    private fun warmWindow(base: Long): Long {
        val known = ExpertPrefs.firstPrepMs(appContext, enginePackage, selectedVoiceName)
        return maxOf(base, if (known > 0L) known + FIRST_PREP_MARGIN_MS else 0L)
    }

    /** Движок взялся за первую фразу через [ms] — запоминаем по паре «движок +
     *  голос», чтобы в следующий раз дать ему столько же времени с запасом. */
    private fun noteFirstPrep(ms: Long) {
        if (firstPrepFromMs == 0L) return
        firstPrepFromMs = 0L
        // Ответил сразу — мерить нечего (и старую пометку не трогаем: она могла
        // достаться от подготовки текста, которую включают на время).
        if (ms < FIRST_PREP_MIN_MS) return
        val capped = ms.coerceAtMost(ExpertPrefs.FIRST_PREP_MAX_MS)
        val prev = ExpertPrefs.firstPrepMs(appContext, enginePackage, selectedVoiceName)
        ExpertPrefs.setFirstPrepMs(appContext, enginePackage, selectedVoiceName, capped)
        Diag.log(
            appContext, "tts",
            "движок готовил первую фразу $capped мс (было $prev) — окно терпения " +
                "в следующий раз ${(capped + FIRST_PREP_MARGIN_MS) / 1000} с"
        )
    }

    /** Сколько ждать новый голос (05.10.2026, вопрос Сержа «а локальные
     *  синтезаторы мы так не сломаем?»).
     *
     *  Локальному движку долгое ожидание ни к чему: голос у него уже на
     *  устройстве, и первая фраза после смены по журналам приходит за 0,3-2 с
     *  (TeraTTS — 1,8-2,6 с). А сетевому и помеченному медленным голос нужен
     *  сетевым кругом, и там первая заявка бывает и в шесть секунд. Оба срока —
     *  в [Timing], выбирает их [timing]. Срок берётся и при смене движка, и
     *  заново в [applySpeedAndVoice], когда уже известно, сетевым ли оказался
     *  НОВЫЙ голос. */
    private fun voiceWarmFuseMs(): Long = timing.warmupMs

    /** Идёт окно прогрева (см. [armVoiceWarmup]). */
    private fun warmingVoice(): Boolean = voiceWarmUntilMs > SystemClock.elapsedRealtime()

    /** Сколько окна прогрева осталось (для срока сторожа). */
    private fun warmLeftMs(): Long =
        (voiceWarmUntilMs - SystemClock.elapsedRealtime()).coerceAtLeast(500L)

    private fun applySpeedAndVoice() {
        val t = tts ?: return
        if (!ready) return
        val name = selectedVoiceName
        var applied = "движковый"
        var chosen: Voice? = null
        if (name != null) {
            // 24.10.2026: голос ищем в ГОТОВОМ списке (см. [voiceCache]), а не
            // спрашиваем движок — на главном потоке этот запрос вешал окно.
            val v = voiceCache.firstOrNull { it.name == name }
            if (v != null) {
                t.voice = v
                chosen = v
                applied = name
            } else {
                applied = "$name (движок его не знает)"
            }
        }
        // Скорость и тон задаём ПОСЛЕ голоса (29.09.2026). Замер по журналу:
        // сетевой голос читал 14,5 знака в секунду при выставленной скорости 3,3,
        // то есть ровно как обычно, — похоже, установка голоса сбрасывает темп к
        // значению по умолчанию, а мы задавали его ДО голоса, и наш ползунок
        // скорости до движка не доезжал. Для локальных движков порядок
        // безразличен, а сетевым он может вернуть работу ползунка.
        t.setSpeechRate(speed)
        t.setPitch(pitch)
        // Сетевой ли этот голос (29.09.2026, см. [netSynth]). Спрашиваем и у
        // выбранного голоса, и у того, которым движок заговорит, если выбор не
        // нашёлся: у сетевого синтеза сроки ожидания другие.
        //
        // ГОЛОС, КОТОРОГО ДВИЖОК НЕ ЗНАЕТ, СЧИТАЕМ МЕДЛЕННЫМ (17.10.2026, разбор
        // с Сержем про «Дмитрия»). Имя голоса ничего не доказывает: «Дмитрий» есть
        // и локальным (движок MS Voice TTS держит его на устройстве и отвечает за
        // доли секунды), и сетевым — через MultiTTS выбираются голоса Microsoft,
        // которых движок по имени НЕ отдаёт («движок его не знает»). Тогда признак
        // «сетевой» был ложным, пара считалась локальной, получала короткие сроки
        // и ошибочно помечалась медленной на первой же неудаче — из-за этого
        // выскакивала панель выбора голоса у живого голоса. Про голос, которого
        // движок не знает, мы не знаем НИЧЕГО, поэтому обещать скорость нельзя:
        // берём сроки сетевого.
        // Сменили движок или голос — прежний признак «не работает» к этой паре
        // не относится: первое нажатие «Читать» должно читать, а не открывать
        // панель (журнал 00:47: после выбора рабочего движка панель открывалась
        // вместо чтения).
        TtsHealth.reset()
        val unknownVoice = name != null && chosen == null
        netDeclared = unknownVoice || voiceIsNetwork(chosen) || voiceIsNetwork(t.voice)
        // Запомнить, есть ли у движка сетевые голоса: окно «Движки» показывает
        // движку без них три положения вместо четырёх ([ExpertPrefs.engineHasNetwork]).
        // Про «нет» можно судить только когда голос у движка ОДИН.
        val voiceCount = voiceCache.size
        ExpertPrefs.noteEngineVoice(appContext, modeEngine(), netDeclared, voiceCount == 1)
        val marked = slowMarks().contains(synthMark())
        val was = netSynth
        netSynth = netDeclared || marked
        // Файловый путь у этой пары «движок + голос» уже проваливался — читаем
        // напрямую с самого начала (см. [netDirect]).
        //
        // 30.09.2026 (сборка 227): одной пары для этого мало — у сетевых голосов
        // одного движка файлы не приходят НИ У ОДНОГО (см.
        // [engineFileFailVoices]). Два провалившихся сетевых голоса — приговор
        // движку: все его сетевые голоса читаем напрямую, без пробы файла.
        // Локальные голоса не задевает — заявленный сетевой нужен и здесь
        // ([netDeclared]); у Google, чьи сетевые голоса файлы отдают, провалов не
        // бывает вовсе, и пометки движка у него не появится.
        val engineFails = engineFileFailVoices()
        val pairMarked = directMarks().contains(synthMark())
        // Профиль способа чтения — свой у КАЖДОГО движка (см. [forceMode]),
        // поэтому перечитываем его здесь: движок мог смениться.
        val forceWas = forceMode
        forceMode = ExpertPrefs.forceMode(appContext, modeEngine())
        val wasDirect = directMode
        // Решение о способе — одним местом ([decideDirectMode]): там же пометка
        // пары ([markedPairNoFiles], по ней прямое чтение идёт по одной фразе и
        // пересоздаётся соединение при смене скорости) и слова о причине для
        // [ReadingMode]. Профиль движка сильнее и пометок, и опыта.
        val (netDirectNow, directWhyNow) = decideDirectMode()
        netDirect = netDirectNow
        directWhyText = directWhyNow
        // Профиль сменил направление прямо на этом применении голоса — конвейер
        // прежнего способа больше не нужен.
        if (forceWas != forceMode) switchPipeline(wasDirect)
        // Прямой режим включился — 24.10.2026 тихий поток сам не встаёт (просьба
        // Сержа: «пускай по умолчанию будет выключена»), только журнал.
        if (directMode) {
            KeepAwake.noteDirectNeedsSilence(
                appContext,
                when {
                    forceMode == ExpertPrefs.MODE_DIRECT ->
                        "в опытных настройках выбран прямой способ чтения"
                    forceMode == ExpertPrefs.MODE_NET_DIRECT ->
                        "голос сетевой, а в опытных настройках выбрано «сетевые — движком»"
                    pairMarked -> "этот движок с этим голосом файлов не отдаёт"
                    else -> "движок не отдаёт файлы ни одним сетевым голосом"
                },
            )
        }
        // Голос сам заявил сеть, у движка уже есть провал — второй раз за файлом
        // не ходим (см. [onSynthWatchdog]).
        netSuspectEngine = netDeclared && !netDirect && engineFails >= 1
        if (netDirect && !was) {
            Diag.log(
                appContext, "tts",
                when {
                    engineMarkedNoFiles ->
                        "движок ${enginePackage ?: "системный"} файлов не отдаёт (помечен на " +
                            "другом голосе, а свой голос у него не выбирается) — читаю напрямую"
                    pairMarked -> "этот движок с этим голосом файлов не отдаёт (помечено " +
                        "раньше) — читаю напрямую, как в альтернативном способе"
                    else -> "движок ${enginePackage ?: "системный"} файлов не отдаёт ни одним " +
                        "сетевым голосом (провалов $engineFails) — файл не заказываю вовсе"
                }
            )
        }
        if (netSynth != was) {
            // 05.10.2026: сообщение было ОДНО на оба направления, и когда пометка
            // «медленный» уходила (смена голоса на немаркированный), в журнале
            // всё равно писалось «движок уже был помечен медленным» — то есть
            // ровно наоборот. По этому вранью разбор и ушёл не туда (журнал
            // 17:12:51: голос M1 на самом деле был ЧИСТЫМ, а пометка жила на
            // прежнем голосе). Теперь говорим как есть.
            if (netSynth) {
                val why = if (netDeclared) {
                    "голос сам заявляет, что нужна сеть"
                } else {
                    "движок уже был помечен медленным"
                }
                Diag.log(
                    appContext, "tts",
                    "синтезатор считаю сетевым ($why): жду фразу дольше, движок не перезапускаю"
                )
            } else {
                Diag.log(
                    appContext, "tts",
                    "сетевым этот голос больше не считаю (пометки на нём нет): сроки обычные"
                )
            }
        }
        // 0.4.75: чем движок заговорит на самом деле — по журналу видно и голос,
        // и скорость (после переключения синтезатора это главный вопрос).
        // 05.10.2026: тут же уточняем длину окна прогрева — теперь известно,
        // сетевым ли оказался НОВЫЙ голос (см. [voiceWarmFuseMs]).
        if (voiceWarmUntilMs != 0L) {
            val ms = warmWindow(voiceWarmFuseMs())
            if (ms != voiceWarmMs) {
                voiceWarmMs = ms
                voiceWarmUntilMs = voiceWarmFromMs + ms
                Diag.log(
                    appContext, "tts",
                    "окно прогрева нового голоса — ${ms / 1000} с " +
                        "(голос ${if (netSynth) "сетевой или помеченный медленным" else "локальный"})"
                )
            }
        }
        Diag.log(
            appContext, "tts",
            "применил: движок ${enginePackage ?: "системный"}, скорость " +
                "${RateSteps.label(speed)}, голос $applied"
        )
    }

    /** Задержки повторных вопросов «а голоса уже приехали?» после init (msg3550).
     *  Каждая следующая длиннее: первый ответ чаще всего приходит почти сразу,
     *  а медленный движок отзывается через секунду-полторы. */
    private val voiceWaitSteps = longArrayOf(300, 700, 1500)

    /** Голоса движка приезжают не в момент init ([applySpeedAndVoice] тогда не
     *  находит выбранный голос и оставляет как есть — настройки не портятся).
     *  Публичного уведомления о готовности списка в SDK нет, поэтому спрашиваем
     *  сами: до [voiceWaitSteps].size раз с растущей паузой. */
    private fun waitForVoices(stepsLeft: Int) {
        if (stepsLeft <= 0) return
        val delay = voiceWaitSteps[voiceWaitSteps.size - stepsLeft]
        main.postDelayed({
            if (!ready) return@postDelayed
            // 24.10.2026: спрашиваем в стороне — см. [voiceCache].
            refreshVoices {
                if (voiceCache.isEmpty()) {
                    waitForVoices(stepsLeft - 1)
                } else {
                    applySpeedAndVoice()
                    Diag.log(appContext, "tts", "голоса движка приехали не сразу (через $delay мс)")
                }
            }
        }, delay)
    }

    // ---------- Сторож молчания (msg4077) ----------

    /** Взвести надзор за синтезом [text]: не отозвался за [synthFuseMs] —
     *  считаем движок замолчавшим. Если эту фразу движок уже терял однажды
     *  ([synthMissesOf] — переспрос не помог), ждём коротко (срок после
     *  переспроса, [Timing.reaskMs]) и идём к следующей мере, а не отсчитываем
     *  полный срок заново (msg5309).
     *
     *  Засекаем и МОМЕНТ взведения надзора (msg4211): в логе тестера сторож
     *  сработал через 42 с вместо номинала — таймеры `postDelayed` не шли,
     *  процесс спал. Часы elapsedRealtime идут и во сне, поэтому разница честно
     *  показывает, сколько устройство простояло замороженным. Засечка — на
     *  каждом взведении: взводят его только по настоящему событию (заявка на
     *  синтез или отсрочка, пока играет предыдущая фраза), и если бы момент
     *  не обновлялся, повтор той же фразы через полчаса выдал бы «спал 1800 с».
     *
     *  [started] — движок уже взялся за эту заявку (пришёл `onStart`). У
     *  СЕТЕВОГО движка заявок в работе несколько ([maxInFlight]), и та, что
     *  стоит в очереди движка, ждёт своей очереди — это не молчание. Поэтому до
     *  старта ждём долго ([Timing.queueMs] — 20 с), а короткий срок отсчитываем
     *  от старта (см. [directSpeechStarted]).
     */
    private fun armSynthWatch(
        text: String,
        shortFuse: Boolean = synthMissesOf(text) > 0,
        started: Boolean = false,
    ) {
        watchFromMs = SystemClock.elapsedRealtime()
        val fuse = synthFuseFor(text, shortFuse, started)
        val token = (synthWatchTokens[text] ?: 0L) + 1
        synthWatchTokens[text] = token
        main.postDelayed({ if (synthWatchTokens[text] == token) onSynthWatchdog(text) }, fuse)
    }

    /** Срок, через который сторож спросит движок, почему молчит синтез.
     *
     *  Отдельный случай — СЛЫШИМАЯ тишина (29.09.2026). Фразу, которую ждёт
     *  чтение ([awaitingPlayText]), а звука нет вовсе (ничего не играет),
     *  стерегём коротко. Жалоба Сержа: «смущает паузы, когда он замолчал тогда
     *  на 5 секунд». В журнале 08:48 так и вышло: заявку на фразу движок потерял, а
     *  следующий шаг лестницы наступал только через полный сетевой срок, и
     *  тишина складывалась в 6,5 с. Пока играет предыдущая фраза, ждать можно и
     *  подольше — этой паузы не слышно. */
    private fun synthFuseFor(text: String, shortFuse: Boolean, started: Boolean): Long = when {
        // 05.10.2026: движок поднимает новый голос — ждём молча и движок не
        // трогаем (см. [armVoiceWarmup]). Ветка стоит ПЕРВОЙ: она важнее и
        // «слышимой тишины», из-за которой срок был 2,5 с, и сетевых сроков.
        warmingVoice() -> warmLeftMs()
        // 29.09.2026 (журнал 18:52, «на маленькой скорости останавливался»): срок
        // для жданной фразы берём не голыми 2,5 с, а не меньше ПОЛОВИНЫ срока по
        // длине фразы. На маленькой скорости фраза длинная (при 0,5 та же фраза
        // звучит вдвое дольше), и движок собирает её дольше: 2,5 с истекали, мы
        // переспрашивали фразу у занятого движка, и он от этого только тормозил —
        // на слух это те самые остановки. Короткая фраза по-прежнему стережётся
        // коротко: половинный срок у неё меньше 2,5 с.
        !soundPlaying() && text == awaitingPlayText ->
            maxOf(SYNTH_SILENT_MS, synthFuseMs(text) / 2, synthExpectMs(text))
        shortFuse -> timing.reaskMs
        !started && timing.queueMs > 0L -> timing.queueMs
        else -> synthFuseMs(text)
    }

    /** Снять надзор за синтезом: за [text] больше не следим, и все прежние
     *  засечки по нему недействительны. */
    private fun forgetSynthWatch(text: String) {
        synthWatchTokens.remove(text)
    }

    /** Снять надзор за всеми заявками разом (пауза, сброс конвейера). */
    private fun forgetAllSynthWatches() {
        synthWatchTokens.clear()
    }

    /** Когда взведён текущий надзор за синтезом (для честной цифры в логе). */
    private var watchFromMs = 0L

    /** Синтез молчит дольше разумного. Лестница мер (msg4103): переспросить фразу
     *  без перезапуска движка → перезапустить движок (до [Timing.restarts] раз,
     *  у сетевого их ноль) →
     *  страховка ([onSynthLost]: прямая речь, а то и пропуск фразы). Чтение
     *  продолжается в любом случае — молчания навсегда быть не должно. */
    private fun onSynthWatchdog(text: String) {
        // Заготовка могла доспеть, пока сторож спал, — тогда сторожить нечего.
        val stuck = pending.filter {
            it.value.kind == Pending.Kind.FILE && it.value.text == text && !it.value.cancelled
        }
        if (stuck.isEmpty()) return
        // 05.10.2026: движок ещё поднимает новый голос — не трогаем его вовсе
        // (см. [armVoiceWarmup]). Сторож мог быть взведён ещё до смены голоса;
        // тогда просто ждём остаток окна. Ни переспроса, ни перезапуска: в
        // журнале Сержа 16:49 именно они и съедали загрузку нового голоса.
        if (warmingVoice()) {
            Diag.log(
                appContext, "tts",
                "окно терпения (осталось ${warmLeftMs() / 1000} с) — " +
                    "фразу не переспрашиваю, движок не перезапускаю"
            )
            armSynthWatch(text)
            return
        }
        // Окно прогрева кончилось, а фразы нет — дальше обычная лестница мер.
        // Засечку «сколько движок готовит первую фразу» НЕ снимаем: ответ может
        // прийти и после лестницы (журнал 01:18: движок ответил на двадцатой
        // секунде, когда мы уже сказали фразу напрямую) — и это как раз то число,
        // которое надо запомнить (см. [noteFirstPrep]).
        if (voiceWarmUntilMs != 0L) {
            voiceWarmUntilMs = 0L
            Diag.log(
                appContext, "tts",
                "движок не отозвался за ${voiceWarmMs / 1000} с — дальше обычные меры"
            )
        }
        // 05.10.2026 (журнал Сержа 18:18, «читает первую фразу и встаёт»): движок
        // СЕЙЧАС ГОВОРИТ САМ (разовая прямая речь), а файлы в это время не делает —
        // TeraTTS обслуживает заявки на синтез, только когда договорил. Наши
        // заготовки впрок по этой причине дохли по сторожу, сторож шёл по лестнице
        // и перезапускал движок ПРЯМО ПОСРЕДИ живой речи. Перезапуск её обрывал, а
        // «доиграла» по оборванной фразе уже не приходила — чтение вставало
        // насовсем. Пока движок говорит сам, не трогаем его вовсе: файлы он
        // сделает, когда освободится (в том же журнале они и доспели сразу после
        // конца фразы).
        if (directSpeakingText != null) {
            armSynthWatch(text, shortFuse = false)
            return
        }
        val stuckPos = stuck.values.first().pos
        if (stuck.values.any { it.role == Pending.Role.REPLY }) {
            // 29.09.2026 (журнал 20:10, жалоба Сержа «включено чтение по ролям, а
            // читает одним голосом»): здесь мы СРАЗУ отказывались от ролей до конца
            // сеанса — из-за одной потерянной заявки у сетевого голоса реплик.
            // Хуже того, фразу мы тут же заказывали основным голосом, и она звучала
            // ещё раз (та самая «фраза два раза»). Теперь даём движку реплик второй
            // срок: заявку НЕ выбрасываем, просто ждём ещё столько же. Отказываемся
            // от ролей только на втором промахе подряд, и тогда уже перечитываем
            // фразу основным голосом — иначе текст пропадёт.
            if (replyMisses < REPLY_MISS_LIMIT) {
                replyMisses++
                Diag.log(
                    appContext, "tts",
                    "движок реплик молчит — жду его ещё раз, роли не бросаю " +
                        "(${text.take(30)}…)",
                )
                armSynthWatch(text, shortFuse = false)
                return
            }
            // Молчит и второй раз — перезапускать его на каждой реплике значит
            // гадать. Возвращаемся к основному голосу и говорим об этом в журнале.
            replyBroken = true
            replyFalls++
            Diag.log(
                appContext, "tts",
                "движок реплик молчит дважды — читаю реплики основным голосом"
            )
            stuck.forEach { (id, p) ->
                p.cancelled = true
                p.file?.delete()
                pending.remove(id)
            }
            dropReplyEngine()
            synthToFile(text, stuckPos)
            return
        }
        if (soundPlaying()) {
            // Играет предыдущая фраза: движок сейчас не трогаем, иначе оборвём звук.
            // Ждём полный срок: с коротким запалом этот надзор просто крутился бы
            // вхолостую каждую секунду, пока звучит фраза.
            armSynthWatch(text, shortFuse = false)
            return
        }
        // Реальное время молчания, а не номинал сторожа: если часы «убежали»
        // далеко за срок запала — значит процесс спал (msg4211, #19).
        val nominalSec = synthFuseFor(text, synthMissesOf(text) > 0, started = false)
        val waited = ((SystemClock.elapsedRealtime() - watchFromMs) / 1000).toInt()
            .coerceAtLeast((nominalSec / 1000).toInt())
        stuck.forEach { (id, p) ->
            p.cancelled = true
            p.file?.delete()
            pending.remove(id)
        }
        // 23.10.2026: набор «в работе» больше не отдельный — заявки сняты выше,
        // из [pending] они уже ушли, и больше про них помнить нечего.
        val wanted = text == awaitingPlayText
        // 05.10.2026 (журнал 20:12, «непонятная пауза при листании»): ЗАГОТОВКА
        // ВПРОК не стоит перезапуска движка. Её никто не ждёт, и очередь закажет
        // её заново обычным порядком ([requestPrefetch] на каждом конце фразы), а
        // перезапуск выбрасывает ВСЁ, что в работе, — в том числе фразу, которую
        // чтение ждёт. В том журнале так и вышло: 20:12:47 сторож перезапустил
        // движок из-за заготовки «Перед ними открывалась перспектива…», жданная
        // «Сноска. И. Н-в…» пропала вместе с конвейером, и чтение замолчало до
        // самого звонка (11 секунд тишины). Пометку «медленный» такая заготовка
        // тоже больше не зарабатывает: промахи впрок — не болезнь движка.
        if (!wanted) {
            Diag.log(
                appContext, "tts",
                "заготовка впрок движку не далась (${text.take(40)}…) — движок не трогаю, " +
                    "очередь закажет её снова"
            )
            return
        }
        // msg4103: первый обрыв — переспрашиваем фразу заново, НЕ трогая движок.
        // Лог пользователя (ivona.tts, RMX3472): движок терял одну-единственную
        // заявку, а следующие обслуживал исправно — предл. 146 зазвучал через
        // 1.1 с после начала синтеза. Перезапуск движка — тяжёлая мера (заново
        // init, голос, скорость), берегём её для второго обрыва подряд.
        if (synthMissesOf(text) == 0 && ready) {
            // 05.10.2026: здесь стояло лечение смены голоса перезапуском движка
            // («движок молчит после смены голоса — сразу перезапускаю»). Для
            // TeraTTS это оказалось худшим из возможного: перезапуск бросал
            // начатую загрузку нового голоса, и каждая следующая попытка выходила
            // не быстрее прежней (журнал 16:38-16:51, три смены голоса по 13-18 с
            // тишины). Теперь смену голоса закрывает окно прогрева
            // ([armVoiceWarmup]), а сюда мы попадаем уже после него — значит,
            // работает обычная лестница: сперва переспрос, перезапуск потом.
            // 30.09.2026 (сборка 227): у движка УЖЕ есть голос, который файл не
            // отдал, а этот голос сам заявляет сеть — второго захода за файлом не
            // делаем. В журнале Сержа проба файла стоила 5,1 с тишины на каждой из
            // первых двух фраз нового голоса; здесь остаётся один срок (2,5 с), и
            // фраза звучит напрямую. Google не задевает: у него провалов нет
            // вовсе, и подозрительным движок не станет.
            if (netSuspectEngine) {
                Diag.log(
                    appContext, "tts",
                    "синтез молчит $waited с (${text.take(40)}…) — у движка файл уже " +
                        "не проходил, второй раз не прошу: читаю напрямую",
                )
            } else {
                synthMisses[text] = 1
                // Сюда попадает только фраза, которую ЖДЁТ чтение: заготовки впрок
                // выходят выше, не трогая движок; переспрашиваем заново, заявку
                // выбрасываем (она уже снята выше).
                Diag.log(appContext, "tts",
                    "синтез молчит $waited с (${text.take(40)}…) — переспрашиваю фразу заново")
                synthToFile(text, stuckPos)
                return
            }
        }
        // Перезапуск движка — мера для ЛОКАЛЬНОГО движка, потерявшего заявку.
        // Сетевому он вредит: заявка в пути выбрасывается, и мы теряем то, что
        // вот-вот пришло бы (журнал Сержа 01:13 — так и набирались паузы по
        // 14 с на фразу). У сетевого вместо перезапуска сразу прямая речь.
        if (retriesInRow < timing.restarts) {
            retriesInRow++
            Diag.log(
                appContext, "tts",
                "движок молчит $waited с (${text.take(40)}…) — перезапускаю движок, попытка $retriesInRow"
            )
            if (wanted) {
                retryAfterRestart = text
                retryAfterRestartPos = stuckPos
                retryAfterRestartPart = stuck.values.first().part
            }
            start(enginePackage)
            return
        }
        if (netSynth) {
            Diag.log(
                appContext, "tts",
                "движок молчит $waited с (${text.take(40)}…) — читаю фразу напрямую, движок не трогаю"
            )
            // Файловый путь у этого движка не работает — считаем промахи подряд и
            // после второго переходим на прямую речь совсем (см. [markNetDirect]).
            // Сетевому голосу на движке, где файл уже не проходил, хватает и
            // одного промаха: второй заход мы и не делали (см.
            // [netSuspectEngine]).
            netFileFails++
            if (netFileFails >= DIRECT_MODE_HITS || netSuspectEngine) {
                markNetDirect("не отдал файл $netFileFails раз подряд")
            }
        } else {
            Diag.log(appContext, "tts", "движок молчит $waited с и перезапуски не помогли — фразу пропускаю")
        }
        // Учимся на этом случае: движок не отдал фразу ни по первой заявке, ни
        // после переспроса и перезапусков. Второй такой раз подряд — и он
        // помечается медленным (см. [slowHits]): дальше ждём его по-сетевому.
        // Заявленному сетевому учиться не надо, он и так уже с длинными сроками.
        if (!netDeclared) {
            slowHits++
            if (slowHits >= SLOW_HITS_TO_MARK) markSlowSynth("не ответил за $waited с")
        }
        retriesInRow = 0
        if (wanted) onSynthLost(text, currentPos)
    }

    /** Сколько раз подряд движок не отдал файл (см. [markNetDirect]). */
    private var netFileFails = 0

    /** Сколько знаков в секунду движок говорит НА САМОМ ДЕЛЕ (29.09.2026).
     *
     *  Наша оценка [Timing.charsPerSec] верна для локальных движков, а сетевой голос
     *  mstrans нашу скорость, похоже, не слушает: в журнале 02:37 пять фраз в
     *  81-132 знака звучали по 5,1 с каждая, то есть около 20 знаков в секунду
     *  вместо ожидаемых 50 на скорости 3,3. Из-за этой ошибки ВСЕ сроки ожидания
     *  у сетевого движка были втрое короче нужного, и мы объявляли живую речь
     *  потерянной: гасили очередь, синтезировали ту же фразу заново — это и были
     *  повторы фраз, которые услышал Серж, — а иногда и вовсе пропускали фразу.
     *
     *  Теперь меряем сами: длина фразы делится на время от «начал говорить» до
     *  «закончил», значение сглаживается. [observedAtSpeed] — скорость, при
     *  которой мерили: движок, который скорость всё-таки слушает, заговорит
     *  быстрее, и срок должен поехать за ней. */
    private var observedCharsPerSec = 0f
    private var observedAtSpeed = 1f

    /** Когда началась прямая фраза — по ней считаем настоящую скорость речи. */
    private val directStartedAt = HashMap<Long, Long>()

    /** Оценка темпа речи для сроков ожидания. Нет замера — берём прежнюю
     *  константу, а для сетевого движка сразу осторожную треть от неё: он уже
     *  показал, что медленный. */
    private fun charsPerSec(): Float {
        val base = if (observedCharsPerSec > 0f) {
            observedCharsPerSec * (speed / observedAtSpeed).coerceIn(0.25f, 4f)
        } else {
            // Нет замера — своя оценка из [Timing]: у медленного движка она
            // втрое осторожнее (15 против 5 знаков в секунду).
            timing.charsPerSec
        }
        return base.coerceIn(2f, 80f)
    }

    /** Запомнить замер темпа по закончившейся прямой фразе. */
    private fun noteSpokenRate(id: Long, chars: Int) {
        val from = directStartedAt.remove(id) ?: return
        val heardTo = directHeardTo.remove(id)
        val sec = (SystemClock.elapsedRealtime() - from) / 1000f
        if (sec < 0.5f || chars < 8) return
        val rate = chars / sec
        if (rate !in 2f..120f) return
        observedCharsPerSec = if (observedCharsPerSec > 0f) {
            observedCharsPerSec * 0.7f + rate * 0.3f
        } else {
            rate
        }
        observedAtSpeed = speed
        // 05.10.2026 (жалоба «в конце пауза после слова „еду“», журнал 21:52).
        // Сетевой движок готовит речь куском и берёт следующий кусок уже во
        // время звучания предыдущего: после КОРОТКОГО куска он не успевает, и
        // слышна пауза ВНУТРИ фразы. По одному лишь onDone этого не видно —
        // поэтому пишем фразу, которая звучала заметно дольше, чем ей положено
        // по темпу, и (если движок сообщает) знак, до которого он дошёл.
        val expected = chars / charsPerSec() * 1000f
        if (sec * 1000f > expected * 1.5f + 1500f) {
            Diag.log(
                appContext, "tts",
                "движок тянул фразу: $chars знаков звучали ${"%.1f".format(sec)} с " +
                    "(по темпу ждали ${"%.1f".format(expected / 1000f)} с)" +
                    if (heardTo != null) ", дошёл до знака $heardTo из $chars" else ""
            )
        }
        // В журнал — по замеру видно, верна ли наша оценка темпа. Жалоба Сержа
        // «в альтернативном режиме были повторы фраз» разбиралась именно по ней.
        if (++rateMeasures % 5 == 1) {
            Diag.log(
                appContext, "tts",
                "темп речи движка: ${"%.1f".format(observedCharsPerSec)} знаков в секунду " +
                    "(скорость ${RateSteps.label(observedAtSpeed)}; считаем по " +
                    "${"%.1f".format(charsPerSec())} — от этого сроки ожидания)"
            )
        }
    }

    /** Сколько замеров темпа сделано (для журнала). */
    private var rateMeasures = 0
    private var rescueText: String? = null
    private var rescueTries = 0

    /** Взвести надзор за прямой речью движка: `speak()` мог отчитаться успехом и
     *  потом промолчать — тогда `onDone` не придёт и чтение встанет.
     *
     *  23.09.2026: срок считаем, а не берём одним числом (было 180 с — три минуты
     *  тишины). Пока движок не подал сигнал «начал говорить», ждём
     *  [Timing.directStartMs] и пропускаем фразу: Сергей выбрал самую короткую тишину
     *  («чем можно пренебречь»), поэтому переспроса и перезапуска движка в этом
     *  режиме нет — они стоили бы ещё четыре секунды. Цена: если движок просто
     *  потерял одну заявку, фраза теряется. Вернуть переспрос — правка на пять
     *  строк, записано в docs/TODO.md. Пришёл сигнал «начал говорить» — считаем по
     *  длине фразы ([directFuseMs]).
     *
     *  С очередью ([directQueue]) срок на СТАРТ взводится только у первой фразы:
     *  у той, что стоит в очереди за другими, свой срок начинается не сейчас, а
     *  после них, и короткий запал сработал бы вхолостую. Дальше надзор ведёт
     *  сигнал «начал говорить» — он приходит на каждую фразу очереди. */
    private fun armDirectWatch(id: Long, started: Boolean = false) {
        val token = ++directWatchToken
        val text = pending[id]?.text
        val fuse = if (started) directFuseMs(text) else directStartMs()
        if (started) {
            Diag.log(
                appContext, "tts",
                "прямая речь началась: стерегу ${fuse / 1000} с " +
                    "(фраза ${text?.length ?: 0} знаков: «${text?.take(30) ?: ""}», скорость $speed)",
            )
        }
        main.postDelayed({
            if (token != directWatchToken) return@postDelayed
            // 23.10.2026: заявку не выбрасываем сразу — в ней место и кусок
            // потерянной единицы, по ним сообщим чтению и по ним же её спасём.
            val lost = pending.remove(id) ?: return@postDelayed
            // Сетевому движку даём ещё попытку, прежде чем терять фразу
            // (29.09.2026, см. [rescueAgain]).
            if (netSynth && rescueAgain(lost.text, lost.pos, lost.part)) return@postDelayed
            // Движок стоит на этой фразе, а следующие уже за ней у него в
            // очереди: без очистки они прозвучат после молчания, и наша закладка
            // разъедется со звуком. Гасим очередь и просим заново со следующей
            // фразы — её пришлёт читалка по onDone (см. [speakDirectQueued]).
            flushDirectQueue("фраза не зазвучала")
            Diag.log(
                appContext, "tts",
                "прямая речь молчит ${fuse / 1000} с — пропускаю фразу, чтение идёт дальше"
            )
            // 30.09.2026: заминка прямой речи — в память окна «Не засыпать».
            StallLog.record(appContext, "прямая речь молчала ${fuse / 1000} с")
            retriesInRow = 0
            reportDone(lost.pos, lost.part, lastOfPhrase(lost.pos, lost.part))
        }, fuse)
    }

    /** Единица речи прямой речи от читалки. Обычный случай — она уже стоит В ГОЛОВЕ
     *  очереди движка (мы наполнили её заранее, [topUpDirectQueue]): тогда не
     *  трогаем ничего, движок сам её скажет, и паузы на стыке не будет вовсе.
     *  Другая единица (прыжок по тексту, повтор предложения, пауза → продолжить) —
     *  старая очередь движку больше не нужна, выбрасываем и начинаем с этой.
     *
     *  26.09.2026: раньше здесь искали фразу по ВСЕМУ тексту очереди. В сборнике
     *  анекдотов короткие реплики повторяются («— Да.», «— Нет.»), и повторная
     *  фраза считалась уже заказанной: своего места в очереди она не получала,
     *  движок её не произносил, а читалка шла дальше — на слух это «фраза
     *  зациклилась» и «не могу остановить». Теперь сверяемся с ГОЛОВОЙ очереди.
     *
     *  23.10.2026, рефакторинг: сверки идут по КЛЮЧУ единицы речи ([Units.key] =
     *  место в книге + кусок), а не по тексту, и в очередь кладутся ВСЕ куски
     *  этой фразы ([rest]) сразу за головой. Текст опознанием быть не может: две
     *  одинаковые реплики из разных мест книги — разные единицы. */
    private fun speakDirectQueued(
        text: String,
        pos: Long = -1L,
        part: Int = 0,
        userAsked: Boolean = false,
        rest: List<String> = emptyList(),
    ) {
        val key = Units.key(pos, part)
        // 29.09.2026: фраза, которая ЗВУЧИТ прямо сейчас, — не повод гасить движок.
        // Чтение иногда называет её повторно, и ветка «пришла другая фраза» ниже
        // обрывала её на полуслове командой «стоп» (а по документации stop() —
        // это ровно «прервать текущее произнесение и выбросить очередь»). Фраза и
        // так звучит: её «доиграла» и будет тем сигналом, которого чтение ждёт.
        val sounding = if (key >= 0) {
            key == directSpeakingKey
        } else {
            directSpeakingText != null && text == directSpeakingText
        }
        if (sounding && directQueue.isNotEmpty()) {
            Diag.log(
                appContext, "sound",
                "альтернативный способ: эта фраза уже звучит (${text.length} знаков) — очередь не трогаю"
            )
            return
        }
        val front = directQueue.firstOrNull()
        val frontPending = front?.let { pending[it] }
        val frontSame = frontPending != null && if (key >= 0) {
            frontPending.key == key
        } else {
            frontPending.pos == pos && frontPending.text == text
        }
        if (frontSame) {
            directAskedId = front
            Diag.log(
                appContext, "sound",
                "альтернативный способ: фраза уже в голове очереди движка " +
                    "(${text.length} знаков): ${text.take(40)}"
            )
            topUpDirectQueue()
            return
        }
        // 23.10.2026: эта единица уже звучала в этом проходе, а просит её САМА
        // читалка (по ходу книги) — второй раз вперёд не читаем. Та же защита,
        // что в файловом пути ([speakExo], ветка «уже прозвучала»).
        if (!userAsked && key >= 0 && playedKeys.contains(key)) {
            Diag.log(
                appContext, "sound",
                "альтернативный способ: единица ${Units.labelOfKey(key)} уже звучала — " +
                    "второй раз по ходу книги не читаю"
            )
            reportDone(pos, part, lastOfPhrase(pos, part))
            return
        }
        flushDirectQueue("пришла другая фраза: «${text.take(40)}» (${text.length} знаков)")
        if (!queueDirect(text, pos, part)) {
            // Движок реплик поднимается — фразу не теряем и не отдаём чужому
            // голосу: повторим заказ, когда он поднимется (27.09.2026).
            if (directWaitReply) {
                retryDirectLater(text, pos, part, userAsked, rest)
                return
            }
            // ——— ДВИЖОК НЕ ВЗЯЛ ФРАЗУ — ЭТО НЕ ЗВУК (24.10.2026, проба 264) ———
            //
            // Жалоба Сержа «текст убежал»: 17:33 книжка прошла с главы 46 до
            // «Книга прочитана» за 1,7 секунды без единого звука. В журнале —
            // НИ ОДНОЙ строки «начал речь», «готово» или «считаю фразу молчащей»:
            // движок (dev.msvoice.tts, голос «MS Dariya RU») ОТКАЗЫВАЛСЯ принять
            // заявку, `queueDirect` возвращал false, и здесь сразу шёл
            // [reportDone] — то есть чтение считало, что фраза прозвучала.
            // Вся защита от убегания ([noteSilentPhrase], [ackLooksSilent],
            // придержка отчёта) стоит на путях, где фраза ХОТЬ КУДА-ТО попала:
            // отказ движка проходил мимо неё.
            //
            // Теперь отказ считается тем, чем он и является: «движок не дал
            // звука». Счётчик фраз подряд поднимет движок заново, а после
            // `timing.silentStopAt` (на первой фразе после старта — двух) чтение
            // встанет, вернётся на место и скажет об этом вслух.
            Diag.log(
                appContext, "tts",
                "движок не взял фразу (${directRefusedReason ?: "причина неизвестна"}): " +
                    "«${text.take(40)}» (${text.length} знаков) — считаю это молчанием, а не звуком",
            )
            if (!noteSilentPhrase(pos)) reportDone(pos, part, lastOfPhrase(pos, part))
            return
        }
        // Остальные куски ТОЙ ЖЕ фразы — сразу за головой и ДО заказа впрок:
        // иначе они встанут после следующих фраз, и чтение, попросив их, погасит
        // очередь движка посреди уже начавшейся чужой речи.
        var p = part
        for (t in rest) {
            p++
            registerParts(pos, p + 1)
            if (t.isBlank()) continue
            if (directQueue.any { pending[it]?.key == Units.key(pos, p) }) continue
            if (!queueDirect(t, pos, p)) break
        }
        if (rest.isNotEmpty()) registerParts(pos, part + rest.size + 1)
        directAskedId = lastDirectQueuedId
        topUpDirectQueue()
    }

    /** Повторить заказ в альтернативном способе, когда поднимется движок реплик.
     *  null в [text] — просто наполнить очередь. 23.10.2026: повторяется ТА ЖЕ
     *  единица речи (место + кусок + куски фразы), а не «текст, который сейчас
     *  считается текущим». */
    private fun retryDirectLater(
        text: String?,
        pos: Long = -1L,
        part: Int = 0,
        userAsked: Boolean = false,
        rest: List<String> = emptyList(),
    ) {
        main.postDelayed({
            if (!directWaitReply) return@postDelayed
            // Фразу уже сменили — повторять нечего (сверка по ключу, не по тексту).
            if (text != null && Units.key(pos, part) != Units.key(currentPos, currentPart)) {
                return@postDelayed
            }
            if (text == null) topUpDirectQueue() else speakDirectQueued(text, pos, part, userAsked, rest)
        }, REPLY_WAIT_STEP_MS)
    }

    /** Отдать движку ещё одну фразу В КОНЕЦ очереди. false — движок отказался
     *  или очередь занята репликой другой роли (тогда ждём, пока доиграет).
     *
     *  26.09.2026 (просьба Сержа): в альтернативном способе реплики тоже читает
     *  второй движок. У каждого движка СВОЯ очередь, и если отдать им фразы
     *  вперемешку, они зазвучат внахлёст. Поэтому очередь наполняем только
     *  фразами одной роли: дошли до смены роли — не заказываем дальше, ждём,
     *  пока текущая доиграет, и следующую отдаём уже другому движку. Внутри
     *  реплики и внутри повествования стык остаётся бесшовным, а на смене роли
     *  слышна короткая пауза — цена двух движков в этом режиме.
     *
     *  30.09.2026: когда голос реплик выбран в ТОМ ЖЕ движке, что книга, второго
     *  экземпляра нет — основной берётся в долг под реплику, как в файловом
     *  способе (см. [borrowMainForReply]). Роли работают и здесь. */
    private fun queueDirect(text: String, pos: Long = -1L, part: Int = 0): Boolean {
        if (tts == null || !ready) {
            directRefusedReason = "движок ещё не готов"
            return false
        }
        directRefusedReason = null
        directWaitReply = false
        val key = Units.key(pos, part)
        // 23.10.2026: эта единица уже отдана движку — второй раз не отдаём
        // (иначе она прозвучит дважды). Опознание по ключу: по тексту нельзя,
        // короткие реплики в книгах повторяются дословно.
        if (key >= 0 && directQueue.any { pending[it]?.key == key }) return true
        // 30.09.2026 (Серж: «в настройках написано, что роли здесь не работают,
        // а они работают»): в этом способе реплики читаются ТАК ЖЕ, как в
        // файловом. Свой экземпляр нужен, только когда голос реплик живёт в
        // другом движке; когда движок один, берём его в долг под реплику —
        // ровно как это делает synthToFile (см. [borrowMainForReply]). До этой
        // правки реплика в таком случае уходила основному голосу, и роли в
        // альтернативном способе пропадали.
        val own = replyNeedsOwnInstance()
        val wantReply = replyOn && Roles.looksReplica(text) && (!own || !replyBroken)
        // 27.09.2026: движок реплик ещё поднимается — реплику основному голосу
        // не отдаём (это слышно), а просто ждём его: заказ повторим сами.
        if (wantReply && own && waitForReply(text, pos, part)) {
            directWaitReply = true
            directRefusedReason = "поднимается движок реплик"
            return false
        }
        forgetReplyWait()
        val rt = if (wantReply && own) replyInstance() else null
        val sameEngine = wantReply && !own
        val role = if (rt != null || sameEngine) Pending.Role.REPLY else Pending.Role.MAIN
        // 23.10.2026: очередь делим по ДВИЖКАМ, а не по ролям. Когда движок один
        // (реплики читаются его же голосом, см. [borrowMainForReply]), очередь у
        // него общая: голос ставится на объект перед каждым заказом и запоминается
        // вместе с заявкой. Прежняя сверка по роли рвала здесь очередь на каждой
        // смене роли, и следующий кусок фразы снова стоил `tts.stop()` посреди
        // речи. Два РАЗНЫХ экземпляра по-прежнему не смешиваем: у них разные
        // очереди, и внахлёст они зазвучат.
        if (own) {
            val lastRole = directQueue.lastOrNull()?.let { pending[it]?.role }
            if (lastRole != null && lastRole != role) {
                directRefusedReason = "ждём, пока доиграет фраза другой роли"
                return false
            }
        }
        val t = rt ?: tts ?: run {
            directRefusedReason = "нет экземпляра движка"
            return false
        }
        val borrowed = role == Pending.Role.REPLY && sameEngine
        if (role == Pending.Role.REPLY) {
            if (borrowed) borrowMainForReply(t) else applyReplyParams(t)
        }
        val idle = directQueue.isEmpty()
        val id = reqSeq++
        pending[id] = Pending(Pending.Kind.DIRECT, text, null, role = role, pos = pos, part = part)
        directAskedAt[id] = SystemClock.elapsedRealtime()

        // ——— ПРОВЕРКА «СЛОМАННЫЙ ДВИЖОК» (24.10.2026, за секретной дверью) ———
        //
        // Жалоба Сержа: «синтезатор был нерабочий, нажал читать — книжка начала
        // быстро прокручиваться». Настоящую поломку ловить долго, а повторять её
        // надо по заказу. Эта галочка заставляет НАШ плеер вести себя ровно так:
        // фразу движку НЕ отдаём, а через мгновение рапортуем «готово» и звука не
        // даём. Дальше всё идёт обычным путём ([synthFinished] → `directAckHoldMs`
        // → [ackLooksSilent]), поэтому по журналу видно, ловит ли защита такой
        // отчёт и говорит ли об этом вслух. В телефоне ничего не ломается.
        if (ExpertPrefs.brokenEngine(appContext)) {
            if (brokenEngineLogged < BROKEN_ENGINE_LOG_MAX) {
                brokenEngineLogged++
                Diag.log(
                    appContext, "tts",
                    "ПРОВЕРКА «сломанный движок»: фразу движку не отдаю, через " +
                        "$BROKEN_ENGINE_ACK_MS мс рапортую «готово» без звука " +
                        "(${text.length} знаков): ${text.take(40)}"
                )
            }
            directQueue.addLast(id)
            lastDirectQueuedId = id
            main.postDelayed({ synthFinished(id) }, BROKEN_ENGINE_ACK_MS)
            return true
        }

        // ——— ПРОВЕРКА «ДВИЖОК ОТКАЗЫВАЕТСЯ» (24.10.2026, за секретной дверью) ———
        //
        // Ровно то, что было у Сержа 17:33: каждая заявка получает отказ. Раньше
        // такой отказ считался прозвучавшей фразой, и книжка убегала (см.
        // [speakDirectQueued]). Галочка нужна, чтобы эту дорогу можно было
        // проверить по заказу.
        if (ExpertPrefs.brokenRefuse(appContext)) {
            if (brokenRefusedLogged < BROKEN_ENGINE_LOG_MAX) {
                brokenRefusedLogged++
                Diag.log(
                    appContext, "tts",
                    "ПРОВЕРКА «движок отказывается»: заявку не отдаю, отвечаю отказом " +
                        "(${text.length} знаков): ${text.take(40)}"
                )
            }
            pending.remove(id)
            directAskedAt.remove(id)
            directRefusedReason = "проверка «движок отказывается»"
            return false
        }

        val baseVol = if (role == Pending.Role.REPLY) replyVolume else volume
        val vol = baseVol.coerceIn(0f, 1f)
        val params = android.os.Bundle().apply {
            putFloat(TextToSpeech.Engine.KEY_PARAM_VOLUME, vol)
            // 30.09.2026: выше 100% движку не заказать — добавку делает наш
            // усилитель, и ему нужен тот же звуковой сеанс (см. [applyDirectBoost]).
            // Ниже 100% сеанс не передаём вовсе: пусть движок работает как раньше.
            if (baseVol > 1f) {
                applyDirectBoost()
                val s = boostSessionId()
                if (s > 0) putInt(TextToSpeech.Engine.KEY_PARAM_SESSION_ID, s)
            }
        }
        var r = runCatching { t.speak(Roles.stripped(text), TextToSpeech.QUEUE_ADD, params, id.toString()) }
            .getOrDefault(TextToSpeech.ERROR)
        // Голос реплик брали у основного экземпляра в долг — возвращаем сразу:
        // движок запоминает голос вместе с заявкой (как и в файловом способе).
        if (borrowed) restoreMainParams(t)
        if (r != TextToSpeech.SUCCESS && role == Pending.Role.REPLY) {
            // Второй движок отказался — фразу читает основной, порядок не рвём.
            val main = tts ?: return false
            Diag.log(appContext, "tts", "движок реплик отказался говорить — читаю фразу основным голосом")
            pending[id] = Pending(
                Pending.Kind.DIRECT, text, null,
                role = Pending.Role.MAIN, pos = pos, part = part,
            )
            r = runCatching { main.speak(Roles.stripped(text), TextToSpeech.QUEUE_ADD, null, id.toString()) }
                .getOrDefault(TextToSpeech.ERROR)
        }
        if (r != TextToSpeech.SUCCESS) {
            pending.remove(id)
            // Отказ движка — это НЕ звук (см. [speakDirectQueued], 24.10.2026).
            directRefusedReason = "движок отказался принять заявку (код $r)"
            return false
        }
        directQueue.addLast(id)
        lastDirectQueuedId = id
        // Срок на СТАРТ взводим, только когда движок и правда молчит. Пустой
        // очереди для этого мало: фразу движок забирает в работу и СРАЗУ
        // выбрасывает из очереди (по сигналу «начал говорить»), а звучать она
        // будет ещё долго. 06.10.2026, журнал 20:49:27: короткий запал (2 с)
        // взводился на фразу, стоящую ЗА звучащей, срабатывал посреди чужой речи,
        // гасил очередь движка и обрывал звучащую фразу — Серж не услышал
        // предложение («Проглянуло солнце. Подводы нагружены…» оборвалось).
        // Теперь звучащая фраза держит свой надзор «начал говорить», а следующая
        // получит свой, когда движок начнёт и её.
        if (idle && directSpeakingText == null) armDirectWatch(id)
        return true
    }

    /** Сколько РАЗНЫХ ФРАЗ книги стоит в очереди движка ДАЛЬШЕ той, которую чтение
     *  назвало последней. Куски одной фразы считаются ОДНОЙ фразой — иначе
     *  двухкусковая фраза сдвигала бы отсчёт, и чтение называло бы фразу через
     *  одну (23.10.2026, П2: очередь считает куски, `onNeedNext` ждёт фразы). */
    private fun directPhrasesAhead(): Int {
        val from = currentPos
        val seen = HashSet<Long>()
        for (id in directQueue) {
            val p = pending[id] ?: continue
            if (p.pos < 0) continue
            if (from >= 0 && p.pos <= from) continue
            seen.add(p.pos)
        }
        return seen.size
    }

    /** Эта фраза уже отдана движку (любой её кусок стоит в очереди). */
    private fun directQueuedPhrase(pos: Long): Boolean =
        if (pos < 0) false else directQueue.any { pending[it]?.pos == pos }

    /** Держать у движка [directAhead] ФРАЗ впереди — тогда он берёт их подряд
     *  без пауз. Что звучит следующим, спрашиваем у читалки тем же [onNeedNext],
     *  каким в обычном режиме заказываем заготовки: она единственный источник
     *  правды о том, что дальше, и сама обрывает список на конце главы, конце
     *  книги и на границе выделенного куска.
     *
     *  29.09.2026, история про счёт (остаётся в силе). Очередь отсчитывается от
     *  фразы, которую чтение назвало ПОСЛЕДНЕЙ. Без этого та же фраза вставала в
     *  очередь второй раз: журнал Сержа 13:41:28 — фраза в 80 знаков прозвучала
     *  дважды, а следующую мы оборвали.
     *
     *  23.10.2026, рефакторинг (П2, П3). Было: `ahead = directQueue.size + …`, то
     *  есть считали КУСКИ в очереди, а `onNeedNext` ждёт смещение в ФРАЗАХ. У
     *  фразы с репликой кусков два, поэтому смещение выходило вдвое больше
     *  нужного: фраза сразу после текущей в очередь НЕ попадала. Когда чтение
     *  доходило до неё, голова очереди была уже другой фразой, и
     *  [speakDirectQueued] гасил всю очередь (`tts.stop()`) — посреди уже
     *  начавшейся чужой фразы. На слух: фраза начинается, обрывается и звучит
     *  снова. Теперь: (1) считаем ФРАЗЫ ([directPhrasesAhead]); (2) кладём в
     *  очередь ВСЕ куски фразы с их номерами; (3) уже заказанную фразу не
     *  заказываем второй раз ([directQueuedPhrase]), а если она попала в
     *  смещение — берём следующую. */
    private fun topUpDirectQueue() {
        // Сколько ФРАЗ держим у движка впереди. Режим «по одной фразе» (движок-
        // прослойка, см. [directAhead]) — это ровно ноль фраз впереди: в очереди
        // стоит только текущая фраза со всеми её кусками (куски обязаны стоять
        // рядом с головой, иначе их заказ гасит очередь). Иначе — [directAhead]
        // фраз, как и было задумано.
        val ahead = directAhead
        val limit = if (ahead <= 1) 0 else ahead - 1
        // Страховка от бесконечного шага: фразу могли уже заказать (тогда смещение
        // растёт дальше) или чтение может назвать не больше, чем есть.
        val guard = limit + 4
        var steps = 0
        var offset = 0
        while (directPhrasesAhead() < limit && steps++ < guard) {
            offset++
            val frags = onNeedNext?.invoke(offset) ?: return
            if (frags.isEmpty()) return
            val pos = frags.first().second
            if (pos < 0) return
            if (directQueuedPhrase(pos)) continue
            // Сколько кусков у фразы — по этому числу [lastOfPhrase] решает,
            // можно ли двигать место в книге (см. [registerParts]).
            registerParts(pos, frags.count { it.second == pos })
            var queuedAny = false
            for ((next, _, part) in frags) {
                if (next.isBlank()) continue
                // Никаких сверок по тексту: очередь движка — это ПОРЯДОК единиц
                // речи, и каждая заявка получает своё место, даже если текст
                // совпадает с соседней (короткие реплики повторяются постоянно).
                if (!queueDirect(next, pos, part)) {
                    // Движок реплик поднимается или очередь занята другим
                    // экземпляром — наполним, когда он будет готов (27.09.2026).
                    if (directWaitReply) retryDirectLater(null)
                    return
                }
                queuedAny = true
                Diag.log(
                    appContext, "sound",
                    "альтернативный способ: в очереди движка ${directQueue.size} " +
                        "(фраз впереди ${directPhrasesAhead()} из $limit; " +
                        "заказал ${Units.label(pos, part)} «${next.take(30)}», " +
                        "${next.length} знаков)"
                )
            }
            if (!queuedAny) return
        }
    }

    // 05.10.2026 (жалоба «в конце пауза после слова „еду“», журнал 21:52) — мысль
    // на будущее, в код НЕ внесена (Серж: «пока ничего не вноси, вроде бы
    // нормально всё звучит»). Пауза была ВНУТРИ фразы: «Еду. При отправке
    // никакого порядка. …» (80 знаков, первое предложение — 4 знака) ушла движку
    // заранее, он начал её ровно в стык, и мы её не трогали. А через 36 мс после
    // её начала мы отдали движку следующую заявку (105 знаков), и пауза встала
    // ровно там: похоже, сетевой работник движка уходит за новой фразой, бросая
    // звучащую на её первом, самом коротком куске (у кусков в 5, 16 и 20 знаков
    // между «начал речь» проходит 1,9-2,1 с, у длинных — зазора нет).
    // Если вернёмся: не отдавать сетевому голосу новую заявку в первые 1,5 с
    // звучания текущей фразы — но только пока очередь и без неё не пуста
    // (`directQueue.size >= 2`), иначе на книге из коротких фраз читалка не
    // найдёт следующую фразу в голове очереди движка, а это уже `flush` с обрывом
    // звука. Условие — `netDeclared`: локальные движки и файловый путь не трогать.

    /** Выбросить всё, что отдано движку в альтернативном способе, вместе с его
     *  собственной очередью. Движок при этом останавливаем — иначе он дочитает
     *  то, что мы уже не считаем своим (прыжок по тексту, пауза, пропуск
     *  застрявшей фразы).
     *
     *  Разовую страховку обычного режима ([fallbackDirect]) это не задевает: там
     *  очередь пуста, и первым же условием мы выходим — гасить движок нельзя, у
     *  него могут быть заявки на синтез в файл. */
    private fun flushDirectQueue(reason: String) {
        if (directQueue.isEmpty()) return
        // 29.09.2026: что именно выбрасываем — в журнал. По одним длинам разбор
        // не шёл (две разные фразы по 74 знака в журнале неразличимы), а по текстам
        // сразу видно, повтор это, пропуск или неверное предсказание очереди.
        val dropped = directQueue.mapNotNull { pending[it]?.text?.take(30) }
        // Засечки выброшенных заявок больше не нужны: без этого карты замеров
        // копили бы по записи на каждую отменённую прыжком фразу.
        directQueue.forEach { directStartedAt.remove(it); directHeardTo.remove(it) }
        directQueue.clear()
        directAskedAt.clear()
        ackSilentInRow = 0
        pending.entries.removeAll { it.value.kind == Pending.Kind.DIRECT }
        directWatchToken++
        runCatching { tts?.stop() }
        // В альтернативном способе реплики мог говорить второй движок — его
        // очередь гасим так же, иначе он дочитает то, что мы уже не считаем своим.
        runCatching { replyTts?.stop() }
        Diag.log(
            appContext, "tts",
            "прямая речь: очередь движка выброшена ($reason)" +
                if (dropped.isEmpty()) "" else " — в ней было: " + dropped.joinToString(" | "),
        )
        directAskedId = null
        directSpeakingText = null
        directSpeakingPos = -1L
        directSpeakingPart = 0
        lastDirectQueuedId = null
    }

    /** Скорость сменилась, а чтение идёт ПРЯМО в движок ([directMode]).
     *
     *  05.10.2026 (жалоба Сержа «на сетевых голосах MultiTTS скорость не
     *  регулируется», журнал 21:36). Движок запоминает темп в тот момент, когда
     *  мы отдаём ему фразу, а отдаём мы три фразы вперёд: после сдвига ползунка
     *  ещё две-три фразы звучали прежним темпом. В том журнале ползунок уже
     *  показывал 2.0, а фразы в 23 и 51 знак шли 5 и 8 знаков в секунду (темп
     *  0.5), и только следующая, отданная после сдвига, пошла 32 знака в
     *  секунду. В файловом пути этой болезни нет: заготовки прежней скорости
     *  выбрасываются ([dropStaleRate]), а звучащую фразу доводит плеер
     *  ([exoSyncSpeed]) — потому локальные голоса и слушаются сразу.
     *
     *  Лечение (решение Сержа 05.10.2026: «пускай та же фраза, но ускоренная
     *  будет»): остановить движок и перечитать ТЕКУЩУЮ фразу новым темпом.
     *  Место чтения при этом не сдвигается: читалка двигается по «фраза
     *  доиграла», а её мы не отдавали. Ждём [DIRECT_RATE_SETTLE_MS], чтобы
     *  движение ползунка (по одной десятой) не перечитывало фразу на каждом
     *  шаге. */
    private fun onDirectRateChanged() {
        if (!directMode) return
        if (directQueue.isEmpty() && directSpeakingText == null) return
        directRateStale = true
        main.removeCallbacks(directRateRunnable)
        main.postDelayed(directRateRunnable, DIRECT_RATE_SETTLE_MS)
    }

    /** Пересоздавать ли соединение с движком при смене скорости
     *  (см. [restartDirectForRate]). Только у помеченной пары: у обычного движка
     *  подмена числа и так доходит, а пересоздание стоило бы секунды тишины на
     *  каждое движение ползунка. */
    private fun renewEngineOnRate(): Boolean = directMode && markedPairNoFiles

    /** Перечитать текущую фразу новым темпом (см. [onDirectRateChanged]). */
    private fun restartDirectForRate() {
        if (!directRateStale) return
        directRateStale = false
        if (!directMode) return
        // В очереди пусто — движку нечего выбрасывать, и новую скорость возьмёт
        // следующая фраза сама. Гасить движок в этом случае нельзя: у него могли
        // остаться заявки на синтез в файл (разовая страховка обычного режима,
        // см. [flushDirectQueue]).
        if (directQueue.isEmpty()) return
        // Реплики книжному ползунку не подчиняются — у них своя скорость: из-за
        // движения книжного ползунка реплику не перечитываем.
        val head = directQueue.firstOrNull()
        if (head != null && pending[head]?.role == Pending.Role.REPLY) return
        // 23.10.2026: перечитываем ЕДИНИЦУ РЕЧИ (место + кусок) и всю фразу с её
        // кусками ([currentRest]) — иначе хвост фразы остался бы в очереди после
        // следующих фраз, и его заказ стоил бы `tts.stop()` посреди живой речи.
        val headPending = head?.let { pending[it] }
        val current = directSpeakingText ?: headPending?.text ?: return
        // Место и кусок берём у ТОЙ единицы, о которой речь: что звучит — у неё,
        // иначе у головы очереди. «Что звучит» важнее: перечитываем именно его.
        val curPos: Long
        val curPart: Int
        if (directSpeakingText != null) {
            curPos = directSpeakingPos
            curPart = directSpeakingPart
        } else {
            curPos = headPending?.pos ?: currentPos
            curPart = headPending?.part ?: 0
        }
        // Куски, которые ещё не звучали: их тоже надо перечитать вместе с головой.
        val curRest = if (curPos >= 0 && curPos == currentPos) {
            currentRest.drop(curPart.coerceAtLeast(0))
        } else {
            emptyList()
        }
        // 06.10.2026 (журнал 18:07:25: ползунок 7.0, а голос читал 13,5 знака в
        // секунду). Движок-прослойка (MultiTTSLexx) передаёт наш темп внутрь
        // MultiTTS только тогда, когда число ОТЛИЧАЕТСЯ от того, что она помнит
        // с прошлого раза, а помнит она его в своём соединении. Одной подмены
        // числа поэтому мало: соединение пересоздаём — ровно так делает FBReader,
        // когда меняешь скорость в его настройках (в системном журнале это видно
        // как «Unbinding TTS engine» и сразу новое подключение). Цена — пауза на
        // подъём движка, и только у помеченной пары ([renewEngineOnRate]).
        if (renewEngineOnRate()) {
            Diag.log(
                appContext, "tts",
                "скорость сменилась на ${RateSteps.label(speed)} — пересоздаю соединение " +
                    "с движком и перечитываю фразу (${current.length} знаков)"
            )
            retryDirectAfterRestart = current
            retryDirectAfterRestartRest = curRest
            retryAfterRestartPos = curPos
            retryAfterRestartPart = curPart
            directSpeakingText = null
            directSpeakingPos = -1L
            directSpeakingPart = 0
            retryAfterRestart = null
            start(enginePackage, rememberAwaiting = false)
            return
        }
        Diag.log(
            appContext, "tts",
            "скорость сменилась на ${RateSteps.label(speed)} — перечитываю фразу " +
                "(${current.length} знаков) новым темпом"
        )
        flushDirectQueue("скорость сменилась на ${RateSteps.label(speed)}")
        speakDirectQueued(current, curPos, curPart, userAsked = true, rest = curRest)
    }

    /** Сигнал движка «начал говорить» пришёл — переводим надзор на срок по длине
     *  фразы. В обычном режиме тот же сигнал приходит про синтез в файл: там свой
     *  надзор, и трогать его не надо. */
    private fun directSpeechStarted(id: Long?) {
        val real = id ?: return
        val p = pending[real] ?: return
        if (p.kind == Pending.Kind.FILE) {
            // 29.09.2026: движок взялся за заявку на синтез в файл. У сетевого
            // движка заявок в работе несколько, и до этого момента заявка могла
            // стоять в очереди движка — теперь срок ожидания честный: считаем от
            // старта, а не от того, когда мы её отдали.
            if (netSynth && !p.cancelled) armSynthWatch(p.text, started = true)
            return
        }
        if (p.kind != Pending.Kind.DIRECT) return
        // Фраза, которая звучит сейчас, — по ней [speakDirectQueued] узнаёт
        // повторный заказ той же единицы и не гасит движок (29.09.2026).
        // 23.10.2026: помним не только текст, но и КЛЮЧ (место + кусок): по тексту
        // одинаковые реплики неразличимы.
        directSpeakingText = p.text
        directSpeakingPos = p.pos
        directSpeakingPart = p.part
        // Засечка «движок начал говорить» — по ней считаем НАСТОЯЩИЙ темп речи
        // (см. [noteSpokenRate]): у сетевого голоса он втрое медленнее нашей
        // константы, и от него зависят сроки ожидания.
        val startedAt = SystemClock.elapsedRealtime()
        directStartedAt[real] = startedAt
        // Движок заговорил — значит он отвечает: счётчик молчащих фраз обнуляем
        // (см. [noteSilentPhrase]).
        silentInRow = 0
        silentFromPos = -1L
        silentRetries = 0
        armDirectWatch(real, started = true)
        // 29.09.2026: очередь движка наполняем сразу, как только он НАЧАЛ фразу, а
        // не когда закончил. Идея Сержа: «следующая фраза готовится чуть раньше и
        // налепляется одна к другой». Раньше заказ следующей уходил только после
        // того, как движок дочитает текущую, — и к её концу у него в запасе могло
        // не остаться ничего, отсюда зазор. Теперь запас всегда есть.
        // Только в прямом чтении: разовая страховка обычного режима идёт мимо
        // очереди, и наполнять её там нельзя — движок заговорил бы фразы, которые
        // читалка собирается синтезировать в файл.
        if (directMode) topUpDirectQueue()
        // 26.10.2026: движок начал фразу — держим свой тихий поток и подновляем его
        // следом за движком, иначе медиа-клавиша (волшебное касание скринридера,
        // кнопки гарнитуры) уходит движку, а не читалке (см. SilentKeepAlive, блок
        // «ПЕРВОЕ МЕСТО В ОЧЕРЕДИ МЕДИА-КЛАВИШ»).
        SilentKeepAlive.directPhraseStarted(appContext)
    }

    /** Сколько ждать прямую речь по длине фразы: сколько ей звучать при текущей
     *  скорости, запас и хвост из [Timing], в границах [DIRECT_MIN_MS]…
     *  [DIRECT_MAX_MS]. [Timing.charsPerSec] — наша оценка темпа на скорости
     *  1.0; её видно в журнале рядом со сроком, и если движок говорит заметно
     *  медленнее, число правится по факту, а не на глаз.
     *
     *  29.09.2026: у СЕТЕВОГО движка срок считается по ЗАМЕРЕННОМУ темпу речи
     *  (см. [charsPerSec]) — раньше мы считали по своей константе, у сетевого
     *  голоса она врала втрое, и сторож объявлял живую речь потерянной: очередь
     *  гасилась, фраза начиналась заново — это и были повторы, которые услышал
     *  Серж. Локального движка это не касается: у него темп известен и верен. */
    private fun directFuseMs(text: String?): Long {
        val chars = text?.length ?: 0
        val expected = chars / charsPerSec() * 1000f
        return (expected * timing.directFactor + timing.directTailMs).toLong()
            .coerceIn(DIRECT_MIN_MS, DIRECT_MAX_MS)
    }

    /** Сколько ждать, что движок НАЧНЁТ фразу (ещё до сигнала «начал говорить»).
     *
     *  Локальному движку хватает двух секунд: он говорит сразу из своего буфера.
     *  СЕТЕВОМУ нужно сначала сходить в сеть и синтезировать фразу — в журнале
     *  02:39 он не начинал за две секунды, и мы объявляли фразу пропущенной,
     *  хотя она просто готовилась. */
    private fun directStartMs(): Long = timing.directStartMs

    /** Сколько ждём движок на синтез [text] в файл: доля того времени, что фраза
     *  будет звучать, в границах из [Timing]. Почему у локального четверть: наш
     *  замер — 13-секундная фраза собралась за 0,95 с, то есть синтез идёт
     *  примерно в десять раз быстрее речи, и четверть даёт запас в два с
     *  половиной раза на медленный движок или занятый процессор. У сетевого доля
     *  другая: он готовит файл не долями секунды, а сетевым кругом (замер по
     *  журналу Сержа — 2,1 с на фразу в 58 знаков, 01:13:57), поэтому и нижняя
     *  граница втрое выше. Срок виден в журнале, и если движок окажется
     *  медленнее, число правится по факту, а не на глаз. */
    private fun synthFuseMs(text: String?): Long {
        val chars = text?.length ?: 0
        val speechMs = chars / charsPerSec() * 1000f
        return (speechMs * timing.synthFactor).toLong()
            .coerceIn(timing.synthMinMs, timing.synthMaxMs)
    }

    /** Сколько движок РЕАЛЬНО пишет фразу в файл (замер 05.10.2026, журнал 21:12).
     *
     *  TeraTTS на скорости 1,8 берёт около 20 мс на знак: 27 знаков — 0,53 с,
     *  137 — 1,45 с, 163 — 2,9 с (по разнице «начал речь» у соседних заявок:
     *  движок их сериализует). Прежний срок жданной фразы ([SYNTH_SILENT_MS],
     *  то есть 2,5 с) покрывал только ~135 знаков, а склейка доходит до 220:
     *  длинную фразу сторож отменял на середине письма, её файл стирался, заявка
     *  уходила в конец очереди движка — на ровном месте выходило 14,6 с тишины.
     *  Сетевому голосу этот расчёт не годится: у него [Timing.expectMsPerChar]
     *  равен нулю, там свои сроки. Если движок окажется медленнее, число
     *  правится по журналу. */
    private fun synthExpectMs(text: String?): Long =
        (text?.length ?: 0) * timing.expectMsPerChar

    /** Сколько движок будет писать эту фразу — по таблице сроков ([Timing]). Нужно
     *  читалке для быстрого старта: она решает, резать ли первую фразу по запятой
     *  (см. `ReaderEngine.cutFirstForStart`, 07.10.2026). Оценка грубая, но для
     *  порога «две с половиной секунды» её хватает. */
    fun estimateSynthMs(text: String): Long = synthExpectMs(text)

    // ---------- Синтез ----------

    /** Запустить синтез [text] в файл. По завершении судьба файла решается в
     *  [synthFinished]: текст ждёт [awaitingPlayText] — играем, иначе копим впрок.
     *
     *  [prefetch] — заявка заказана ВПРОК ([requestPrefetch], [prefetchRest],
     *  [prewarm]), а не по просьбе чтения. Признак уезжает в заявку, и по нему
     *  [synthFinished] решает, копить файл в [readyQueue] или считать синтез
     *  осиротевшим. Раньше эту роль играл отдельный набор «текстов в работе» —
     *  на одинаковых репликах он путал заявки. */
    private fun synthToFile(text: String, pos: Long = -1L, part: Int = 0, prefetch: Boolean = false) {
        if (tts == null || !ready) return
        // Реплика, режим включён и движок реплик уже поднялся — заказываем у него.
        // Не поднялся (или отказал) — читает основной: чтение не ждёт. Исключение
        // (27.09.2026): движок ЕЩЁ ПОДНИМАЕТСЯ — тогда не отдаём реплику чужому
        // голосу, а ждём его и повторяем заказ (см. [waitForReply]).
        // 29.09.2026: движок реплик отказал — пробуем поднять его заново, но не
        // таймером, а по делу: встретилась очередная реплика, значит он снова нужен.
        // И только если репликам вообще нужен СВОЙ экземпляр (движки разные).
        val ownInstance = replyNeedsOwnInstance()
        if (replyOn && ownInstance && replyBroken && Roles.looksReplica(text)) {
            maybeReviveReplyEngine()
        }
        val looksLikeReply = replyOn && Roles.looksReplica(text)
        val wantReply = looksLikeReply && (!ownInstance || !replyBroken)
        if (wantReply && ownInstance && waitForReply(text, pos, part)) return
        // Пока ждали, движок мог отказать (не поднялся за отведённый срок) —
        // тогда фразу читает основной голос и второй экземпляр не поднимаем.
        val replyRole = wantReply && (!ownInstance || !replyBroken)
        forgetReplyWait()
        // 29.09.2026: если реплики выбраны в ТОМ ЖЕ движке, что книга, — второго
        // экземпляра не заводим вовсе. Два экземпляра одного движка (так было и у
        // Сержа: книга и реплики в MultiTTS, отличаются только голоса) — известное
        // слабое место: движок теряет заявки, и роли пропадают. Ставим голос реплик
        // на основном экземпляре и СРАЗУ возвращаем книжный: движок запоминает
        // голос в момент заказа фразы, поэтому книжные фразы от этого не страдают
        // (см. [borrowMainForReply]).
        val sameEngine = replyRole && !ownInstance
        val t = (if (replyRole && ownInstance) replyInstance() else null) ?: tts ?: return
        val role = if (replyRole && (sameEngine || t === replyTts)) {
            Pending.Role.REPLY
        } else {
            Pending.Role.MAIN
        }
        val borrowed = role == Pending.Role.REPLY && sameEngine
        if (role == Pending.Role.REPLY) {
            if (borrowed) borrowMainForReply(t) else applyReplyParams(t)
        }
        val file = File(synthDir, "s_${reqSeq}.wav")
        val id = reqSeq++
        // Скорость запоминаем ту, которой файл заказан: у реплик она своя, и
        // сверять её надо со своей, иначе заготовки пересобирались бы по кругу.
        val rate = rateFor(role)
        // Тон запоминаем по имени файла: движок пишет файл уже с этой высотой
        // голоса, и по этому числу плеер доводит тон, если ползунок сдвинули
        // (см. [exoSyncSpeed]).
        rememberFilePitch(file.name, pitchFor(role))
        pending[id] = Pending(Pending.Kind.FILE, text, file, rate, role, pos, part).apply {
            this.prefetch = prefetch
        }
        if (role == Pending.Role.REPLY) {
            replyPhrases++
            replyFiles.add(file.name)
            if (replyFiles.size > 1000) replyFiles.clear()
        } else {
            mainPhrases++
        }
        armSynthWatch(text)
        val r = runCatching {
            t.synthesizeToFile(Roles.stripped(text), null, file, id.toString())
        }.getOrDefault(TextToSpeech.ERROR)
        // Голос реплик мы брали у основного экземпляра в долг — возвращаем сразу:
        // движок уже запомнил его для этой фразы, а следующая книжная должна
        // звучать книжным голосом.
        if (borrowed) restoreMainParams(t)
        if (r != TextToSpeech.SUCCESS) {
            pending.remove(id)?.let { it.file?.delete() }
            if (role == Pending.Role.REPLY) {
                // Второй движок отказался сразу — дальше реплики читает основной.
                replyBroken = true
                replyFalls++
                Diag.log(
                    appContext, "tts",
                    "движок реплик отказался сразу (код $r) — читаю реплики основным голосом"
                )
                synthToFile(text, pos, part)
                return
            }
            onSynthLost(text, pos)
        }
        // Замеры: раз в двадцать пять фраз пишем, чем читаем на самом деле.
        if ((mainPhrases + replyPhrases) % 25 == 0) {
            Diag.log(appContext, "tts", "реплики: ${replyCountersLine()}")
        }
    }
    /** Движок применил нашу скорость? (06.10.2026, после истории с настройкой
     *  MultiTTS «Приоритет конфигурации».)
     *
     *  Зачем: когда эта настройка включена, движок читает по СВОИМ параметрам и
     *  наш ползунок не делает ничего — Серж крутил скорость и не слышал разницы,
     *  а в журнале одна и та же фраза давала файл ОДНОГО И ТОГО ЖЕ размера на
     *  0,5, 1, 1,5, 2, 2,5 и 3,5. Признак надёжный: при 24 кГц 16 бит моно это
     *  48 000 байт на секунду звучания, значит файл той же фразы на вдвое
     *  большей скорости обязан быть примерно вдвое короче.
     *
     *  Здесь ТОЛЬКО запись в журнал (поведение чтения не меняем): сравниваем
     *  размер файла одной и той же фразы, сделанного на РАЗНЫХ скоростях. Если
     *  разница скоростей заметная (0,3 и больше), а размер совпал (в пределах
     *  трёх процентов) — это пара «движок нашу скорость не применил». Две такие
     *  пары подряд дают строку ИТОГ, по которой в журнале сразу видно причину.
     *  Пара, где размеры разошлись, счёт обнуляет — значит скорость работает.
     *
     *  Прямое чтение (файлов нет) пропускаем: там сравнивать нечего. */
    private fun noteRateIgnored(text: String, rate: Float, bytes: Long) {
        if (altDirect || netDirect) return
        if (bytes < 128) return // пустой звук — не о скорости
        val prev = fileBytesByText[text]
        if (fileBytesByText.size >= RATE_MEMO_MAX) {
            val eldest = fileBytesByText.keys.firstOrNull() ?: return
            fileBytesByText.remove(eldest)
        }
        fileBytesByText[text] = rate to bytes
        if (prev == null) return
        val (prevRate, prevBytes) = prev
        if (kotlin.math.abs(prevRate - rate) < 0.3f) return
        val big = kotlin.math.max(prevBytes, bytes).toDouble()
        val diff = kotlin.math.abs(prevBytes - bytes) / big
        if (diff > 0.03) {
            rateIgnoredPairs = 0
            return
        }
        rateIgnoredPairs++
        Diag.log(
            appContext, "sound",
            "одна и та же фраза на ${RateSteps.label(prevRate)} и " +
                "${RateSteps.label(rate)} дала файл одного размера ($bytes байт) — " +
                "движок нашу скорость не применяет (пар подряд: $rateIgnoredPairs)"
        )
        if (rateIgnoredPairs >= 2 && !rateIgnoredLogged) {
            rateIgnoredLogged = true
            Diag.log(
                appContext, "sound",
                "ИТОГ: похоже, движок игнорирует нашу скорость. Если это MultiTTS — " +
                    "проверить настройку «Приоритет конфигурации»: она должна быть " +
                    "ВЫКЛ («будут использоваться параметры вызывающего абонента»)"
            )
        }
    }

    /** Сколько фраза [text] обязана звучать по замеру темпа этой пары (мс). */
    private fun directExpectMs(text: String): Long =
        (text.length / charsPerSec() * 1000f).toLong().coerceAtLeast(400L)

    /** Разбор отчёта «готово» в прямом чтении.
     *
     *  Возвращаем: 0 — всё как обычно; больше нуля — столько миллисекунд НЕ
     *  начинать следующую фразу; меньше нуля — движок отчитался так быстро, что
     *  похоже, будто он молчал (см. [ackLooksSilent]).
     *
     *  Зачем вообще придерживать. В прямом чтении звук играет движок, а место в
     *  книге двигает его отчёт. Если движок отчитывается раньше, чем фраза
     *  физически может прозвучать, чтение убегает вперёд (жалоба тестера). Срок
     *  берём из замера темпа этой пары — того же, по которому считаем сроки
     *  сторожей. */
    private fun directAckHoldMs(id: Long, text: String): Long {
        val from = directAskedAt[id] ?: return 0L
        val elapsed = SystemClock.elapsedRealtime() - from
        val expect = directExpectMs(text)
        if (elapsed * 2 >= expect) return 0L // успел хотя бы половину — верим
        val rest = (expect - elapsed).coerceAtMost(ACK_HOLD_MAX_MS)
        // ФИЗИЧЕСКИЙ ПОЛ — ПЕРВЫМ ДЕЛОМ (10.10.2026). Никакой голос не произносит
        // знаки мгновенно: даже на самой быстрой скорости фраза в сотню знаков
        // звучит сотни миллисекунд. Если движок отчитался «готово» раньше этого
        // пола И ни разу не сказал «начал говорить» — он молчал, что бы он ни
        // сообщал про знаки.
        //
        // Зачем понадобилось. Прежнее правило отпускало фразу без разбора, если
        // движок присылал хоть какое-то сообщение «дошёл до знака»: тестерский
        // движок (dev.msvoice.tts, Realme RMX3472) отвечал «готово» за 27 мс на
        // ЛЮБУЮ фразу, сообщая при этом диапазон, — защита молчала, и книга
        // пролистывалась на 240 предложений за четыре секунды без единого звука
        // (журнал 10.10.2026, 09:26). Теперь такие отчёты считаются молчанием
        // ([ackLooksSilent]): после ACK_SILENT_STOP подряд чтение встаёт и
        // говорит об этом вслух.
        //
        // Почему условие про «начал говорить». Движки-прослойки играют звук САМИ
        // и отчитываются вперёд — они «начал говорить» присылают, и их трогать
        // нельзя (см. ветку ниже с придержкой). Молчащий движок этого сигнала не
        // шлёт вовсе: у тестера в журнале нет ни одной строки «onStart».
        if (directStartedAt[id] == null && elapsed < directImpossibleMs(text)) {
            if (ackFastLogged < ACK_FAST_LOG_MAX) {
                ackFastLogged++
                Diag.log(
                    appContext, "tts",
                    "движок отчитался «готово» за $elapsed мс, а фразу в ${text.length} знаков " +
                        "произнести нельзя быстрее ${directImpossibleMs(text)} мс, и о начале " +
                        "речи он не сообщал (знаки: ${directHeardTo[id] ?: 0}) — считаю фразу молчащей",
                )
            }
            return -1L // молчание: ждать нечего, придержка не нужна
        }
        if ((directHeardTo[id] ?: 0) > 0) return 0L // движок сообщал, до какого знака дошёл
        val meaningful = text.count { it.isLetterOrDigit() }
        if (meaningful < ACK_MIN_CHARS) return rest
        // «Начал говорить» движок не прислал вовсе — признаков речи нет никаких.
        // Это тот самый случай тестера: движок принимал фразу и мгновенно отвечал
        // «готово», а звука не было.
        if (directStartedAt[id] == null && elapsed * 3 < expect) {
            Diag.log(
                appContext, "tts",
                "движок отчитался «готово» за $elapsed мс, хотя фраза в ${text.length} знаков " +
                    "звучит около $expect мс, и о начале речи не сообщал — похоже, он молчал"
            )
            return -rest.coerceAtLeast(1L)
        }
        // Движок сказал «начал», но отчитался раньше, чем фраза могла прозвучать.
        // Такие движки-прослойки играют звук сами и отчитываются вперёд: чтение
        // только придерживаем (место не должно убегать от звука), но молчащими их
        // не считаем — звук-то идёт.
        if (ackEarlyLogged < 5) {
            ackEarlyLogged++
            Diag.log(
                appContext, "tts",
                "движок ответил раньше звука ($elapsed мс вместо ~$expect мс) — " +
                    "придерживаю чтение, чтобы место не убежало вперёд"
            )
        }
        return rest
    }

    /** Сколько миллисекунд фраза [text] обязана звучать при любой скорости —
     *  ниже этого срока отчёт «готово» означает не речь, а молчание
     *  (см. [directAckHoldMs]).
     *
     *  Число намеренно щедрое: [FASTEST_MS_PER_CHAR] = 4 мс на знак при скорости
     *  1.0 — это 250 знаков в секунду, чего не умеет никакой синтезатор. Занижать
     *  его опасно (настоящую быструю речь примем за молчание), завышать тоже:
     *  тогда мы просто не заметим залипший движок и вернёмся к той же прокрутке.
     *  При скорости 1.8 в журнале тестера фраза в 100 знаков «звучала» 27 мс при
     *  поле около 220 мс — разница в восемь раз. */
    private fun directImpossibleMs(text: String): Long {
        val speedNow = speed.coerceIn(0.5f, 10f)
        val scaled = text.length * FASTEST_MS_PER_CHAR / speedNow
        return scaled.toLong().coerceAtLeast(FASTEST_FLOOR_MS)
    }

    /** Подозрительный отчёт «готово»: движок «читает» слишком много фраз подряд
     *  без признаков звука. После [ACK_SILENT_STOP] таких встаём и говорим —
     *  как в [noteSilentPhrase], но по своему поводу. */
    private fun ackLooksSilent(pos: Long): Boolean {
        ackSilentInRow++
        if (ackSilentInRow < ACK_SILENT_STOP) return false
        Diag.log(
            appContext, "tts",
            "движок $ackSilentInRow фраз подряд отчитался «готово», не подав признаков речи — " +
                "останавливаю чтение и говорю об этом (место не сдвигаю)"
        )
        ackSilentInRow = 0
        val from = if (pos > 0L) pos else currentPos
        currentText = null
        awaitingPlayText = null
        awaitingPos = -1L
        directQueue.clear()
        directAskedAt.clear()
        directAskedId = null
        directSpeakingText = null
        directSpeakingPos = -1L
        directSpeakingPart = 0
        runCatching { tts?.stop() }
        runCatching { replyTts?.stop() }
        onEngineSilent?.invoke(from)
        return true
    }

    /** Завершился синтез (или прямое произнесение) с [id]. На главном потоке. */
    private fun synthFinished(id: Long) {
        // Фраза дошла до конца — значит движок звук даёт: счётчик отказов
        // синтеза обнуляем (16.10.2026, сборка 264x), а короткий поводок на
        // первую фразу снимаем — тишина кончилась (17.10.2026, 265x).
        errorInRow = 0
        coldPhrasePending = false
        // Движок дал звук — признак «не работает» снимаем (17.10.2026).
        TtsHealth.reset()
        directWatchToken++ // речь движка отозвалась — надзор за ней больше не нужен
        val p = pending.remove(id) ?: return
        // Заявка закрылась (файл пришёл или ошибка) — сторож по ней больше не
        // нужен: у сетевого движка таких заявок в работе несколько.
        forgetSynthWatch(p.text)
        if (p.cancelled) {
            p.file?.delete()
            return
        }
        when (p.kind) {
            Pending.Kind.DIRECT -> {
                // Фраза доиграла — «звучит сейчас» больше никого нет (29.09.2026).
                directSpeakingText = null
                directSpeakingPos = -1L
                directSpeakingPart = 0
                if (directAskedId == id) directAskedId = null
                // Звучащая фраза прямой речи (или разовая страховка) закончилась.
                retriesInRow = 0 // движок жив — счётчик перезапусков обнуляем
                rescueText = null // фраза дошла до конца — спасать больше нечего
                rescueTries = 0
                // 08.10.2026: движок отчитался «готово» — а сказал ли он что-нибудь?
                // Разбор отчёта — до сообщения чтению: место в книге не должно
                // уезжать вперёд звука (жалоба тестера: движок отвечал мгновенно,
                // и чтение за полторы секунды прошло семьдесят предложений).
                //
                // ПОРЯДОК ВАЖЕН (10.10.2026): разбор идёт ДО [noteSpokenRate], потому
                // что тот ВЫЧИЩАЕТ засечки этой фразы (`directStartedAt`,
                // `directHeardTo`) и после него разбор уже не отличит движок,
                // который сказал «начал говорить», от того, который молчал. На
                // этом чуть не построили вывод «в сборке нет защиты»: по журналу
                // тестера нельзя было понять, какие сигналы движок слал.
                val hold = directAckHoldMs(id, p.text)
                // Замер настоящего темпа речи: длина фразы на время звучания.
                noteSpokenRate(id, p.text.length)
                directAskedAt.remove(id)
                if (directQueue.firstOrNull() == id) directQueue.removeFirst()
                else directQueue.remove(id)
                // Движок сейчас возьмёт следующую фразу очереди: переводим надзор
                // на её длину. Сигнал «начал говорить» придёт и сам, но срок,
                // отсчитанный отсюда, спасает движки, которые его не шлют.
                directQueue.firstOrNull()?.let { armDirectWatch(it, started = true) }
                // 08.10.2026: и в этом способе сообщаем, какая ЕДИНИЦА речи
                // доиграла (место и кусок) — иначе чтение не отличит свой конец
                // от чужого (см. [reportDone]).
                if (hold < 0L) {
                    // Отчёт похож на «сказал», хотя звука не было.
                    val pos = if (p.pos >= 0L) p.pos else currentPos
                    if (ackLooksSilent(pos)) return
                }
                // 23.10.2026: единица ПРОЗВУЧАЛА — запоминаем её ключ. Прямой путь
                // теперь работает с теми же ключами, что файловый, поэтому и здесь
                // действует правило «вперёд единица звучит один раз» (см. [speakDirectQueued]).
                noteUnitPlayed(p.pos, p.part)
                if (hold != 0L) {
                    // Не даём чтению убежать вперёд: ждём, пока фраза могла бы
                    // прозвучать, и только потом двигаем место.
                    val wait = if (hold < 0L) -hold else hold
                    // Про молчание (hold = -1) уже сказано строкой выше: ждать
                    // нечего, и «придерживаю на 1 мс» было бы только шумом.
                    if (wait > ACK_HOLD_LOG_MIN_MS) {
                        Diag.log(
                            appContext, "tts",
                            "движок ответил раньше звука — придерживаю чтение на $wait мс, " +
                                "чтобы место не убежало вперёд"
                        )
                    }
                    main.postDelayed(
                        { reportDone(p.pos, p.part, lastOfPhrase(p.pos, p.part)) },
                        wait,
                    )
                } else {
                    ackSilentInRow = 0
                    reportDone(p.pos, p.part, lastOfPhrase(p.pos, p.part))
                }
            }
            Pending.Kind.FILE -> {
                val f = p.file
                if (f == null || !f.exists() || f.length() == 0L) {
                    // 05.10.2026 (журнал 22:43): движок отчитался «готово», а файла
                    // нет вовсе. Раньше эта ветка молчала и просто шла дальше —
                    // по такому пути и убежало чтение. Теперь это видно в журнале.
                    Diag.log(
                        appContext, "tts",
                        "движок отчитался «готово», а файла нет (${f?.length() ?: -1} байт): " +
                            "«${p.text.take(40)}»"
                    )
                    f?.delete()
                    onSynthLost(p.text, p.pos)
                    return
                }
                forgetSynthMisses(p.text) // синтез доспел — движок отзывается, обрывов нет
                // И обрывов подряд больше нет: движок умеет отвечать, копить
                // поводы пометить его медленным незачем (см. [slowHits]).
                slowHits = 0
                netFileFails = 0 // файлы приходят — прямой режим не нужен
                // 05.10.2026: файл пришёл — новый голос поднялся, окно прогрева
                // больше не нужно. Заодно пишем в журнал, сколько он на это взял:
                // по этой цифре и правится срок [Timing.warmupMs].
                if (voiceWarmUntilMs != 0L && (awaitingPlayText == null || p.text == awaitingPlayText)) {
                    val ms = SystemClock.elapsedRealtime() - voiceWarmFromMs
                    voiceWarmUntilMs = 0L
                    Diag.log(
                        appContext, "tts",
                        "окно терпения закрыто: фраза доспела за $ms мс"
                    )
                    // 07.10.2026: сколько движок готовил первую фразу — в пометку
                    // по паре «движок + голос» (см. [noteFirstPrep]).
                    noteFirstPrep(ms)
                    // Голос ответил сразу после СМЕНЫ — пометка «медленный», если
                    // её поставили наши же промахи при смене, больше не годится
                    // (см. [forgetSlowMark]). Холодный старт пометку не трогает.
                    if (p.role == Pending.Role.MAIN && voiceWarmBySwitch) {
                        forgetSlowMark("новый голос ответил сразу после смены")
                    }
                }
                // Движок реплик отозвался — прошлые промахи больше не считаем
                // (29.09.2026: иначе редкие промахи складывались бы в отказ от ролей).
                if (p.role == Pending.Role.REPLY) {
                    replyMisses = 0
                }
                rescueText = null // файл пришёл — спасать фразу больше не нужно
                rescueTries = 0
                // msg4416: движок иногда отдаёт файл из одного заголовка (44 байта,
                // ни одного отсчёта) — фраза звучит молча. Пишем в журнал её текст:
                // надо понять, теряется ли настоящий текст или это пустые обрывки
                // разбора (в логе Сергея такие файлы идут парами подряд).
                //
                // 06.10.2026 (MultiTTSLexx, журнал 18:00): у движка-прослойки
                // пустой файл — не случайность, а правило: звук он играет САМ, а в
                // наш файл не пишет ничего. Прежде мы считали такой ответ удачей,
                // пометка «файлов не отдаёт» не ставилась, и чтение ходило за
                // файлами, которых нет, пока сторож не начинал перезапускать
                // движок по кругу. Теперь два пустых файла подряд у одной пары —
                // такой же провал файлового пути, как неотвеченная заявка:
                // помечаем пару и дальше читаем её голосом ([markNetDirect]).
                // Двух, а не одного: у локального движка пустой файл случается и
                // сам по себе (в журналах TeraTTS такие шли парами), и менять ему
                // путь из-за одной случайности нельзя. Пустые обрывки разбора
                // («…», «***») в счёт не идут — см. [looksLikeSpeech].
                if (f.length() < 128) {
                    if (emptySoundLogged < 6) {
                        emptySoundLogged++
                        Diag.log(
                            appContext, "sound",
                            "движок отдал пустой звук (${f.length()} байт) [${whoLabel(p.role)}]: " +
                                "«${p.text.take(60)}»"
                        )
                    }
                    if (p.role == Pending.Role.MAIN && looksLikeSpeech(p.text)) {
                        val awaited = isAwaited(p)
                        emptySoundFails++
                        // Принудительный способ (см. [forceMode]) — проб и переходов
                        // не делаем вовсе: сразу считаем фразу молчащей. Ждать
                        // второго пустого файла тут незачем, а обманывать тишиной
                        // нельзя — счётчик [noteSilentPhrase] остановит чтение и
                        // скажет об этом вслух.
                        val give = forceMode != ExpertPrefs.MODE_AUTO ||
                            emptySoundFails >= EMPTY_SOUND_HITS
                        if (give) {
                            f.delete()
                            if (forceMode != ExpertPrefs.MODE_AUTO) {
                                Diag.log(
                                    appContext, "sound",
                                    "принудительный способ (${ExpertPrefs.forceModeLabel(forceMode)}): " +
                                        "пустой файл, фразу «${p.text.take(40)}» считаю молчащей"
                                )
                                silentFileAttempt(p.text, p.pos)
                                return
                            }
                            emptySoundFails = 0
                            markNetDirect("$EMPTY_SOUND_HITS пустых файла подряд")
                            // Играть нечего — файл выброшен. Фразу, которую ждёт
                            // чтение, произносим голосом движка: он теперь наш
                            // прямой путь, и место чтения от этого не сдвинется.
                            if (awaited) {
                                speakDirectNow(
                                    p.text, p.pos, p.part,
                                    "файл от движка пустой ($EMPTY_SOUND_HITS раза подряд) — " +
                                        "читаю фразу его голосом, дальше без файлов",
                                )
                            }
                            return
                        }
                        // ПЕРВЫЙ пустой файл на настоящей фразе. Играть его нельзя:
                        // это тишина, а чтение идёт по «фраза доиграла» — оно
                        // сдвинется дальше, и предложение потеряется молча.
                        // 06.10.2026, журнал 20:49:18: «синтез готов: s_86.wav
                        // (44 байт)», заготовка ушла в плеер, прозвучала молча, и
                        // Серж не услышал «Попросили провести беседы с активом и
                        // колхозниками». Жданную фразу заказываем ЗАНОВО: не вышло
                        // и во второй раз — счётчик дойдёт до приговора выше, и
                        // фраза зазвучит голосом движка. Заготовку просто
                        // выбрасываем: её закажут снова, когда до неё дойдёт чтение.
                        f.delete()
                        Diag.log(
                            appContext, "sound",
                            "пустой файл не играю — фраза «${p.text.take(40)}» " +
                                if (awaited) "заказана заново" else "выброшена"
                        )
                        if (awaited) synthToFile(p.text, p.pos, p.part)
                        return
                    }
                } else {
                    // Файл со звуком — провалов подряд больше нет.
                    emptySoundFails = 0
                }
                // msg5979: заказанная скорость и «сырой» размер файла. По ним
                // видно, насколько движок ускорился НА САМОМ ДЕЛЕ: при 24 кГц,
                // 16 бит моно это 48 000 байт в секунду звучания, значит одна и
                // та же фраза на 2.0 обязана быть вдвое короче, чем на 1.0.
                // Пишем ДО trimSilence: обрезка краёв отнимает постоянный кусок
                // и сравнение смазала бы.
                // 26.09.2026: помечаем, чей файл — книга или реплика и какой
                // движок: без этого жалобу «у реплик слышны паузы» не разобрать.
                trimWho = whoLabel(p.role)
                Diag.log(
                    appContext, "sound",
                    "синтез готов: ${f.name} (${f.length()} байт), скорость " +
                        "${RateSteps.label(p.rate)} [$trimWho]"
                )
                noteRateIgnored(p.text, p.rate, f.length())
                trimSilence(f, p.role)
                if (isAwaited(p) && p.rate != rateFor(p.role)) {
                    // Скорость сменили, пока фраза синтезировалась: файл сделан
                    // прежним темпом. Не играем его — заказываем заново текущим
                    // (задержка тут только у той фразы, что была в работе).
                    //
                    // 29.09.2026 (журнал 19:03, «была остановка, я крутил
                    // скорость»): здесь СНИМАЛИ awaitingPlayText — и это оказалось
                    // страшнее задержки. Пока ползунок едет, [dropStaleRate] чистит
                    // список заявок, и следующие доспевшие файлы перестают узнаваться:
                    // «осиротевший синтез» молча удалялся, играть было нечего, и
                    // чтение замолкало НАВСЕГДА (в журнале после 19:03:54 нет ни
                    // «играю фразу», ни «фраза доиграла», хотя файлы приходили).
                    // Фразу оставляем жданной: тогда переспрос доедет до [playFile].
                    f.delete()
                    Diag.log(
                        appContext, "sound",
                        "скорость сменилась, пока фраза синтезировалась — собираю заново"
                    )
                    synthToFile(p.text, p.pos, p.part)
                } else if (isAwaited(p)) {
                    // Это та единица речи, которую уже попросили говорить.
                    awaitingPlayText = null
                    awaitingPos = -1L
                    awaitingPart = -1
                    // 23.10.2026: играем ровно ту единицу, за которую пришёл файл
                    // ([Pending.key]), а не «текущую фразу чтения». Иначе при
                    // задержке синтеза файл одной фразы вставал в список под ключом
                    // другой, и проверка порядка ([expectedNextKey]) считала от
                    // чужого места.
                    playFile(p)
                    // 05.10.2026, журнал Сержа 17:12-17:14: «после первой фразы
                    // после переключения — большая пауза, дальше терпимо». Так и
                    // было: после смены голоса эта фраза приходит ФАЙЛОМ в ответ
                    // на просьбу чтения (а не из очереди), играть её начинает
                    // [synthFinished], и конвейер вперёд никто не заводил — он
                    // просыпался только на «фраза доиграла». Всю первую фразу
                    // движок стоял без работы, а следующую собирал уже с нуля: в
                    // журнале 17:12:54 играет s_17, «заказал заготовок: 3» —
                    // только в 17:13:02, после её конца, и стык вышел в 1,2 с
                    // (17:14:18 — 2,7 с). Теперь заказываем впрок сразу, как
                    // только фраза зазвучала, — как это и делает ветка заготовки
                    // ниже.
                    requestPrefetch()
                    exoTopUp()
                } else if (p.prefetch) {
                    // Упреждающий синтез завершился, пока его ещё не просили.
                    // 23.10.2026: признак «заказана впрок» стоит в самой заявке
                    // ([Pending.prefetch]) — по тексту его больше не выясняем.
                    // msg4077: засечка в лог — без неё по логу не видно, доспела
                    // заготовка или синтез молча повис.
                    // 07.10.2026: предел очереди теперь по потолку запаса в фразах
                    // ([aheadPhraseCap]) — запас вперёд считается ещё и знаками, и
                    // с прежним жёстким пределом доспевшие файлы выбрасывались бы,
                    // а потом заказывались заново.
                    if (readyQueue.size >= aheadPhraseCap() + maxInFlight) {
                        // Очередь переполнена (прыжок назад или смена позиции) —
                        // лишнее не копим. Запас на [maxInFlight] нужен с 30.09.2026:
                        // фраза, заказанная позже ещё не готовой, теперь ЖДЁТ в
                        // очереди своей очереди (см. [exoTopUp]), и жёсткий предел
                        // выбрасывал бы нужные файлы.
                        f.delete()
                    } else {
                        addReadyInOrder(Prepared(p.text, f, p.rate, p.role, req = id, pos = p.pos, part = p.part))
                        Diag.log(
                            appContext, "sound",
                            "заготовка готова: ${f.name} (${f.length()} байт), в очереди ${readyQueue.size}/$prefetchDepth"
                        )
                        // msg4472: заготовка доспела — сразу просим следующую,
                        // пока играет текущая. Так очередь наполняется сама.
                        // Кроме упреждающей подготовки ([prewarm]): там нужна
                        // ровно одна фраза — та, с которой начнётся чтение.
                        if (prewarmOnly) prewarmOnly = false else requestPrefetch()
                        // msg4598: сразу отдаём её в список плеера, если звук уже
                        // идёт. Без этого стык бесшовным становился бы только у
                        // тех фраз, чья следующая была готова к моменту старта.
                        exoTopUp()
                    }
                } else {
                    // Осиротевший синтез (устаревшая заготовка) — просто удаляем.
                    //
                    // 29.09.2026 (журнал 19:03): но если при этом НИЧЕГО не звучит, а
                    // файл сделан на нынешней скорости — играем его. Иначе получается
                    // вечная тишина: заявку сняла чистка на смене скорости, файл
                    // пришёл и молча удалился, а новых заявок никто не делает.
                    // Лучше сыграть фразу не по чину, чем замолчать насовсем.
                    //
                    // 21.10.2026: но играем ТОЛЬКО когда чтение правда кого-то ждёт.
                    // Раньше условие было «ничего не играет», а это верно и после
                    // паузы: файл, заказанный до остановки, доспевал уже в тишине и
                    // звучал — книга начинала читаться сама, хотя человек её только
                    // открыл и авточтение выключено (журнал Сержа 21.10). Ждать
                    // некому (currentText и awaitingPlayText пусты) — файл не нужен.
                    val waiting = currentText != null || awaitingPlayText != null
                    if (!soundPlaying() && waiting && p.rate == rateFor(p.role)) {
                        Diag.log(
                            appContext, "sound",
                            "файл пришёл без заявки (${f.name}), звука нет — играю его"
                        )
                        playFile(p)
                    } else {
                        if (!waiting && !soundPlaying()) {
                            Diag.log(
                                appContext, "sound",
                                "файл пришёл без заявки (${f.name}), но чтение никого не ждёт — " +
                                    "не играю (заготовка сделана после остановки)"
                            )
                        }
                        f.delete()
                    }
                }
            }
        }
    }

    /** Синтез с [id] сорвался — разбираемся, был ли это запрошенный текст. */
    private fun synthFailed(id: Long, errorCode: Int) {
        directWatchToken++
        val p = pending.remove(id) ?: return
        p.file?.delete()
        if (p.cancelled) return
        if (p.role == Pending.Role.REPLY) {
            // Второй движок не справился с фразой. Перезапускать его на каждой
            // реплике — значит гадать; честнее вернуться к основному голосу и
            // сказать об этом в журнале.
            replyBroken = true
            replyFalls++
            Diag.log(
                appContext, "tts",
                "движок реплик вернул ошибку (код $errorCode) — читаю реплики основным голосом"
            )
            dropReplyEngine()
            synthToFile(p.text, p.pos, p.part)
            return
        }
        if (p.kind == Pending.Kind.DIRECT) {
            // Движок отказался от фразы прямой речи. Раньше такие ошибки молчали
            // вовсе: в этом режиме надзирало только молчание, а ошибка — не
            // молчание, и о ней никто не узнавал.
            val head = directQueue.firstOrNull() == id
            directQueue.remove(id)
            Diag.log(
                appContext, "tts",
                "прямая речь: движок отказался от фразы (код $errorCode)"
            )
            // ОТКАЗ — ЭТО НЕ «ФРАЗА СЫГРАЛА» (16.10.2026, сборка 264x). Прежде
            // отказ по звучащей фразе засчитывался как проигранный, и чтение шло
            // дальше в полной тишине: у Сержа движок не работал в системе вовсе
            // («другая читалка им тоже не читает»), а наша читалка об этом
            // молчала. С 17.10.2026 (265x) ОДНОГО отказа по звучащей фразе
            // довольно, чтобы встать и сказать словами. Отказы заготовок впрок не
            // считаем — они не про звук.
            //
            // «ЗВУЧАЩАЯ» — НЕ ТОЛЬКО ГОЛОВА ОЧЕРЕДИ (266x, журнал 23:54): спасение
            // через прямой путь (`speakDirectNow`) кладёт заявку МИМО очереди, и
            // проверка «голова ли это» такой отказ пропускала — читалка молчала, а
            // Серж ждал слов. Теперь отказ считается, если фраза сейчас звучит или
            // её ждёт чтение. 23.10.2026: сверка по КЛЮЧУ единицы (место + кусок).
            val sounding = head ||
                (p.key >= 0 && p.key == directSpeakingKey) ||
                (p.key >= 0 && p.key == awaitingKey())
            if (sounding && noteSynthError()) return
            if (!head) return
            flushDirectQueue("движок вернул ошибку")
            retriesInRow = 0
            reportDone(p.pos, p.part, lastOfPhrase(p.pos, p.part))
            return
        }
        Diag.log(appContext, "tts", "синтез в файл не удался (код $errorCode)")
        // Считаем только отказ по фразе, которую ждёт чтение: упавшая заготовка
        // впрок — не повод объявлять движок нерабочим.
        if (p.text == awaitingPlayText && noteSynthError()) return
        onSynthLost(p.text, p.pos)
    }

    /** Голоса движка с языками — в журнал (16.10.2026, сборка 264x). По этой
     *  строке видно, есть ли на телефоне голос нужного языка: Серж спросил
     *  «можно ли выбрать синтезатор для белорусского», а сперва надо понять, есть
     *  ли на устройстве такой голос вообще. Печатаем не больше восьми языков. */
    private fun logVoiceLanguages() {
        // 24.10.2026: берём ГОТОВЫЙ список (см. [voiceCache]) — сам запрос к
        // движку отсюда убран: он вешал главный поток.
        val vs = voiceCache
        if (vs.isEmpty()) {
            Diag.log(appContext, "tts", "голосов у движка нет вовсе")
            return
        }
        val byLang = vs.groupBy { it.locale.language }
        val top = byLang.entries.sortedByDescending { it.value.size }.take(8)
            .joinToString("; ") { e -> "${e.key}=${e.value.size}" }
        val cur = selectedVoiceName?.let { name -> vs.firstOrNull { it.name == name } }
            ?.locale?.toLanguageTag()
        Diag.log(
            appContext, "tts",
            "голоса движка: всего ${vs.size} ($top); выбранный ${cur ?: "не назван"}",
        )
    }

    /** Считает отказы синтеза подряд и, когда их стало [TTS_DEAD_ERRORS],
     *  объявляет движок нерабочим: встаём, возвращаем место и говорим человеку
     *  словами, что синтезатор не даёт звука. Возврат true — дальше вести чтение
     *  нельзя, вызывающий обязан выйти.
     *
     *  Почему два, а не пять, как у молчания: молчание может быть медленной
     *  подготовкой фразы, а ОТКАЗ — это уже ответ движка. Два ответа подряд
     *  «не могу» означают, что и дальше не сможет. */
    private fun noteSynthError(): Boolean {
        errorInRow++
        Diag.log(appContext, "tts", "отказов синтеза подряд: $errorInRow")
        if (errorInRow < TTS_DEAD_ERRORS) return false
        TtsHealth.engineUnusable = true
        Diag.log(
            appContext, "tts",
            "движок не даёт звука ($errorInRow отказа подряд) — останавливаю чтение и " +
                "говорю об этом (место чтения не сдвигаю)",
        )
        onEngineSilent?.invoke(currentPos)
        return true
    }

    /** Движок не дал по фразе ни звука. true — дальше вести чтение нельзя:
     *  движок молчит подряд слишком много фраз (см. [onEngineSilent]), и
     *  вызывающий НЕ должен сообщать «фраза доиграла».
     *
     *  Лестница: 1 пропущенная фраза — как было; timing.silentRestartAt подряд —
     *  поднимаем движок заново и ждём перечитанную фразу (её закажет
     *  [retryAfterRestart]); timing.silentStopAt подряд — встаём и говорим. */
    private fun noteSilentPhrase(pos: Long): Boolean {
        if (silentInRow == 0 && pos > 0L) silentFromPos = pos
        silentInRow++
        // ПЕРВАЯ ФРАЗА ПОСЛЕ СТАРТА — КОРОТКИЙ ПОВОДОК (17.10.2026, просьба Сержа:
        // «не говори, что синтезатор не готов, долго жду»). Пока не прозвучала ни
        // одна фраза, человек сидит в полной тишине и не знает, идёт ли чтение;
        // поэтому здесь встаём и говорим уже на ВТОРОЙ неудаче, а не на
        // четвёртой. Перезапуск движка при этом не отменяется — он часто и есть
        // лекарство, — просто на первую фразу их не два, а один.
        val stopAt = if (coldPhrasePending) minOf(2, timing.silentStopAt) else timing.silentStopAt
        if (silentInRow == timing.silentRestartAt && silentInRow < stopAt) {
            Diag.log(
                appContext, "tts",
                "движок не дал звука $silentInRow фразы подряд — поднимаю его заново"
            )
            retryAfterRestart = currentText
            retryAfterRestartPos = currentPos
            retryAfterRestartPart = currentPart
            start(enginePackage, rememberAwaiting = false)
            return true
        }
        // 24.10.2026: «повторов запроса к сетевому голосу» (1…10, как у @Voice).
        // Первый перезапуск выше — как было; сверх него у сетевого голоса есть
        // ещё (netRetries − 1) попыток перечитать ту же фразу, прежде чем решим,
        // что он не отвечает. Только у сетевого: локальный отвечает за доли
        // секунды, и повторять его молчание бессмысленно (Серж 17.10.2026:
        // «если локальный синтезатор, то не делаем такую большую паузу»).
        val extraRetries = if (netSynth) (netRetries - 1).coerceAtLeast(0) else 0
        if (silentInRow >= stopAt && silentRetries < extraRetries) {
            silentRetries++
            Diag.log(
                appContext, "tts",
                "сетевой голос молчит: повтор запроса $silentRetries из $extraRetries"
            )
            retryAfterRestart = currentText
            retryAfterRestartPos = currentPos
            retryAfterRestartPart = currentPart
            start(enginePackage, rememberAwaiting = false)
            return true
        }
        if (silentInRow >= stopAt) {
            Diag.log(
                appContext, "tts",
                "движок молчит $silentInRow фраз подряд — останавливаю чтение и " +
                    "говорю об этом (место чтения не сдвигаю)"
            )
            val from = silentFromPos
            silentInRow = 0
            silentFromPos = -1L
            coldPhrasePending = false
            currentText = null
            awaitingPlayText = null
            awaitingPos = -1L
            readyQueue.clear()
            runCatching { tts?.stop() }
            runCatching { replyTts?.stop() }
            onEngineSilent?.invoke(from)
            return true
        }
        return false
    }

    /** Синтеза в файл не вышло. Если текст кто-то ждёт (speak()) — пытаемся
     *  проговорить напрямую движком: тишина хуже, чем разовое возвращение к
     *  движковому звуку (на время этой фразы media-кнопки будут не наши — это
     *  редкая страховка). Упавшую заготовку просто отбрасываем.
     *
     *  При принудительном обычном способе ([ExpertPrefs.MODE_FILE]) страховки
     *  нет: иначе проба «только файлом» показывала бы не то, что выбрано. Фразу
     *  считаем молчащей — после нескольких таких чтение встанет и скажет вслух. */
    private fun onSynthLost(text: String, pos: Long = -1L) {
        if (forceMode == ExpertPrefs.MODE_FILE) {
            Diag.log(
                appContext, "tts",
                "принудительно обычный способ: синтез не вышел — голосом движка фразу не читаю"
            )
            silentFileAttempt(text, pos)
            return
        }
        // ПЕРВАЯ ФРАЗА — БЕЗ СПАСЕНИЯ (17.10.2026, 266x, жалоба Сержа «всё равно
        // не сообщает, что синтезатор не готов, надо делать маленькую паузу»).
        // Пока не прозвучало ни одной фразы, человек слышит только тишину: ждать
        // вторую попытку через прямой путь (в журнале 23:54 это ещё 12 секунд)
        // незачем — говорим сразу, что синтезатор не готов. Повторить можно
        // кнопкой «Попробовать снова» в окне, которое при этом показывается.
        if (coldPhrasePending && noteSynthError()) return
        speakDirectNow(
            text, pos, currentPart,
            "страховка: движок говорит напрямую (media-кнопки на это время не наши)",
        )
    }

    /** Файловый путь не дал звука, а читать голосом движка запрещено (см.
     *  [forceMode]): считаем фразу молчащей и идём дальше.
     *
     *  Счётчик [noteSilentPhrase] — единственный путь для «фраза потерялась»:
     *  после timing.silentRestartAt подряд движок поднимают заново, после
     *  timing.silentStopAt чтение встаёт и говорит об этом вслух. Заготовку не
     *  считаем и чтение по ней не двигаем: её закажут снова, когда дойдут. */
    private fun silentFileAttempt(text: String, pos: Long) {
        if (text != awaitingPlayText) return
        if (!noteSilentPhrase(pos)) reportDone()
    }

    /** Сказать фразу голосом движка ПРЯМО СЕЙЧАС, минуя очередь (очистить её и
     *  произнести). Нужно там, где файловый путь только что сорвался, а фразу
     *  чтение уже ждёт: молчание хуже разового возврата к движковому звуку.
     *  [logLine] — что написать в журнал: у «страховки» и у перехода на прямой
     *  путь из-за пустого файла причины разные, и по журналу их надо различать. */
    private fun speakDirectNow(text: String, pos: Long, part: Int = 0, logLine: String) {
        val wanted = text == awaitingPlayText
        awaitingPlayText = null
        val t = tts
        if (t == null || !ready || !wanted) return
        Diag.log(appContext, "tts", logLine)
        val id = reqSeq++
        pending[id] = Pending(Pending.Kind.DIRECT, text, null, pos = pos, part = part)
        directAskedAt[id] = SystemClock.elapsedRealtime()
        val r = runCatching { t.speak(Roles.stripped(text), TextToSpeech.QUEUE_FLUSH, null, id.toString()) }
            .getOrDefault(TextToSpeech.ERROR)
        if (r != TextToSpeech.SUCCESS) {
            pending.remove(id)
            // Совсем ничего не вышло. Сетевому движку даём ещё попытку: терять
            // фразу хуже, чем подождать (29.09.2026, просьба Сержа).
            if (netSynth && rescueAgain(text, pos, part)) return
            if (!noteSilentPhrase(pos)) reportDone(pos, part, lastOfPhrase(pos, part))
        } else {
            armDirectWatch(id)
        }
    }

    /** Есть ли в тексте что произносить. Пустой файл от движка считаем признаком
     *  провала файлового пути только на настоящей фразе: пустые обрывки разбора
     *  («…», «***», «—») молчат законно, и менять из-за них путь нельзя
     *  (см. [synthFinished]). */
    private fun looksLikeSpeech(text: String): Boolean {
        var meaningful = 0
        for (ch in text) if (ch.isLetterOrDigit()) meaningful++
        return meaningful >= 4
    }

    /** Фраза пропадала — попробовать спасти её ещё раз (29.09.2026).
     *
     *  Жалоба Сержа: «в прошлый раз было лучше, когда паузы небольшие, но оно
     *  сразу начинало читать». Раньше при сорванном синтезе фраза пропускалась
     *  молча — в журнале 01:51 так потерялась фраза в 189 знаков, и в чтении
     *  вышло 18 секунд тишины. Теперь для СЕТЕВОГО движка пробуем дважды:
     *  сначала синтез в файл ещё раз (движок мог просто залипнуть на минуту),
     *  потом прямую речь ещё раз. Локальные движки не трогаем — у них своя
     *  лестница мер и своё поведение. */
    private fun rescueAgain(text: String, pos: Long = -1L, part: Int = 0): Boolean {
        val tries = if (rescueText == text) rescueTries + 1 else 1
        if (tries > RESCUE_TRIES) return false
        rescueText = text
        rescueTries = tries
        // В прямом чтении файлов не заказываем вовсе: этот путь для этого движка
        // уже признан негодным (см. [netDirect]). Иначе выходила ерунда из
        // журнала 02:30 — приложение перешло на прямое чтение и тут же снова
        // попросило файл, который заведомо не придёт.
        if (directMode) {
            Diag.log(
                appContext, "tts",
                "фразу потеряли — пробую ещё раз (попытка $tries из $RESCUE_TRIES): прямая речь"
            )
            speakDirectAgain(text, pos, part)
            return true
        }
        Diag.log(
            appContext, "tts",
            "фразу потеряли — пробую ещё раз (попытка $tries из $RESCUE_TRIES): " +
                if (tries == 1) "синтез в файл" else "прямая речь"
        )
        if (tries == 1) {
            currentText = text
            currentPos = pos
            currentPart = part
            awaitingPlayText = text
            awaitingPos = pos
            awaitingPart = part
            synthToFile(text, pos, part)
        } else {
            speakDirectAgain(text, pos, part)
        }
        return true
    }

    /** Ещё раз прямая речь той же фразы (спасение, см. [rescueAgain]).
     *  23.10.2026: с местом и куском — иначе спасённая фраза возвращалась в
     *  очередь без ключа, и «доиграла» по ней место не двигала. */
    private fun speakDirectAgain(text: String, pos: Long = -1L, part: Int = 0) {
        val t = tts ?: return
        // Прежняя очередь движку больше не нужна: фраза не зазвучала, а её место
        // займёт эта. Заодно tts.stop() выметает у движка то, что он ещё держит.
        flushDirectQueue("спасаю фразу заново")
        val id = reqSeq++
        pending[id] = Pending(Pending.Kind.DIRECT, text, null, pos = pos, part = part)
        directAskedAt[id] = SystemClock.elapsedRealtime()
        val r = runCatching { t.speak(Roles.stripped(text), TextToSpeech.QUEUE_FLUSH, null, id.toString()) }
            .getOrDefault(TextToSpeech.ERROR)
        if (r != TextToSpeech.SUCCESS) {
            pending.remove(id)
            reportDone(pos, part, lastOfPhrase(pos, part))
        } else {
            armDirectWatch(id)
        }
    }

    // ---------- Проигрывание ----------

    /** Младшие байты WAV: 16-битное число с прямым порядком (little endian). */
    private fun leShort(b: ByteArray, i: Int): Int =
        (b[i].toInt() and 0xFF) or ((b[i + 1].toInt() and 0xFF) shl 8)

    /** 32-битное число WAV (little endian). */
    private fun leInt(b: ByteArray, i: Int): Int =
        leShort(b, i) or (leShort(b, i + 2) shl 16)

    /** Коды причин, по которым обрезка файл не тронула. Пишем в журнал по
     *  одному разу на код за сессию: если галочка «ничего не меняет», по этой
     *  строке видно, ЧТО именно ей помешало (msg4409 — Сергей: «на мой слух
     *  эта галочка ничего не меняет», а причина молчала).
     *  1 — это не WAV; 2 — формат не PCM; 3 — не тот звук (каналы/биты/частота);
     *  4 — нет блока data; 5 — файл подозрительного размера; 7 — сплошная
     *  тишина; 8 — после обрезки осталась бы десятая часть; 9 — тишины по краям
     *  нет вовсе (значит пауза не в тишине, а в интонации синтезатора). */
    private val trimBailLogged = HashSet<String>()

    /** Чей файл обрезаем — для строк журнала (26.09.2026). Без этого в логе не
     *  видно, отказала обрезка у основного движка или у репликового, а жалоба
     *  была именно про паузы у реплик. */
    private var trimWho: String = ""

    /** Кто сделал файл: роль и движок — одной короткой пометкой для журнала. */
    private fun whoLabel(role: Pending.Role): String =
        if (role == Pending.Role.REPLY) "реплика, ${replyEnginePackage ?: "системный"}"
        else "книга, ${enginePackage ?: "системный"}"

    /** Целевая средняя громкость фразы: −18 dBFS (26.09.2026). К ней приводим
     *  каждую фразу любого движка — тогда смена движка не слышна по громкости
     *  (гугловский читает тише, multiTTS громче). */
    private val loudTargetRms = 4125.0

    private fun trimBail(code: Int, what: String, f: File) {
        // «Дальше не повторяю» — но по каждой паре «причина + кто сделал файл»
        // отдельно: иначе отказ у репликового движка скрылся бы за таким же
        // отказом у основного (26.09.2026).
        if (!trimBailLogged.add("$code|$trimWho")) return
        Diag.log(
            appContext, "sound",
            "паузы: ${f.name} [$trimWho] не тронул — $what (причина $code; дальше не повторяю)"
        )
    }

    /** Обрезать тишину по краям синтезированного файла (msg4402). Разбираем
     *  только обычный 16-битный PCM-WAV (в том числе в «расширенном» заголовке) —
     *  если внутри что-то другое или файл не разобрался, оставляем как есть:
     *  пауза останется прежней, но чтение не сломается, а причина уйдёт в
     *  журнал через [trimBail]. Голову подрезаем сильнее хвоста — в начале
     *  тишина почти всегда «пустая», в конце в неё уходит затухание последнего
     *  слова. */
    /** Сколько времени уходит на обработку звука (26.09.2026). Серж спросил,
     *  сильно ли мы грузим процессор: отвечаем цифрами с его телефона, а не
     *  рассуждением. Считаем время прохода по отсчётам — обрезки тишины и
     *  выравнивания громкости — и пишем в журнал среднее и худшее на каждые
     *  двадцать пять фраз. */
    private var audioProcCount = 0
    private var audioProcTotalNs = 0L
    private var audioProcMaxNs = 0L

    private fun trimSilence(f: File, role: Pending.Role) {
        val t0 = System.nanoTime()
        trimSilenceInner(f, role)
        val spent = System.nanoTime() - t0
        audioProcCount++
        audioProcTotalNs += spent
        if (spent > audioProcMaxNs) audioProcMaxNs = spent
        if (audioProcCount % 25 == 0) {
            Diag.log(
                appContext, "sound",
                "обработка звука: фраз $audioProcCount, в среднем " +
                    "${fmtMs(audioProcTotalNs / audioProcCount)} мс, худшая ${fmtMs(audioProcMaxNs)} мс"
            )
        }
    }

    /** Миллисекунды с одним знаком для журнала. */
    private fun fmtMs(ns: Long): String =
        String.format(java.util.Locale.US, "%.1f", ns / 1_000_000.0)

    private fun trimSilenceInner(f: File, role: Pending.Role) {
        val b = runCatching { f.readBytes() }.getOrNull() ?: return
        val n = b.size
        if (n < 128 || n > 8_000_000) { trimBail(5, "размер не тот ($n байт)", f); return }
        if (String(b, 0, 4, Charsets.US_ASCII) != "RIFF" ||
            String(b, 8, 4, Charsets.US_ASCII) != "WAVE"
        ) { trimBail(1, "это не WAV", f); return }

        var off = 12
        var channels = 0
        var sampleRate = 0
        var bits = 0
        var dataOff = -1
        var dataLen = 0
        while (off + 8 <= n) {
            val id = String(b, off, 4, Charsets.US_ASCII)
            val sz = leInt(b, off + 4)
            if (sz < 0 || off + 8 + sz > n) {
                if (id == "data") { dataOff = off + 8; dataLen = n - dataOff }
                break
            }
            if (id == "fmt " && sz >= 16) {
                // msg4409: движки пишут и «расширенный» заголовок
                // (WAVE_FORMAT_EXTENSIBLE, тег 0xFFFE): подформат там лежит
                // GUID'ом, и для обычного PCM он тоже начинается единицей.
                // Раньше принимали только тег 1 — на таком файле обрезка молча
                // ничего не делала.
                val tag = leShort(b, off + 8)
                val pcm = tag == 1 ||
                    (tag == 0xFFFE && sz >= 40 && leInt(b, off + 32) == 1)
                if (!pcm) { trimBail(2, "формат не PCM (тег $tag)", f); return }
                channels = leShort(b, off + 10)
                sampleRate = leInt(b, off + 12)
                bits = leShort(b, off + 22)
            } else if (id == "data") {
                dataOff = off + 8
                dataLen = minOf(sz, n - dataOff)
            }
            off += 8 + sz + (sz and 1)
        }
        if (channels !in 1..2 || bits != 16 || sampleRate !in 8000..48000) {
            trimBail(3, "не тот звук (каналов $channels, бит $bits, Гц $sampleRate)", f)
            return
        }
        if (dataOff < 0 || dataLen < 3200) { trimBail(4, "нет блока data", f); return }

        val frame = channels * 2
        val frames = dataLen / frame
        if (frames < 400) { trimBail(5, "слишком короткий ($frames кадров)", f); return }

        fun ampOf(frameIdx: Int): Int {
            var m = 0
            var i = dataOff + frameIdx * frame
            repeat(channels) {
                val v = ((b[i + 1].toInt() shl 8) or (b[i].toInt() and 0xFF)).toShort().toInt()
                val a = if (v < 0) -v else v
                if (a > m) m = a
                i += 2
            }
            return m
        }

        val thresh = 300 // ≈ −40 dBFS: тише этого считаем тишиной
        val scanCap = minOf(frames, sampleRate * 2)
        var first = -1
        var i = 0
        while (i < scanCap) {
            if (ampOf(i) > thresh) { first = i; break }
            i++
        }
        if (first < 0) { trimBail(7, "сплошная тишина", f); return }
        var last = -1
        var j = frames - 1
        while (j > first) {
            if (ampOf(j) > thresh) { last = j; break }
            j--
        }
        if (last < 0) { trimBail(7, "сплошная тишина", f); return }

        // msg5604: остаток тишины на стыке задаёт настройка — две пятых в
        // голове фразы, три пятых в хвосте (при 130 мс это прежние 50 и 83 мс).
        val keep = pauseKeepMs.coerceIn(0, 1000)
        val headKeep = sampleRate * (keep * 2 / 5) / 1000
        val tailKeep = sampleRate * (keep * 3 / 5) / 1000
        val startF = (first - headKeep).coerceAtLeast(0)
        val endF = (last + 1 + tailKeep).coerceAtMost(frames)
        if (endF - startF < frames / 10) {
            trimBail(8, "после обрезки осталась бы десятая часть", f)
            return
        }

        val cutHead = startF * 1000 / sampleRate
        val cutTail = (frames - endF) * 1000 / sampleRate
        val needTrim = !(cutHead < 40 && cutTail < 60)

        // ---- Выравнивание громкости (26.09.2026) ----
        // Гугловский движок читает тише, multiTTS — громче, и при смене движка
        // это слышно. Считаем среднюю громкость звучащей части (RMS, уже без
        // краевой тишины) и домножаем отсчёты до общей цели: одна громкость у
        // всех движков, голосов и фраз.
        var rmsDb = 0.0
        var gainDb = 0.0
        var gain = 1f
        var peak = 0
        val usedFrames = endF - startF
        if (usedFrames > 0) {
            var sum = 0.0
            var k = startF
            while (k < endF) {
                var at = dataOff + k * frame
                repeat(channels) {
                    val v = ((b[at + 1].toInt() shl 8) or (b[at].toInt() and 0xFF)).toShort().toInt()
                    sum += v.toDouble() * v
                    val a = if (v < 0) -v else v
                    if (a > peak) peak = a
                    at += 2
                }
                k++
            }
            val rms = kotlin.math.sqrt(sum / (usedFrames * channels))
            if (rms >= 1.0 && peak > 0) {
                rmsDb = 20.0 * kotlin.math.log10(rms / 32768.0)
                gain = (loudTargetRms / rms).toFloat()
                // Не тянем тихое вчетверо и не глушим громкое вчетверо: дальше
                // это уже не выравнивание, а порча звука.
                gain = gain.coerceIn(0.25f, 4f)
                // Пики важнее цели: лучше чуть тише, чем хрип на громких звуках.
                val room = (32767f * 0.98f) / peak
                if (gain > room) gain = room
                if (kotlin.math.abs(gain - 1f) < 0.02f) gain = 1f
                gainDb = 20.0 * kotlin.math.log10(gain.toDouble())
            }
        }

        // ---- Ручная подстройка выше 100% (26.09.2026) ----
        // Ползунок громкости пускает до 200%, но плеер громче единицы не умеет.
        // Значит всё, что выше, домножаем здесь, в самом звуке: так тихий движок
        // (гугловский) можно именно ПОДНЯТЬ, а не только убавить громкий.
        val userVol = if (role == Pending.Role.REPLY) replyVolume else volume
        if (userVol > 1f && peak > 0) {
            gain *= userVol
            val room = (32767f * 0.98f) / peak
            if (gain > room) gain = room
            gainDb = 20.0 * kotlin.math.log10(gain.toDouble())
        }

        if (!needTrim && gain == 1f) {
            // Ни тишины по краям, ни разницы в громкости — файл не трогаем.
            trimBail(9, "тишины по краям нет (голова $cutHead мс, хвост $cutTail мс)", f)
            return
        }

        val outLen = (endF - startF) * frame
        val out = ByteArray(44 + outLen)
        System.arraycopy("RIFF".toByteArray(Charsets.US_ASCII), 0, out, 0, 4)
        System.arraycopy("WAVE".toByteArray(Charsets.US_ASCII), 0, out, 8, 4)
        System.arraycopy("fmt ".toByteArray(Charsets.US_ASCII), 0, out, 12, 4)
        System.arraycopy("data".toByteArray(Charsets.US_ASCII), 0, out, 36, 4)
        val putInt = { at: Int, v: Int ->
            out[at] = (v and 0xFF).toByte()
            out[at + 1] = ((v shr 8) and 0xFF).toByte()
            out[at + 2] = ((v shr 16) and 0xFF).toByte()
            out[at + 3] = ((v shr 24) and 0xFF).toByte()
        }
        val putShort = { at: Int, v: Int ->
            out[at] = (v and 0xFF).toByte()
            out[at + 1] = ((v shr 8) and 0xFF).toByte()
        }
        putInt(4, 36 + outLen)
        putInt(16, 16)
        putShort(20, 1)
        putShort(22, channels)
        putInt(24, sampleRate)
        putInt(28, sampleRate * frame)
        putShort(32, frame)
        putShort(34, 16)
        putInt(40, outLen)
        System.arraycopy(b, dataOff + startF * frame, out, 44, outLen)

        // Домножаем отсчёты на выравнивающий коэффициент (16 бит, little-endian).
        if (gain != 1f) {
            var at = 44
            val end = 44 + outLen - 1
            while (at < end) {
                val v = ((out[at + 1].toInt() shl 8) or (out[at].toInt() and 0xFF)).toShort().toInt()
                var s = (v * gain).toInt()
                if (s > 32767) s = 32767
                if (s < -32768) s = -32768
                out[at] = (s and 0xFF).toByte()
                out[at + 1] = ((s shr 8) and 0xFF).toByte()
                at += 2
            }
        }

        if (!runCatching { f.writeBytes(out) }.isSuccess) return
        // В журнал — сколько тишины движок дописал ВСЕГО и сколько из неё
        // срезано: по этой строке видно, из чего состояла пауза между
        // предложениями (msg4409: «на слух ничего не меняет» — вот цифры).
        // Плюс громкость: измеренная и сдвиг — по ним видно выравнивание.
        val silHead = first * 1000 / sampleRate
        val silTail = (frames - 1 - last) * 1000 / sampleRate
        Diag.log(
            appContext, "sound",
            "паузы: у ${f.name} [$trimWho] тишины было ${silHead} мс в начале и ${silTail} мс в конце; " +
                "срезано ${cutHead} и ${cutTail} мс; громкость ${fmtDb(rmsDb)} dBFS, сдвиг ${fmtDb(gainDb)} dB"
        )
    }

    /** Децибелы с одним знаком для журнала (точка, а не запятая: журнал читают
     *  скриптом и глазами). */
    private fun fmtDb(v: Double): String = String.format(java.util.Locale.US, "%.1f", v)

    // ---------------- Файлы играет ExoPlayer ----------------

    /** Играет ли сейчас наш звук — по состоянию ExoPlayer. Все сторожа
     *  спрашивают здесь. */
    private fun soundPlaying(): Boolean = exoFilePlayingSafe()

    // Сторож замершей позиции: пока позиция НИ РАЗУ не росла — не судим (на
    // части прошивок currentPosition всегда ноль, и мы бы рвали фразы на ровном
    // месте); увидели рост, а потом позиция встала на три проверки подряд —
    // фразу считаем потерянной и говорим её напрямую движком, иначе чтение
    // замолчит навсегда.
    private var exoPosToken = 0
    private var exoPosLast = -1L
    private var exoPosSawProgress = false
    private var exoPosStuckHits = 0
    private val exoPosCheck = object : Runnable {
        override fun run() {
            if (!exoFilePlayingSafe()) return
            val pos = runCatching { filePlayer.positionMs }.getOrDefault(-1L)
            if (pos > exoPosLast) {
                exoPosSawProgress = true
                exoPosStuckHits = 0
            } else if (exoPosSawProgress) {
                if (++exoPosStuckHits >= EXO_POS_STUCK_HITS) {
                    exoPosStuckHits = 0
                    Diag.log(
                        appContext, "sound",
                        "exo: позиция стоит ${EXO_POS_STUCK_HITS * EXO_POS_STEP_MS / 1000} с — " +
                            "фраза потерялась, говорю напрямую",
                    )
                    fallbackDirect(currentText, currentPos, currentPart)
                    return
                }
            }
            exoPosLast = pos
            main.postDelayed(this, EXO_POS_STEP_MS)
        }
    }

    /** Взвести сторож позиции заново — на каждой новой фразе: у неё своя позиция. */
    private fun armExoPositionWatch() {
        val token = ++exoPosToken
        exoPosLast = -1L
        exoPosSawProgress = false
        exoPosStuckHits = 0
        main.removeCallbacks(exoPosCheck)
        main.postDelayed(exoPosCheck, EXO_POS_STEP_MS)
        // Токен нужен только чтобы старый экземпляр проверки не ожил после
        // остановки: releaseMedia его увеличивает.
        if (token < 0) exoPosToken = 0
    }

    /** Снять сторож позиции (звук погашен или пошёл напрямую). */
    private fun dropExoPositionWatch() {
        exoPosToken++
        exoPosStuckHits = 0
        exoPosSawProgress = false
        exoPosLast = -1L
        main.removeCallbacks(exoPosCheck)
    }

    // ——— ЕДИНИЦЫ РЕЧИ: ключ, порядок, «звучала ли уже» (08.10.2026) ———
    //
    // Разбор жалобы Сержа «два раза какая-то фраза повторялась» (журнал 21:43 и
    // 12:45). Фраза книги бывает разрезана на куски, и куски шли с ОДНОЙ
    // позицией — опознать их было нечем. Отсюда два следствия: хвост фразы
    // вставал в список плеера ПОСЛЕ следующего предложения (оно уже стояло
    // заготовкой), а чтение, услышав «доиграла» от чужого файла, двигало место
    // в книге и просило фразу, которая только что прозвучала; кэш сыгранных
    // отдавал её звук, и повтор слышался мгновенно.
    //
    // Теперь у каждой единицы речи есть КЛЮЧ (позиция + номер куска), и он один
    // служит опознанием везде: в очереди заготовок, в списке плеера, в кэше и в
    // отчёте «доиграла». Два правила держат порядок:
    //   1) список плеера наполняется ТОЛЬКО по порядку ключей — заготовка, до
    //      которой ещё не дошла очередь, ждёт в [readyQueue];
    //   2) единица, уже прозвучавшая в этом проходе, вперёд не звучит второй раз
    //      (повтор — только по просьбе человека, тогда играем из кэша).
    // Прежнего порядка больше нет: выключатель убран 08.10.2026, когда новый
    // отстоялся на живом чтении.
    //
    // ПОЛЯ ЭТОГО РАЗДЕЛА ОБЪЯВЛЕНЫ НАВЕРХУ КЛАССА (см. «единицы речи» у
    // [appContext]) — не переносить их сюда: [resetPipeline] зовётся из
    // конструктора (start из init), и поля, объявленные НИЖЕ конструктора, в
    // этот момент ещё null (на этом приложение падало при запуске 08.10.2026:
    // NPE на playedKeys.clear()).

    private fun logOrderOnce(what: String, line: String) {
        if (orderLogged.add(what)) Diag.log(appContext, "sound", line)
    }

    /** Сколько кусков у фразы с позицией [pos]; 1 — обычная фраза одним файлом. */
    private fun partsOf(pos: Long): Int = if (pos < 0) 1 else (phraseParts[pos] ?: 1)

    /** Запомнить, что у фразы [pos] кусков [n]. Меньшее число не затирает
     *  большее: куски называют по одному, и последний заказ знает всё.
     *
     *  Карту подчищаем по мере чтения: держим только недавние позиции (иначе за
     *  многочасовое чтение она растёт без предела). Убираем то, что далеко позади
     *  читаемого места, — к нему уже не вернутся иначе как прыжком, а прыжок
     *  заказывает фразу заново и число кусков запишется снова. */
    private fun registerParts(pos: Long, n: Int) {
        if (pos < 0 || n <= 1) return
        if (phraseParts.size > 4000) {
            val from = pos - 2000
            phraseParts.keys.removeAll { it < from }
        }
        val was = phraseParts[pos] ?: 0
        if (n > was) phraseParts[pos] = n
    }

    /** Номер куска для очередного «говори»: кусок той же фразы — следующий,
     *  новой фразы — нулевой. Так чтение, называющее куски по одному
     *  (`ReaderEngine.pendingFragments`), нумеруется без своих правок. */
    private fun nextPartFor(pos: Long): Int {
        val part = if (pos >= 0 && pos == lastAskedPos) lastAskedPart + 1 else 0
        lastAskedPos = pos
        lastAskedPart = part
        registerParts(pos, part + 1)
        return part
    }

    /** Ключ единицы, которая обязана звучать сразу после ([pos], [part]). */
    private fun expectedAfter(pos: Long, part: Int): Long? {
        if (pos < 0) return null
        if (part + 1 < partsOf(pos)) return Units.key(pos, part + 1)
        // Последний кусок фразы: следующей идёт первая единица следующей фразы
        // книги. Что это за фраза, знает только чтение ([onNeedAfter]).
        val next = onNeedAfter?.invoke(pos) ?: return null
        return Units.key(next, 0)
    }

    /** Ключ, который обязан звучать следующим: после последней единицы в списке
     *  плеера, а если список пуст — после последней доигравшей. */
    private fun expectedNextKey(): Long? {
        val last = exoPending.lastOrNull()
        if (last != null && last.pos >= 0) return expectedAfter(last.pos, last.part)
        if (lastPlayedPos >= 0) return expectedAfter(lastPlayedPos, lastPlayedPart)
        return null
    }

    /** Последний ли это кусок фразы: по нему чтение понимает, можно ли двигать
     *  место в книге. Место неизвестно — считаем «последний»: пусть двигает, как
     *  двигало раньше, чем встанет насовсем. */
    private fun lastOfPhrase(pos: Long, part: Int): Boolean =
        pos < 0 || part < 0 || part + 1 >= partsOf(pos)

    /** Единственный путь сообщить чтению «доиграла»: вместе с сигналом уходят
     *  место и кусок единицы, иначе чтение не может отличить свой конец от
     *  чужого (см. `ReaderEngine.onPlayerDone`). [pos] < 0 — место неизвестно
     *  (ошибка, служебная фраза): чтение ведёт себя как раньше. */
    private fun reportDone(pos: Long = -1L, part: Int = -1, last: Boolean = true) {
        lastDonePos = pos
        lastDonePart = part
        lastDoneLast = last
        val cb = onDone
        cb?.invoke()
    }

    /** Отметить единицу прозвучавшей в этом проходе. По этой отметке вперёд она
     *  больше не зазвучит: повтор — только по просьбе человека. */
    private fun noteUnitPlayed(pos: Long, part: Int) {
        lastPlayedPos = pos
        lastPlayedPart = part
        if (pos >= 0) playedKeys.add(Units.key(pos, part))
    }

    /** Начать играть фразу новым плеером. [positionMs] — продолжение паузы с
     *  середины файла: у ExoPlayer позиция точная, переигрывать начало не нужно. */
    private fun exoPlay(
        text: String,
        f: File,
        rate: Float,
        positionMs: Long = 0L,
        pos: Long = -1L,
        part: Int = 0,
    ) {
        // 29.09.2026 (потеря текста в 187): если звук УЖЕ идёт, список не
        // перезапускаем — фразу ДОПИСЫВАЕМ за звучащей. Перезапуск выбрасывал всё,
        // что стояло впереди, и плеер прыгал через несколько фраз.
        if (positionMs == 0L && exoFilePlayingSafe() && playingText != null && exoPending.isNotEmpty()) {
            exoAppend(text, f, rate, pos, part, automatic = false)
            return
        }
        playingText = text
        playingPos = pos
        playingPart = part
        playingKey = Units.key(pos, part)
        playingFile = f
        playingRate = rate
        exoAhead = 0
        exoPending.clear()
        exoPending.addLast(Prepared(text, f, rate, roleOfFile(f), pos = pos, part = part))
        filePlayer.setListener(exoListener)
        exoSyncSpeed(exoPending.last())
        filePlayer.setVolume(volumeFor(f))
        filePlayer.play(
            listOf(FilePlayback.Item(id = ++exoSeq, text = text, file = f)),
            startIndex = 0,
            startPositionMs = positionMs,
        )
        armExoStartWatch(text)
        armSoundWatch()
        exoTopUp()
    }

    /** Фраза от читалки в новом пути. Правила: звучит сейчас — не трогаем; уже
     *  стоит впереди в списке — ждём её (список НЕ перезапускаем, иначе гибнет всё,
     *  что впереди, — это и была потеря текста в 187); в списке нет — выбрасываем
     *  хвост и дописываем эту фразу за звучащей. */
    private fun speakExo(text: String, pos: Long, part: Int, userAsked: Boolean) {
        // 29.09.2026: слушателя ставим ЗДЕСЬ, при каждом обращении чтения. В 190
        // его ставили только в exoPlay (когда список начинается заново), а если
        // фраза уже лежала в списке (подготовили заранее) — плеер пускали без
        // слушателя, и «фраза доиграла» до чтения не доходила: чтение вставало.
        filePlayer.setListener(exoListener)
        // 30.09.2026: вместе с фразой взводим сторож звука — если она так и не
        // зазвучит (мёртвый список плеера после ошибки файла), чтение не замолчит.
        armSoundWatch()
        // 08.10.2026: сверяемся по КЛЮЧУ единицы речи (место в книге + номер
        // куска), а не по тексту: у фразы бывает несколько кусков с одной
        // позицией, и текст не опознание — в книге полно одинаковых фраз.
        val key = Units.key(pos, part)
        // 1) эта единица звучит прямо сейчас
        val sameSounding = if (key >= 0) playingKey == key else playingText == text && playingPos == pos
        if (sameSounding && exoFilePlayingSafe()) {
            Diag.log(appContext, "sound", "exo: эта фраза уже звучит — очередь не трогаю")
            requestPrefetch()
            exoTopUp()
            return
        }
        // 2) она уже впереди в списке плеера — просто ждём
        val ahead = exoPending.any { if (key >= 0) it.key == key else it.text == text && it.pos == pos }
        if (ahead) {
            Diag.log(appContext, "sound", "exo: фраза уже впереди в списке — жду её")
            // 29.09.2026: после паузы или после подготовки первой фразы плеер
            // стоит молча — «продолжить» должно его просто пустить (жалоба Сержа:
            // «ставлю на паузу, нажимаю воспроизвести, а он молчит»).
            if (!exoFilePlayingSafe()) {
                runCatching { filePlayer.resume() }
                Diag.log(appContext, "sound", "exo: пускаю список (был на паузе)")
            }
            requestPrefetch()
            exoTopUp()
            return
        }
        // 2б) ПОРЯДОК (08.10.2026). Эта единица уже прозвучала в нынешнем проходе,
        // а просит её само чтение по ходу книги (не человек). Второй раз вперёд она
        // не звучит: повтор — только по просьбе человека, и тогда играем из кэша.
        // Если чтение догнало уже прозвучавшее — его указатель уехал: сообщаем
        // «доиграла», чтобы оно шло дальше (так чтение само подтягивается к тому
        // месту, которое реально звучит), и пишем это в журнал.
        if (!userAsked && key >= 0 && playedKeys.contains(key)) {
            logOrderOnce(
                "repeat-$key",
                "порядок: ${Units.label(pos, part)} уже звучала в этом проходе — " +
                    "второй раз по ходу книги не читаю, двигаю место дальше"
            )
            awaitingPlayText = null
            awaitingPos = -1L
            awaitingPart = -1
            reportDone(pos, part, lastOfPhrase(pos, part))
            return
        }
        // 3) её в списке нет: хвост вон (звучащую не трогаем), эту — за звучащей
        exoDropTail()
        // 3а) пауза сохранила звук ровно этой фразы — продолжаем с того места
        takeKeptPhrase(text, pos, part)?.let { kept ->
            exoPlay(kept.text, kept.file, kept.rate, keptPositionMs, kept.pos, kept.part)
            // 05.10.2026 (журнал 23:58, жалоба «большая пауза»): здесь НЕ
            // заказывали следующие фразы, и движок стоял вхолостую всё время,
            // пока играл сохранённый файл (в том журнале — 10,1 с). Следующую
            // фразу он начинал писать только после её конца, уже в тишине:
            // TeraTTS на скорости 1,5 потратил на неё 2,4 с, и человек услышал
            // паузу в 2,7 с на ровном месте. Теперь очередь заказываем сразу,
            // как в ветке «фраза в голове очереди» ниже (все остальные ветки
            // [speakExo] так и делают — эта одна осталась без заказа).
            requestPrefetch()
            return
        }
        // 3а-2) фраза уже ЗВУЧАЛА недавно — её звук ждёт в кэше сыгранных
        // (07.10.2026, просьба Сержа «сделать кэш двух-трёх последних фраз»).
        // Сюда приходят «повторить фразу», шаг назад («Пред.») и возврат к
        // прежнему месту: раньше каждое такое нажатие стоило нового синтеза —
        // на медленном движке это секунды тишины.
        // 08.10.2026: кэш отдаём ТОЛЬКО по просьбе человека. По ходу книги
        // вперёд он не нужен вовсе, а именно он делал слышимый повтор мгновенным
        // (журнал 21:43 и 12:45): чтение просило уже прозвучавшую фразу, а кэш
        // отдавал её звук без задержки.
        if (userAsked) {
            takePlayed(text, pos, part)?.let { done ->
                awaitingPlayText = null
                awaitingPos = -1L
                awaitingPart = -1
                exoPlay(done.text, done.file, done.rate, 0L, done.pos, done.part)
                requestPrefetch()
                return
            }
        }
        // 3б) фраза в очереди, но не первая: всё перед ней чтение уже прошло
        // (прыжок вперёд) — выбрасываем и играем её. Без этого мы бы заказали её
        // заново и услышали в другой раз (30.09.2026).
        // 08.10.2026: сверяемся по ключу единицы, а не по тексту с позицией: у
        // фразы бывает несколько кусков с одной позицией (см. [Units.key]).
        val sameUnit = { p: Prepared -> if (key >= 0) p.key == key else p.text == text && p.pos == pos }
        val deeper = readyQueue.indexOfFirst { sameUnit(it) && it.rate == rateFor(it.role) }
        if (deeper > 0) {
            repeat(deeper) { runCatching { readyQueue.removeFirst().file.delete() } }
        }
        val head = readyQueue.firstOrNull()
        if (head != null && sameUnit(head) && head.rate == rateFor(head.role)) {
            readyQueue.removeFirst()
            awaitingPlayText = null
            awaitingPos = -1L
            awaitingPart = -1
            exoPlay(text, head.file, head.rate, 0L, head.pos, head.part)
            requestPrefetch()
            return
        }
        // 23.10.2026: заявка по этой единице уже в пути? Спрашиваем по КЛЮЧУ
        // (место + кусок), а не по тексту: две одинаковые реплики из разных мест
        // книги — разные единицы, и по тексту вторая не нашла бы свою заявку.
        if (fileInFlightAny(pos, part, text) != null) {
            // Заявка уже в пути: ждём её, файл придёт в synthFinished.
            awaitingPlayText = text
            awaitingPos = pos
            awaitingPart = part
            // 05.10.2026 (журнал 21:12, «зашёл в голос — большая пауза»): заявка у
            // движка УЖЕ есть, и если ждать её приходится в полной тишине (звука
            // нет, очередь пуста) — это тот же ХОЛОДНЫЙ СТАРТ, что и в ветке ниже:
            // движок пишет фразу с нуля, а за ней у него в работе ещё заготовки.
            // Без окна терпения сторож через 2,5 с считал заявку потерянной,
            // отменял её, стирал файл и заказывал заново — и так пять кругов с
            // двумя перезапусками движка, 14,6 с тишины. А движок в это время
            // писал фразы исправно: у TeraTTS на скорости 1,8 это около 20 мс на
            // знак (27 знаков за 0,53 с, 163 знака за 2,9 с), то есть склейка до
            // 220 знаков пишется до 4,5 с — ДОЛЬШЕ нашего срока.
            if (waitingSilently()) {
                armVoiceWarmup(
                    "фраза уже заказана движку, жду её в тишине",
                    timing.coldStartMs,
                    bySwitch = false,
                )
            } else {
                // Звук идёт — этой паузы не слышно, но срок сторожа надо
                // пересчитать: прежний взведён, когда фраза была ещё заготовкой
                // (другой срок и другая точка отсчёта).
                armSynthWatch(text)
            }
            return
        }
        // 05.10.2026: здесь был «холодный старт» — фраза уходила движку на
        // произнесение (идея Сержа «играть, не дожидаясь конца фразы»). Работало
        // быстро (65-88 мс против 2-4 с), но ОТКАЧЕНО в тот же вечер: движок
        // (TeraTTS) не делает файлы, пока говорит сам, — заготовки впрок
        // дохли по сторожу, и сторож перезапускал движок прямо посреди живой
        // речи. В журнале 18:18 после этого чтение встало насовсем: фраза
        // оборвана, «доиграла» не придёт, ждать нечего. Разбор и что делать
        // дальше — docs/BACKLOG.md.
        //
        // 05.10.2026, вечер (журнал 18:43, «на прыжках большие паузы»): у этого
        // же холодного старта была вторая беда — СРОК. TeraTTS пишет длинную
        // фразу 3-4,6 с (замер: 15 мс на знак), а сторож ждал 2,5 с, потом
        // переспрашивал фразу и дважды перезапускал движок — каждый раз выбрасывая
        // уже написанное. На круг выходило 15 с тишины и прямая речь: в журнале
        // предл. 61 и 62 так и пропали. Поэтому первой фразе без запаса даём окно
        // терпения ([armVoiceWarmup]) — тогда она просто доспевает.
        if (coldStart(pos, part, text)) {
            // Первая фраза после начала чтения: пока она не прозвучала, человек
            // слышит ТОЛЬКО тишину, и ждать долго нельзя (17.10.2026, просьба
            // Сержа «не говори, что синтезатор не готов, долго жду»).
            coldPhrasePending = true
            armVoiceWarmup(
                "холодный старт: готового звука нет, фраза пишется с нуля",
                timing.coldStartMs,
                bySwitch = false,
            )
        }
        awaitingPlayText = text
        awaitingPos = pos
        awaitingPart = part
        synthToFile(text, pos, part)
    }

    /** Фразу придётся ждать В ПОЛНОЙ ТИШИНЕ: ничего не играет и в очереди
     *  заготовок пусто. Значит, каждый миллисекунд ожидания человек слышит. */
    private fun waitingSilently(): Boolean {
        if (directMode) return false
        if (exoFilePlayingSafe()) return false
        if (readyQueue.isNotEmpty()) return false
        return true
    }

    /** Холодный старт (см. [speakExo]): фразу надо синтезировать с нуля, и
     *  готового звука нет ни одной — ни в плеере, ни в очереди заготовок. Так
     *  бывает после прыжка, в начале чтения, после смены голоса и после
     *  настоящего «стоп» (не паузы). */
    private fun coldStart(pos: Long, part: Int, text: String): Boolean =
        waitingSilently() && fileInFlightAny(pos, part, text) == null

    /** Что вышло из попытки дописать единицу в список плеера. */
    private enum class AppendResult { ADDED, HELD, DROPPED }

    /** Дописать одну фразу в конец списка плеера (с записью в зеркало).
     *
     *  [automatic] — дописывает не чтение, а сама очередь заготовок
     *  ([exoTopUp]). Только для неё работает правило ПОРЯДКА (08.10.2026):
     *  список ExoPlayer играется как стоит, поэтому автоматически дописать можно
     *  ровно СЛЕДУЮЩУЮ единицу речи. Всё, что заказано дальше, ждёт в
     *  [readyQueue] — иначе хвост фразы оказывался позади следующего
     *  предложения, а чтение, услышав конец чужого файла, двигало место и
     *  просило уже прозвучавшее (журнал 21:43 и 12:45). Запрос самого чтения
     *  ([automatic] = false) — это прыжок или повтор: он список переставляет,
     *  как скажет человек. */
    private fun exoAppend(
        text: String,
        f: File,
        rate: Float,
        pos: Long,
        part: Int,
        automatic: Boolean,
    ): AppendResult {
        // 29.09.2026, жалоба Сержа «одна фраза прочиталась три раза» (журнал
        // 17:40:57): на старте чтения читалка успевала ответить на заказ дважды
        // по-разному — сначала одной фразой, потом другой, — сверка конвейера
        // выбрасывала хвост и заказывала заново, а копии УЖЕ дописанных в плеер
        // фраз оставались в списке и звучали подряд. Сверку это не лечит (её
        // причину убрали отдельно), но услышать одну фразу дважды мы не должны
        // ни при каком раскладе: ту же фразу второй раз в список не берём.
        val key = Units.key(pos, part)
        val same = exoPending.firstOrNull { if (key >= 0) it.key == key else it.text == text && it.pos == pos }
        if (same != null && same.rate == rate) {
            runCatching { f.delete() }
            Diag.log(appContext, "sound", "exo: такая фраза уже есть в списке — лишнюю не беру (${f.name})")
            return AppendResult.DROPPED
        }
        if (same != null) {
            // Та же фраза, но сделанная на прежней скорости (или прежним голосом):
            // она устарела — выбрасываем хвост списка и берём свежую.
            Diag.log(
                appContext, "sound",
                "exo: фраза в списке сделана на скорости ${same.rate}, а нужна $rate — беру свежую"
            )
            exoDropTail()
        }
        val sameSounding = if (key >= 0) playingKey == key else text == playingText && pos == playingPos
        if (sameSounding) {
            runCatching { f.delete() }
            Diag.log(appContext, "sound", "exo: эта фраза уже звучит — лишнюю не беру (${f.name})")
            return AppendResult.DROPPED
        }
        // ПОРЯДОК (08.10.2026): очередь заготовок дописывает только следующую
        // единицу. Ключ, который ещё не наступил, не «выбрасываем» и не
        // переставляем — он ждёт своей очереди в [readyQueue]. Ждём только то,
        // что и правда есть в конвейере: если жданной единицы нигде нет (заявка
        // сорвалась, кусок убрал словарь), держать бессмысленно — чтение встало
        // бы в тишину.
        if (automatic) {
            val expect = expectedNextKey()
            if (expect != null && key >= 0 && key != expect) {
                if (unitInPipeline(expect)) {
                    logOrderOnce(
                        "hold-$key",
                        "порядок: заготовка ${Units.label(pos, part)} ждёт своей очереди " +
                            "(следующей должна звучать ${Units.labelOfKey(expect)})"
                    )
                    return AppendResult.HELD
                }
                logOrderOnce(
                    "gone-$expect",
                    "порядок: единицы ${Units.labelOfKey(expect)} в конвейере нет " +
                        "(заявка сорвалась или кусок убран) — беру следующую"
                )
            }
        }
        exoPending.addLast(Prepared(text, f, rate, roleOfFile(f), pos = pos, part = part))
        filePlayer.append(listOf(FilePlayback.Item(id = ++exoSeq, text = text, file = f)))
        Diag.log(appContext, "sound", "exo: дописал фразу (${f.name}), впереди ${exoPending.size - 1}")
        return AppendResult.ADDED
    }

    /** Есть ли эта единица речи где-нибудь в конвейере: в списке плеера, в
     *  очереди готовых заготовок или в работе у движка. Нужно правилу порядка
     *  ([exoAppend]): ждать имеет смысл только то, что и правда придёт. */
    private fun unitInPipeline(key: Long): Boolean {
        if (key < 0) return false
        if (exoPending.any { it.key == key }) return true
        if (readyQueue.any { it.key == key }) return true
        return pending.values.any { !it.cancelled && Units.key(it.pos, it.part) == key }
    }

    /** Файл [p] уже сделан движком на скорости [Prepared.rate] — плееру задаём
     *  только отношение «нужная скорость / темп файла». Обычно это ровно 1.0:
     *  файл свежий. Не 1.0 бывает, когда ползунок двинули на ходу (тогда звучащий
     *  файл дотягивается до нового темпа) или
     *  когда в списке лежит заготовка прежней скорости. */
    private fun exoSyncSpeed(p: Prepared) {
        val fileRate = if (p.rate > 0f) p.rate else 1f
        exoPlayingRate = fileRate
        val want = rateFor(p.role)
        val ratio = (want / fileRate).coerceIn(0.25f, 4f)
        runCatching { filePlayer.setSpeed(ratio) }
        // Тон доводим так же, как темп: файл записан движком на [pitchFor] своего
        // времени, а звучать должен на нынешнем ползунке (29.09.2026).
        val madeAt = filePitchOf(p.file)
        exoPlayingPitch = if (madeAt > 0f) madeAt else 1f
        val pitchRatio = (pitchFor(p.role) / exoPlayingPitch).coerceIn(0.25f, 4f)
        runCatching { filePlayer.setPitch(pitchRatio) }
    }

    /** Выбросить из списка всё, что ещё не звучало (звучащую фразу не трогаем) —
     *  так уходят неверные заготовки, не обрывая речь. */
    private fun exoDropTail() {
        if (exoPending.size <= 1) return
        val keep = exoPending.first()
        while (exoPending.size > 1) {
            val dropped = exoPending.removeLast()
            runCatching { dropped.file.delete() }
        }
        exoAhead = 0
        runCatching { filePlayer.dropAhead(0) }
        Diag.log(appContext, "sound", "exo: хвост выброшен, оставил «${keep.file.name}»")
    }

    /** Дописать в список заготовки из [readyQueue] — это замена прицепке встык:
     *  у ExoPlayer очередь настоящая, и впереди может стоять сколько угодно фраз. */
    private fun exoTopUp() {
        var appended = 0
        // 30.09.2026, жалоба Сержа «были похожие фразы, и одна прочиталась дважды»
        // (журнал 15:17:02): книгу читает один движок, реплики — второй, и заявки
        // они выполняют с разной скоростью. Фразы уходили в плеер в порядке
        // ГОТОВНОСТИ: соседние «такая ты сладкая!» (книга, готова быстро) и
        // «- Я бы тебя съел...» (реплика, готовилась дольше) вставали в списке
        // наоборот, и слушатель слышал их переставленными. Хуже: пауза сохраняла
        // звучащую (реплика), а чтение уже стояло на следующей фразе — после
        // «продолжить» та же фраза звучала ВТОРОЙ раз.
        // Теперь фразу, заказанную позже той, что ещё в работе, держим в очереди:
        // порядок заказа = порядок звучания (см. [Prepared.req]).
        val earliest = earliestInFlight()
        // Одна фраза звучит, [prefetchDepth] - 1 держим впереди — считаем по
        // зеркалу: очередь заготовок к этому моменту уже опустела, фразы ушли в плеер.
        while (exoPending.size - 1 < prefetchDepth - 1 && readyQueue.isNotEmpty()) {
            val head = readyQueue.first()
            if (earliest != null && head.req != 0L && head.req > earliest) {
                if (heldForOrderLogged != head.req) {
                    heldForOrderLogged = head.req
                    Diag.log(
                        appContext, "sound",
                        "exo: держу фразу (${head.file.name}) «${FilePlayback.brief(head.text)}» — " +
                            "раньше неё заказана другая, жду её"
                    )
                }
                break
            }
            // 07.10.2026, ПОРЯДОК ПО КНИГЕ (жалоба Сержа «фразы повторяются»,
            // журнал 00:35). Список у ExoPlayer играется как стоит, поэтому
            // заготовка обязана быть ровно той фразой, что идёт сразу за
            // последней уже стоящей в списке. Если во главе очереди фраза не
            // она (следствие сбоя в заказе заготовок) — НЕ берём и ВЫБРАСЫВАЕМ:
            // иначе она прозвучит раньше очереди, чтение уедет (оно считает фразы
            // по «фраза доиграла»), а потом та же фраза закажется и прозвучит
            // второй раз. Держать её нельзя: непонятный файл в очереди мешает
            // считать, сколько фраз заказано вперёд ([phrasesAhead]), и заказ
            // уходил бы всё дальше. Понадобится — чтение попросит её само.
            // Куски одной фразы (слова автора и реплика) идут с одной позицией —
            // им дорога открыта.
            //
            // 08.10.2026: сверку ведёт [exoAppend] по КЛЮЧУ единицы речи (место
            // в книге + номер куска). Если очередь заготовок забежала вперёд —
            // она больше НЕ выбрасывается, а просто ждёт своей очереди: кусок
            // текущей фразы обязан прозвучать раньше следующего предложения
            // (см. [Units.key]).
            when (exoAppend(head.text, head.file, head.rate, head.pos, head.part, automatic = true)) {
                AppendResult.ADDED -> {
                    readyQueue.removeFirst()
                    appended++
                }
                AppendResult.DROPPED -> readyQueue.removeFirst()
                AppendResult.HELD -> break
            }
        }
        if (appended > 0) {
            Diag.log(appContext, "sound", "exo: дописал заготовок $appended (впереди ${exoPending.size - 1})")
        }
    }

    /** Положить готовую фразу в очередь НА СВОЁ место — по номеру заявки.
     *
     *  30.09.2026, журнал 215 (15:30:18-15:30:25): простого «держу фразу» оказалось
     *  мало. Книжную фразу (s_5, предл. 1175) движок отдал раньше, чем реплику
     *  (s_4, предл. 1174), её придержали — а когда реплика доспела, она встала в
     *  КОНЕЦ очереди, то есть ПОСЛЕ придержанной. На слух вышло: сначала «Мы сейчас
     *  ме-е-едленно…» (1175), потом «- Нет.» (1174), а затем чтение, дойдя до 1175,
     *  заказало эту фразу заново и она прозвучала ВТОРОЙ раз (s_9). Порядок в
     *  очереди теперь держится по номеру заявки, а не по времени готовности. */
    private fun addReadyInOrder(p: Prepared) {
        if (p.req == 0L) {
            readyQueue.addLast(p)
            return
        }
        val at = readyQueue.indexOfFirst { it.req != 0L && it.req > p.req }
        if (at < 0) readyQueue.addLast(p) else readyQueue.add(at, p)
    }

    /** О какой фразе уже сказали «держу» — чтобы не повторять строку в журнале. */
    private var heldForOrderLogged = 0L

    /** Самая ранняя заявка, которая ещё в работе (файл не пришёл). Если такой
     *  нет — отдавать плееру можно всё. */
    private fun earliestInFlight(): Long? =
        pending.entries.filter { it.value.kind == Pending.Kind.FILE }.minOfOrNull { it.key }

    /** Сколько ФРАЗ (позиций книги) уже заказано вперёд. Куски одной фразы —
     *  слова автора и реплика — занимают одну позицию ([Prepared.pos]), поэтому
     *  считаем разные позиции, а не куски (05.10.2026: иначе двухкусковая фраза
     *  сбивала бы отсчёт [requestPrefetch]). 07.10.2026: в счёт идут только
     *  позиции ДАЛЬШЕ читаемой фразы — куски её самой «впереди» не считаются
     *  (см. комментарий внутри). */
    private fun phrasesAhead(): Int {
        val seen = HashSet<Long>()
        // 07.10.2026 (жалоба Сержа «фразы повторяются», журнал 00:35): считаем
        // «впереди» только то, что ДАЛЬШЕ читаемой фразы ([currentPos]). Было —
        // все позиции подряд, и в счёт попадали куски самой читаемой фразы: её
        // слова автора уходили в работу через [prefetchRest] с той же позицией,
        // и [requestPrefetch] думал, что одна фраза уже заказана. Он просил у
        // чтения фразу через одну, та вставала в список плеера, звучала раньше
        // очереди — и текст повторялся. В книгах с прямой речью (эта книга —
        // сплошные реплики) такая фраза с двумя кусками почти каждая.
        // currentPos < 0 — позиции не знаем (первый заказ): считаем как раньше.
        val from = currentPos
        fun count(pos: Long) {
            if (pos < 0) return
            if (from >= 0 && pos <= from) return
            seen.add(pos)
        }
        if (exoPending.size > 1) {
            exoPending.drop(1).forEach { count(it.pos) }
        }
        readyQueue.forEach { count(it.pos) }
        // 23.10.2026: заявки в работе берём из [pending] (отдельного набора
        // «текстов в работе» больше нет) — по позиции и куску, а не по тексту.
        pending.values.forEach { if (it.kind == Pending.Kind.FILE && !it.cancelled) count(it.pos) }
        return seen.size
    }

    /** Сколько ЗНАКОВ текста уже заказано или стоит впереди читаемой фразы
     *  (07.10.2026). Считаем так же, как [phrasesAhead], только знаками: фраза
     *  бывает и в двадцать знаков, и в двести двадцать, и глубина «в штуках»
     *  давала то четверть секунды запаса, то двадцать секунд. */
    private fun aheadCharsAhead(): Int {
        val from = currentPos
        var sum = 0
        fun add(text: String, pos: Long) {
            if (pos < 0) return
            if (from >= 0 && pos <= from) return
            sum += text.length
        }
        if (exoPending.size > 1) {
            exoPending.drop(1).forEach { add(it.text, it.pos) }
        }
        readyQueue.forEach { add(it.text, it.pos) }
        pending.values.forEach {
            if (it.kind == Pending.Kind.FILE && !it.cancelled) add(it.text, it.pos)
        }
        return sum
    }

    /** Цель запаса в знаках: ступень настройки × [ExpertPrefs.AHEAD_CHARS_PER_STEP]. */
    private fun aheadCharsTarget(): Int = prefetchDepth * ExpertPrefs.AHEAD_CHARS_PER_STEP

    /** Потолок запаса в ФРАЗАХ: знаки знаками, а на книге из коротких предложений
     *  очередь иначе разрослась бы до десятков файлов. Две ступени сверху к
     *  настройке и не больше восьми — дальше выигрыша нет, только память. */
    private fun aheadPhraseCap(): Int = (prefetchDepth + 2).coerceAtMost(8)

    /** Сторож «звук не начался»: молчание лечим прямой речью. */
    private fun armExoStartWatch(text: String) {
        val token = ++exoStartToken
        main.postDelayed({
            if (token != exoStartToken) return@postDelayed
            if (!exoFilePlayingSafe()) {
                Diag.log(appContext, "sound", "exo: звук не начался — говорю фразу напрямую")
                // 30.09.2026: заминка — в память окна «Не засыпать» (StallLog).
                StallLog.record(appContext, "фраза не зазвучала за ${PLAY_STALL_MS / 1000} с")
                fallbackDirect(text, currentPos, currentPart)
            }
        }, PLAY_STALL_MS)
    }

    /** Сторож «звука нет, а читать должны».
     *
     *  30.09.2026, журнал 00:47:29 (жалоба Сержа «остановилось чтение»): после
     *  ошибки файла список плеера оставался мёртвым — в нём шесть фраз, часть уже
     *  удалена, — и новые в него не дописывались: очередь заготовок ждала места
     *  (см. [exoTopUp]), места не появлялось, «фраза доиграла» не приходила.
     *  Снаружи это вечная тишина, а приложение считает, что читает («power:
     *  бьюсь: чтение идёт»). Сторож взводится на каждое обращение чтения и
     *  снимается, когда фраза зазвучала: если за [SOUND_STALL_MS] ни одна не
     *  началась, а фразы есть — выбрасываем список и играем следующую готовую
     *  (или собираем заново). Пока идёт синтез, сторож молчит: это нормальное
     *  ожидание, а не тупик. */
    private fun armSoundWatch() {
        val token = ++soundWatchToken
        main.postDelayed({
            if (token != soundWatchToken) return@postDelayed
            if (exoFilePlayingSafe()) {
                armSoundWatch()
                return@postDelayed
            }
            if (pending.values.any { it.kind == Pending.Kind.FILE }) {
                // Синтез в работе — ждём его, тупика нет.
                armSoundWatch()
                return@postDelayed
            }
            val next = readyQueue.firstOrNull()
            if (next == null && exoPending.isEmpty()) {
                // Просить нечего: чтение встало или на паузе — сторож не нужен.
                return@postDelayed
            }
            Diag.log(
                appContext, "sound",
                "звука нет ${SOUND_STALL_MS / 1000} с, а фразы есть (готовых ${readyQueue.size}, " +
                    "в списке плеера ${exoPending.size}) — выбрасываю список и играю дальше"
            )
            // 30.09.2026: самая честная заминка «читаем, а звука нет» — в память
            // окна «Не засыпать» (StallLog): по ней видно, часто ли это вообще.
            StallLog.record(appContext, "звука не было ${SOUND_STALL_MS / 1000} с, хотя фразы были")
            exoClearAll()
            if (next != null) {
                readyQueue.removeFirst()
                awaitingPlayText = null
                exoPlay(next.text, next.file, next.rate, 0L, next.pos, next.part)
            } else {
                val t = awaitingPlayText ?: currentText
                if (!t.isNullOrBlank()) {
                    val tPos = if (t == awaitingPlayText) awaitingPos else currentPos
                    val tPart = if (t == awaitingPlayText && awaitingPart >= 0) awaitingPart else currentPart
                    awaitingPlayText = t
                    awaitingPos = tPos
                    awaitingPart = tPart
                    synthToFile(t, tPos, tPart)
                }
            }
            armSoundWatch()
        }, SOUND_STALL_MS)
    }

    /** Снять сторож звука: фраза зазвучала или чтение встало. */
    private fun dropSoundWatch() {
        soundWatchToken++
    }

    private fun exoFilePlayingSafe(): Boolean = runCatching { filePlayer.isPlaying }.getOrDefault(false)

    /** Что сообщает плеер: «фраза доиграла» двигает чтение, ошибка уходит в
     *  прямую речь. */
    private val exoListener = object : FilePlayback.Listener {
        override fun onPhraseStart(index: Int, item: FilePlayback.Item) {
            exoStartToken++ // звук пошёл — сторож старта больше не нужен
            dropSoundWatch() // и сторож «звука нет» тоже: фраза зазвучала
            playingText = item.text
            playingFile = item.file
            // Громкость у реплик своя: файл мог прийти от второго движка.
            filePlayer.setVolume(volumeFor(item.file))
            // Темп у каждой фразы свой: файл сделан на [Prepared.rate], а звучать
            // должен на нынешней скорости ползунка (см. [exoSyncSpeed]). Заодно
            // запоминаем темп САМОГО ФАЙЛА: пауза по нему проверяет, годится ли
            // сохранённый звук для продолжения (см. [pauseKeepingPhrase]).
            //
            // 29.09.2026 (журнал 21:49, жалоба Сержа «фраза повторилась»): раньше
            // playingRate выставлялся только в [exoPlay], то есть у фраз, которыми
            // список НАЧИНАЛИ. Фразы, доигранные из очереди, оставляли чужой темп —
            // и пауза, сравнив его с нужным, решала, что сохранённый звук «прежней
            // скорости», выбрасывала файл. Продолжение синтезировалось заново и
            // звучало С НАЧАЛА: на слух это тот самый повтор.
            exoPending.firstOrNull { it.file.name == item.file.name }?.let { p ->
                playingRate = p.rate
                playingPos = p.pos
                playingPart = p.part
                playingKey = p.key
                exoSyncSpeed(p)
            }
            // Фраза новая — позиция у неё своя: сторож взводим заново.
            armExoPositionWatch()
        }

        override fun onPhraseEnd(index: Int, item: FilePlayback.Item) {
            if (exoAhead > 0) exoAhead--
            // Звук этой фразы ищем в зеркале ДО того, как оно сдвинется: из него
            // берём скорость, роль и позицию для кэша сыгранных (07.10.2026).
            val done = exoPending.firstOrNull { it.file.name == item.file.name }
            // Фраза ушла из зеркала: она больше не «впереди».
            // 23.10.2026: снимаем по имени ФАЙЛА, а не по тексту. Имя файла
            // уникально, а тексты в книге повторяются («— Да.»), и прежняя сверка
            // по тексту снимала не тот элемент зеркала — все следующие pos/part
            // съезжали, и порядок разъезжался (см. [expectedNextKey]).
            val at = exoPending.indexOfFirst { it.file.name == item.file.name }
            if (at >= 0) exoPending.removeAt(at)
            dropExoPositionWatch() // фраза кончилась — сторожить её позицию больше нечего
            // 08.10.2026: какая ЕДИНИЦА речи доиграла — по ключу, а не по тексту.
            // Это же число уходит чтению: по нему оно решает, можно ли двигать
            // место в книге (см. [reportDone] и `ReaderEngine.onPlayerDone`).
            val dPos = done?.pos ?: -1L
            val dPart = done?.part ?: -1
            val dLast = lastOfPhrase(dPos, dPart)
            Diag.log(
                appContext, "sound",
                "фраза доиграла: ${item.file.name} «${FilePlayback.brief(item.text)}»" +
                    (if (dPos >= 0) " [${Units.label(dPos, dPart)}${if (dLast) ", последний кусок" else ""}]" else ""),
            )
            // 07.10.2026: было `item.file.delete()` — и «повторить фразу» стоило
            // нового синтеза. Теперь звук последних фраз ждёт в кэше (см.
            // [playedCache]); лишнее из кэша удаляется там же.
            if (done != null) {
                rememberPlayed(done.text, item.file, done.rate, done.role, done.pos, done.part)
                noteUnitPlayed(done.pos, done.part)
            } else {
                runCatching { item.file.delete() }
            }
            playingText = null
            playingPos = -1L
            playingPart = 0
            playingKey = -1L
            playingFile = null
            rescueText = null
            rescueTries = 0
            retriesInRow = 0
            // Порядок как в прежнем пути: сперва наполняем очередь, потом двигаем
            // чтение — иначе оно попросит фразу, которой ещё нет.
            requestPrefetch()
            exoTopUp()
            reportDone(dPos, dPart, dLast)
        }

        override fun onAllEnded() {
            Diag.log(appContext, "sound", "exo: список кончился — жду следующую фразу")
            // 29.09.2026: подстраховка от вечного молчания. Если «фраза доиграла»
            // по списку не пришла (в 190 так и вышло — слушателя забыли поставить),
            // здесь сами считаем фразу законченной: двигаем чтение и заказываем
            // заготовки. Молчание навсегда недопустимо.
            if (playingText != null) {
                Diag.log(appContext, "sound", "exo: конца фразы не дождались — двигаю чтение сам")
                playingText = null
                playingFile = null
                exoPending.clear()
                exoAhead = 0
                requestPrefetch()
                exoTopUp()
                reportDone()
            }
        }

        override fun onError(item: FilePlayback.Item?, message: String) {
            val text = item?.text ?: currentText
            item?.file?.delete()
            Diag.log(
                appContext, "sound",
                "exo: файл не заиграл ($message) — чищу список и собираю фразу заново «${FilePlayback.brief(text ?: "")}»"
            )
            // 30.09.2026 (журнал 00:47:29, жалоба Сержа «остановилось чтение»):
            // прежде здесь произносили фразу НАПРЯМУЮ движком, а список плеера
            // оставляли как был — с уже удалёнными файлами. Дальше очередь
            // заготовок ждала в нём места, места не появлялось, «фраза доиграла»
            // не приходила, и чтение замолкало насовсем. Плюс та прямая речь идёт
            // своим уровнем и звучит громче выровненных файлов — Серж услышал это
            // как «громкость скакнула вверх». Теперь чистим состояние плеера
            // целиком и собираем ту же фразу заново — обычным путём, через файл.
            exoClearAll()
            if (text.isNullOrBlank()) {
                reportDone()
                return
            }
            awaitingPlayText = text
            awaitingPos = currentPos
            awaitingPart = currentPart
            synthToFile(text, currentPos, currentPart)
            armExoStartWatch(text)
            armSoundWatch()
        }
    }

    /** Сыграть готовый файл заявки [p].
     *
     *  23.10.2026, рефакторинг: играем ровно ТУ единицу речи, за которую пришёл
     *  файл, — с её местом и куском ([Pending.key]). Раньше здесь брались
     *  глобальные `currentText`/`currentPos`/`currentPart`, то есть «та фраза, что
     *  чтение попросило последней». Пока фраза синтезировалась, чтение могло
     *  уйти вперёд или назад — и в зеркало списка плеера ([exoPending]) вставал
     *  НЕВЕРНЫЙ ключ. Дальше проверка порядка ([expectedNextKey]) считала от
     *  чужого места, правильно стоящая заготовка уходила в `HELD`, и текст мог
     *  прозвучать второй раз. Скорость файла тоже берём из заявки: по ней пауза
     *  не выдаст прежний темп за нынешний (см. [pauseKeepingPhrase]). */
    private fun playFile(p: Pending) {
        val f = p.file ?: return
        // Звук пошёл — движок отвечает, счётчик молчащих фраз обнуляем
        // (см. [noteSilentPhrase]).
        silentInRow = 0
        silentFromPos = -1L
        exoPlay(p.text, f, p.rate, 0L, p.pos, p.part)
    }

    /** Выбросить всё, что заготовлено впрок (msg5604). Зовётся, когда на ходу
     *  сменили голос или движок: заготовки сделаны ПРЕЖНИМ голосом, и пока они
     *  не отыграют (до трёх в очереди), новый голос не слышен вовсе. Заодно
     *  снимаем метку «синтез идёт»: файл, который доспеет после смены, уже
     *  осиротеет и будет удалён — он тоже прежним голосом. Текущий звук не
     *  трогаем: его перечитает читалка ([ReaderEngine] restartAfterSwitch). */
    fun dropPrepared() {
        awaitingPlayText = null
        awaitingPart = -1
        prewarmOnly = false
        previewOnly = false
        // 08.10.2026: счётчик кусков начинаем заново — после смены голоса та же
        // фраза читается с начала, а не «с первого куска» (см. [speak]).
        lastAskedPos = -1L
        lastAskedPart = -1
        directAskedAt.clear()
        ackSilentInRow = 0
        // 08.10.2026: голос сменился — прежний проход кончился, и та же фраза
        // новым голосом обязана прозвучать (её перечитает читалка).
        playedKeys.clear()
        lastPlayedPos = -1L
        lastPlayedPart = -1
        // Голос сменился — сохранённый паузой звук сделан прежним.
        keptPhrase?.let { runCatching { it.file.delete() } }
        keptPhrase = null
        // 07.10.2026: и кэш сыгранных фраз тоже прежним голосом — новый голос
        // должен звучать, а не подхватывать старый звук из кэша.
        clearPlayedCache()
        clearPrefetch()
        // 29.09.2026 (журнал 18:04, «смена голоса на ходу»): в новом пути заготовки
        // лежат в списке плеера, и без этой чистки после смены голоса продолжали
        // звучать файлы ПРЕЖНЕГО голоса — Серж описал это как «переключаю, а он
        // читает старым». Список чистим целиком, вместе со звучащей фразой: её
        // чтение перечитает уже новым голосом ([restartAfterSwitch]).
        exoClearAll()
        // 05.10.2026: в ПРЯМОМ чтении файлов нет вовсе, и чистка списка плеера
        // ничего не даёт: звук идёт из очереди САМОГО движка, и она продолжала
        // играть прежним голосом (см. [cutDirectNow]). А в ФАЙЛОВОМ пути мы до
        // сих пор не гасили очередь движка: журнал Сержа 16:49 — за миг до смены
        // голоса «заказал заготовок: 3, в работе 4», то есть четыре тяжёлых
        // синтеза прежним голосом продолжали занимать движок, пока мы просили у
        // него новый. Первый синтез нового голоса от этой давки замедлялся.
        if (directMode) {
            cutDirectNow("смена голоса на ходу")
        } else {
            // Заявки прежнего голоса закрываем САМИ, до stop(). Среди них есть и
            // заявка на звучащую фразу — та, что чтение сейчас перечитает: если
            // оставить её живой, движок ответит на неё (файлом или ошибкой), а мы
            // примем ответ за судьбу НОВОЙ заявки того же текста — сыграем фразу
            // прежним голосом или зря уйдём в прямую речь (см. [synthFinished] и
            // [synthFailed]).
            // 05.10.2026: сюда же попадает фраза холодного старта — она тоже
            // звучит прежним голосом, и её «доиграла» не должна сдвинуть чтение
            // после смены.
            val stale = pending.values.count {
                !it.cancelled && (it.kind == Pending.Kind.FILE || it.kind == Pending.Kind.DIRECT)
            }
            pending.entries.removeAll { (_, p) ->
                if (!p.cancelled && (p.kind == Pending.Kind.FILE || p.kind == Pending.Kind.DIRECT)) {
                    p.cancelled = true
                    runCatching { p.file?.delete() }
                    true
                } else {
                    false
                }
            }
            directSpeakingText = null
            directSpeakingPos = -1L
            directSpeakingPart = 0
            runCatching { tts?.stop() }
            runCatching { replyTts?.stop() }
            Diag.log(
                appContext, "tts",
                "смена голоса на ходу: заявок прежним голосом было $stale — очередь движка погашена"
            )
        }
    }

    /** Оборвать прямую речь прямо сейчас: движок перестаёт говорить, его очередь
     *  и наши заявки выбрасываются (30.09.2026, сборка 228).
     *
     *  Зачем отдельно от [stop]. [stop] — это пауза: он ещё и отпускает плеер,
     *  снимает надзоры, чистит сохранённую паузой фразу. Здесь нужно ровно одно:
     *  чтобы движок замолчал и его очередь не доигрывала прежним голосом, пока
     *  читалка заказывает ту же фразу заново. */
    private fun cutDirectNow(reason: String) {
        if (!directMode) return
        val wasQueue = directQueue.size
        val wasSpeaking = directSpeakingText != null
        if (wasQueue == 0 && !wasSpeaking) return
        flushDirectQueue(reason)
        // Движок мог говорить и без нашей очереди (заявка уже доигрывала):
        // гасим его самого, очередь у него при этом выметается целиком.
        runCatching { tts?.stop() }
        runCatching { replyTts?.stop() }
        directSpeakingText = null
        directSpeakingPos = -1L
        directSpeakingPart = 0
        directAskedId = null
        Diag.log(
            appContext, "tts",
            "прямая речь оборвана ($reason): в очереди было $wasQueue, звучала=$wasSpeaking",
        )
    }

    /** Погасить список плеера целиком: ничего не остаётся ни звучать, ни ждать. */
    private fun exoClearAll() {
        exoPending.clear()
        exoAhead = 0
        playingText = null
        playingFile = null
        dropExoPositionWatch()
        exoStartToken++
        runCatching { filePlayer.stop() }
    }

    /** Чей голос сделал этот файл: репликовый или книжный. Файлы реплик мы и
     *  так помним по имени (см. [replyFiles]), а знать роль нужно затем, что от
     *  неё зависят и скорость заготовки, и громкость звука. */
    private fun roleOfFile(f: File): Pending.Role =
        if (f.name in replyFiles) Pending.Role.REPLY else Pending.Role.MAIN

    /** Собственный аудиоплеер не смог сыграть файл (редкий случай) — чтобы
     *  чтение не замолчало, произносим текст напрямую движком. На время этой
     *  фразы media-кнопки будут не наши; по её окончании чтение продолжается.
     *  23.10.2026: единицу называем с местом и куском — тогда её «доиграла»
     *  относится к своему месту в книге, а не «место неизвестно». */
    private fun fallbackDirect(text: String?, pos: Long = -1L, part: Int = 0) {
        if (text.isNullOrBlank()) return
        val t = tts
        if (t == null || !ready) {
            // Совсем ничего не вышло — пропускаем предложение, чтение не встаёт.
            reportDone(pos, part, lastOfPhrase(pos, part))
            return
        }
        val id = reqSeq++
        pending[id] = Pending(Pending.Kind.DIRECT, text, null, pos = pos, part = part)
        val r = runCatching { t.speak(Roles.stripped(text), TextToSpeech.QUEUE_FLUSH, null, id.toString()) }
            .getOrDefault(TextToSpeech.ERROR)
        if (r != TextToSpeech.SUCCESS) {
            pending.remove(id)
            reportDone(pos, part, lastOfPhrase(pos, part))
        } else {
            armDirectWatch(id)
        }
    }

    /** Отменить текущее проигрывание. onDone НЕ вызывается. */
    private fun releaseMedia() {
        dropSoundWatch() // чтение встало — сторож «звука нет» больше не нужен
        playingText = null
        playingFile = null
        // У ExoPlayer отпускаем его список целиком.
        exoStartToken++
        exoAhead = 0
        // 29.09.2026: зеркало тоже чистим. Иначе после паузы оно врало, что
        // фразы «ещё впереди в списке», и «продолжить» молчало (жалоба Сержа).
        exoPending.clear()
        dropExoPositionWatch()
        runCatching { filePlayer.stop() }
    }

    /** Пока играет текущее — спросить читалку, какие фразы будут следующими, и
     *  синтезировать их заранее, чтобы между фразами не было паузы.
     *
     *  msg4472: держим [prefetchDepth] фраз готовыми.
     *
     *  29.09.2026 (просьба Сержа: «можем ли мы три фразы одновременно
     *  синтезировать»): заявок в работе теперь столько, сколько мест в очереди
     *  ([maxInFlight]), а не одна. Заказываем сразу весь набор — движок сам
     *  решает, делать их подряд или параллельно; у сетевых голосов он умеет
     *  параллельно, и тогда три файла приходят за время одного. Раньше заказ
     *  уходил только после ответа на предыдущий, и очередь наполнялась по одной.
     *  У локального движка по-прежнему одна заявка за раз ([maxInFlight]). */
    private fun requestPrefetch() {
        if (directMode) return // заготовки не нужны: движок читает сам
        // Проба голоса (19.10.2026): звучит одна фраза, и впереди ей ничего не
        // нужно — иначе файлы будущих фраз уедут в список плеера и зазвучат
        // после пробы, когда чтение уже стоит (см. [previewOnly]).
        if (previewOnly) return
        if (awaitingPlayText != null) return // текущая фраза ещё не сыграна
        // 29.09.2026 (журнал 17:53): у ExoPlayer фразы из очереди заготовок уезжают
        // в список плеера ([exoTopUp]) и в очереди больше не числятся. В позицию
        // заказа их тоже надо считать: иначе читалку спрашивают про уже заказанные
        // фразы, она называет то, что в списке уже стоит, и каждый круг в журнале
        // «exo: такая фраза уже есть в списке — лишнюю не беру». Само чтение от
        // этого не рвётся, но очередь наполняется наполовину и бессмысленно.
        var issued = 0
        // 29.09.2026, НАЙДЕНО ПО ЖУРНАЛУ 10:24 («программа не отвечает» на смене
        // скорости): в условии стояло число заявок, снятое ДО цикла (`inFlight`),
        // а позиция считалась по живому набору. Как только очередь и набор пусты
        // (смена скорости их чистит — [dropStaleRate]), условие «0 + 0 + 0 < 3»
        // выполнялось ВЕЧНО, и цикл заказывал синтез фразы за фразой, пока читалка
        // не откажется называть следующую: в журнале это «позиция 126 из 3», то
        // есть 126 заявок в одном вызове. Дальше сверка конвейера обходила все
        // 126 заявок, и на КАЖДУЮ читалка считала фразу от текущего места (с
        // применением словаря) — квадратичная работа на главном потоке, движок
        // захлёбывался сотней заявок, окно переставало отвечать. Теперь условие
        // считает ЖИВЫЕ числа.
        //
        // 07.10.2026: запас считаем ДВУМЯ мерами — знаками ([aheadCharsTarget]) и
        // фразами ([aheadPhraseCap]). Знаки дают ровный запас звука (короткая
        // фраза больше не оставляет стык голодным), потолок в фразах не даёт
        // очереди разрастись на книге из коротких предложений. Куски одной фразы
        // считаются один раз — по позиции (см. [phrasesAhead]).
        while (phrasesAhead() < aheadPhraseCap() && aheadCharsAhead() < aheadCharsTarget()) {
            if (issued >= aheadPhraseCap() + maxInFlight) break // страховка: больше потолка не заказываем
            // 05.10.2026: offset считаем по ФРАЗАМ, а не по кускам. У фразы с
            // прямой речью кусков два и больше (слова автора и реплики), и все
            // они занимают ОДНУ позицию книги — иначе двухкусковая фраза
            // сдвигала бы отсчёт и читалка называла бы фразу через одну.
            val offset = phrasesAhead() + 1
            // 29.09.2026: в журнал — почему очередь НЕ растёт. Жалоба Сержа: с
            // сетевым синтезатором паузы стали меньше, но остались; в журнале
            // видно, что каждая заготовка встаёт «в очереди 1/3», то есть цепочка
            // обрывается, а по чему — из журнала не понять. Причина называется
            // словами, и повод пишется один раз на вид (не спамим).
            val frags = onNeedNext?.invoke(offset) ?: return logPrefetchSkip(offset, "чтение не назвало фразу")
            if (frags.isEmpty()) return logPrefetchSkip(offset, "фраза пустая")
            // 08.10.2026: чтение называет куски фразы вместе с их номерами —
            // запоминаем, сколько кусков у фразы: по этому числу считается, какая
            // единица речи обязана звучать следующей (см. [expectedAfter]).
            frags.map { it.second }.distinct().forEach { p ->
                registerParts(p, frags.count { it.second == p })
            }
            var progressed = false
            for ((nextText, nextPos, nextPart) in frags) {
                if (nextText.isBlank()) continue
                // 23.10.2026: сверки только по КЛЮЧУ единицы речи (место + кусок).
                // Сверка `nextText == currentText` выброшена: она считала «уже
                // читается» всякую фразу с тем же текстом из другого места книги
                // («— Да.» в диалоге), и такая фраза не заказывалась вовсе.
                val nextKey = Units.key(nextPos, nextPart)
                if (nextKey >= 0 && nextKey == Units.key(currentPos, currentPart)) continue
                if (readyQueue.any { it.key == nextKey }) continue
                if (exoPending.any { it.key == nextKey }) continue
                if (fileInFlight(nextKey) != null) continue
                synthToFile(nextText, nextPos, nextPart, prefetch = true)
                issued++
                progressed = true
            }
            if (!progressed) return logPrefetchSkip(offset, "фраза уже заказана")
        }
        // 29.09.2026: в журнал — сколько заявок ушло движку разом. По этой строке
        // видно и глубину конвейера, и то, делает ли движок их параллельно:
        // если три файла приходят почти одновременно — параллельно, если по
        // очереди с равными промежутками — значит он их сериализует.
        if (issued > 0) {
            Diag.log(
                appContext, "sound",
                "заказал заготовок: $issued (в работе ${fileInFlightCount()} из $maxInFlight; " +
                    "впереди ${aheadCharsAhead()} знаков из ${aheadCharsTarget()}, " +
                    "фраз ${phrasesAhead()} из ${aheadPhraseCap()})"
            )
        }
    }

    /** Почему заготовка вперёд не заказана — в журнал (29.09.2026). Пишем по
     *  разу на повод: чтение идёт минутами, и повторять одну и ту же строку
     *  каждый раз незачем. */
    private val prefetchSkipsLogged = HashSet<String>()

    private fun logPrefetchSkip(offset: Int, why: String) {
        if (!prefetchSkipsLogged.add(why)) return
        Diag.log(
            appContext, "sound",
            "заготовку вперёд не заказываю (позиция $offset; впереди " +
                "${aheadCharsAhead()} знаков из ${aheadCharsTarget()}, фраз " +
                "${phrasesAhead()} из ${aheadPhraseCap()}): $why"
        )
    }

    /** Полностью обнулить состояние пайплайна (без остановки TTS). */
    private fun resetPipeline() {
        forgetAllSynthWatches()
        directWatchToken++
        awaitingPlayText = null
        // 08.10.2026: и счётчик кусков фразы тоже с нуля (см. [speak]).
        lastAskedPos = -1L
        lastAskedPart = -1
        directAskedAt.clear()
        ackSilentInRow = 0
        prewarmOnly = false
        synthMisses.clear()
        firstPrepFromMs = 0L // засечка «сколько готовит первую фразу» — см. [noteFirstPrep]
        directQueue.clear()
        directWaitReply = false
        directAskedId = null
        directSpeakingText = null
        directSpeakingPos = -1L
        directSpeakingPart = 0
        currentRest = emptyList()
        lastDirectQueuedId = null
        forgetReplyWait()
        clearPrefetch()
        releaseMedia()
        currentText = null
        // 08.10.2026: проход начинается заново — прозвучавшее снова может звучать
        // (прыжок, смена голоса или движка, перезапуск). Порядок и «уже звучало»
        // считаем от нового места.
        playedKeys.clear()
        lastPlayedPos = -1L
        lastPlayedPart = -1
    }

    private fun clearPrefetch() {
        readyQueue.forEach { runCatching { it.file.delete() } }
        readyQueue.clear()
        // Заявки, которые ещё в пути, тоже снимаем: иначе их файлы приедут
        // позже и попадут в очередь как заготовки для фраз, которых чтение уже
        // не ждёт (при нескольких заявках в работе это стало заметнее).
        // 23.10.2026: «впрок» — признак самой заявки ([Pending.prefetch]);
        // по тексту больше не сверяем, одинаковые фразы путались.
        pending.entries.removeAll { (_, p) ->
            if (p.kind == Pending.Kind.FILE && p.prefetch && !p.cancelled) {
                p.cancelled = true
                runCatching { p.file?.delete() }
                true
            } else {
                false
            }
        }
    }

    // ---------- Первая фраза заранее и пауза без повторного синтеза ----------
    // (24.09.2026, просьба Сергея: «чтение начиналось бы быстрее»)

    /** Приготовить звук фразы, с которой начнётся чтение, ДО нажатия «читать».
     *
     *  Зачем. Единственная задержка перед первым звуком — синтез первой фразы:
     *  по журналу Сергея это 0,54 с на фразу в 10,6 с речи (движок берёт
     *  40–50 мс на секунду звука), плюс 0,03 с на запуск нашего плеера. Отсюда
     *  и 0,58 с между «читать» и звуком; убрать их можно только тем, что файл
     *  готов заранее — окно читалки открывается на нужном месте за секунды до
     *  нажатия. Это ровно та же заготовка, что и во время чтения, только
     *  заказанная раньше.
     *
     *  Готовим ОДНУ фразу ([prewarmOnly]) и только когда ничего не читается:
     *  очередь впрок без звука — это лишняя работа процессора. Не пригодилась
     *  (прыжок, другая книга, чтение так и не начали) — файл осиротеет и будет
     *  удалён, как любая незапрошенная заготовка. */
    fun prewarm(text: String, pos: Long = -1L) {
        if (directMode || text.isBlank()) return
        // 06.10.2026 (журнал 21:38, жалоба Сержа «открыл книжку — она начала
        // автоматически читаться, хотя авточтение выключено»). Виновата именно
        // заготовка первой фразы: у движка-прослойки (MultiTTSLexx) заявка «сделай
        // файл» означает «прочитай вслух» — он играет звук САМ, а нам не отдаёт
        // ничего. Мы готовили первую фразу заранее, ещё до начала чтения, и в
        // журнале это видно: 21:38:18.732 «готовлю первую фразу заранее (185
        // знаков)» → 21:38:18.744 «onStart: движок начал речь (0)». Чтение при
        // этом стояло (старт был только в 21:38:23.8, по кнопке).
        //
        // Поэтому у движка, у которого ХОТЬ ОДИН голос уже попал в пометку
        // «файлов не отдаёт», заготовку впрок не делаем вовсе: знаем, что он
        // заговорит сам. Пометка пары тут не спасает: она хранится на «движок +
        // голос», а у прослойки наш голос не выбран (в журнале «голос
        // движковый»), и прежняя пометка на другой голос не совпала.
        val failed = engineFileFailVoices()
        if (failed >= 1) {
            Diag.log(
                appContext, "sound",
                "заготовку первой фразы не делаю: у движка уже $failed голос(а) без " +
                    "файлов — он заговорит сам, и это было бы слышно до начала чтения"
            )
            return
        }
        val t = tts
        if (t == null || !ready) return
        if (currentText != null || awaitingPlayText != null || soundPlaying()) return
        // 23.10.2026: «уже заказана» — сверка по КЛЮЧУ единицы речи.
        val key = Units.key(pos, 0)
        if (fileInFlightAny(pos, 0, text) != null) return
        // Роль этой фразы знаем так же, как её узнает synthToFile: реплика —
        // значит своя скорость, и «уже готово» надо сверять с ней же.
        val role = if (replyOn && !replyBroken && Roles.looksReplica(text)) {
            Pending.Role.REPLY
        } else {
            Pending.Role.MAIN
        }
        // Куски этой фразы в очереди — сверяем по ключу (0), текст не опознание.
        if (readyQueue.any { it.key == key && it.rate == rateFor(role) }) return
        if (keptPhrase?.key == key && keptPhrase?.rate == rateFor(role)) return
        clearPrefetch()
        prewarmOnly = true
        Diag.log(appContext, "sound", "готовлю первую фразу заранее (${text.length} знаков)")
        synthToFile(text, pos, 0, prefetch = true)
    }

    /** Заказать остальные куски ТЕКУЩЕЙ фразы (реплики после слов автора) сразу,
     *  не дожидаясь, пока первый кусок доиграет.
     *
     *  05.10.2026, жалоба «второй синтезатор не читает прямую речь, фраза
     *  пропускается»: реплику заказывал только [ReaderEngine.onUtteranceDone],
     *  когда авторский кусок УЖЕ доиграл. К этому времени упреждающий синтез уже
     *  заготовил следующие фразы книги, и реплика вставала в КОНЕЦ очереди — после
     *  них, а не сразу за своим авторским куском. Отсюда прямая речь либо звучала
     *  не на месте, либо (если читатель ставил паузу) не звучала вовсе. Здесь
     *  реплика заказывается в тот же миг, что и авторский кусок, — её номер
     *  заявки оказывается сразу за ним, и [addReadyInOrder] ставит её на место.
     *  Куски, которые уже заказаны или стоят в очереди, повторно не трогаем.
     *
     *  08.10.2026: куски нумеруются (см. [Units.key]) — первый здесь получает
     *  номер 1, потому что нулевой (сама фраза) уже отдан в [speak]. Без номера
     *  хвост фразы неотличим от следующего предложения, и порядок звука ехал.
     *
     *  23.10.2026. Два правила. (1) Сверки — только по КЛЮЧУ: `rest == currentText`
     *  выброшена, она выкидывала кусок, дословно совпадающий с головой фразы.
     *  (2) В ПРЯМОМ пути куски текущей фразы тоже заказываются заранее — раньше
     *  прямой путь их не заказывал, и первый кусок по завершении вызывал
     *  `flushDirectQueue` (`tts.stop()`) посреди уже начавшейся следующей фразы:
     *  на слух — фраза обрывается и начинается заново. Обычно здесь ничего не
     *  заказывается: их уже отдал [speak] вместе с головой. */
    fun prefetchRest(fragments: List<String>, pos: Long) {
        var part = if (pos >= 0 && pos == lastAskedPos) lastAskedPart + 1 else 1
        if (directMode) {
            for (rest in fragments) {
                registerParts(pos, part + 1)
                if (rest.isBlank()) {
                    part++
                    continue
                }
                val key = Units.key(pos, part)
                if (directQueue.any { pending[it]?.key == key }) {
                    part++
                    continue
                }
                // Порядок очереди движка — это порядок звука: дописывать можно
                // только в КОНЕЦ. Если за хвостом очереди уже стоят единицы
                // ДАЛЬШЕ этой, дописывать нельзя — кусок прозвучал бы не на своём
                // месте. Такой кусок закажет чтение, когда дойдёт до него.
                val tailKey = directQueue.lastOrNull()?.let { pending[it]?.key } ?: -1L
                if (tailKey > key) {
                    Diag.log(
                        appContext, "sound",
                        "кусок ${Units.label(pos, part)} не дописываю: очередь движка уже ушла вперёд"
                    )
                    return
                }
                if (!queueDirect(rest, pos, part)) return
                part++
            }
            if (fragments.isNotEmpty()) registerParts(pos, part)
            topUpDirectQueue()
            return
        }
        for (rest in fragments) {
            registerParts(pos, part + 1)
            if (rest.isBlank()) {
                part++
                continue
            }
            val key = Units.key(pos, part)
            if (readyQueue.any { it.key == key }) {
                part++
                continue
            }
            if (exoPending.any { it.key == key }) {
                part++
                continue
            }
            if (fileInFlight(key) != null) {
                part++
                continue
            }
            synthToFile(rest, pos, part, prefetch = true)
            part++
        }
    }

    /** Пауза с сохранением звука звучащей фразы: продолжение зазвучит сразу.
     *
     *  В паузе файл звучащей фразы никуда не девается — его удаляют только конец
     *  фразы или ошибка. А продолжение начинается с ТОЙ ЖЕ фразы (позицию
     *  читалка держит по предложениям и на паузе сохраняет её начало), поэтому
     *  его можно сыграть из того же файла, не заказывая синтез заново: по
     *  журналу это те же 0,5 с на фразу в десять секунд речи.
     *
     *  Скорость держим рядом с файлом: сменили её на паузе — файл прежнего
     *  темпа не играем (см. [takeKeptPhrase]).
     *
     *  Порядок важен: сначала [stop] (он чистит очередь, надзоры и заявки),
     *  потом ставим сохранённую фразу — иначе stop() снёс бы её как старую. */
    fun pauseKeepingPhrase() {
        val text = playingText
        val file = playingFile
        val rate = playingRate
        // У ExoPlayer позиция точная — запоминаем её, чтобы продолжение пошло с
        // середины фразы, а не с её начала.
        val pos = runCatching { filePlayer.positionMs }.getOrDefault(0L)
        stop()
        if (text != null && file != null && file.exists() && rate == rateFor(roleOfFile(file))) {
            keptPhrase = Prepared(text, file, rate, roleOfFile(file), pos = playingPos)
            keptPositionMs = pos
            Diag.log(
                appContext, "sound",
                "пауза: звук фразы сохранён (${file.name}, ${file.length()} байт) — продолжение зазвучит сразу"
            )
        } else {
            file?.delete() // продолжать не с чего — файл не копим
        }
    }

    /** Взять фразу, сохранённую паузой. Пригодилась — отдаём файл, играть его
     *  будет наш плеер. Не та фраза, сменившаяся скорость или пропавший файл —
     *  выбрасываем и читаем как обычно. */
    private fun takeKeptPhrase(text: String, pos: Long, part: Int): Prepared? {
        val kept = keptPhrase ?: return null
        keptPhrase = null
        val sameUnit = kept.text == text && kept.pos == pos &&
            (part < 0 || kept.part == part)
        if (sameUnit && kept.rate == rateFor(kept.role) && kept.file.exists()) {
            Diag.log(appContext, "sound", "продолжаю с сохранённого звука (${kept.file.name})")
            return kept
        }
        if (sameUnit) {
            Diag.log(
                appContext, "sound",
                "сохранённый звук сделан на скорости ${RateSteps.label(kept.rate)}, " +
                    "сейчас ${RateSteps.label(speed)} — синтезирую заново"
            )
        }
        kept.file.delete()
        return null
    }

    /** Фраза доиграла — кладём её звук в кэш сыгранных вместо удаления (см.
     *  [playedCache]). Файл стёрли не мы (ошибка, чужая чистка) — просто
     *  забываем о нём. */
    private fun rememberPlayed(
        text: String,
        f: File,
        rate: Float,
        role: Pending.Role,
        pos: Long,
        part: Int,
    ) {
        if (directMode || rate <= 0f || !f.exists() || f.length() <= 0L) {
            runCatching { f.delete() }
            return
        }
        playedCache.removeAll { it.file.name == f.name }
        playedCache.addLast(Prepared(text, f, rate, role, pos = pos, part = part))
        while (playedCache.size > PLAYED_CACHE_MAX) {
            runCatching { playedCache.removeFirst().file.delete() }
        }
    }

    /** Фраза уже звучала недавно — её звук лежит в кэше сыгранных. Отдаём файл,
     *  если он цел и сделан нынешней скоростью этой роли; иначе выбрасываем и
     *  читаем как обычно (как [takeKeptPhrase] для паузы).
     *
     *  08.10.2026: ищем по КЛЮЧУ единицы речи — у фразы бывает несколько кусков
     *  с одной позицией, и по тексту с позицией они неразличимы. */
    private fun takePlayed(text: String, pos: Long, part: Int): Prepared? {
        val key = Units.key(pos, part)
        val at = playedCache.indexOfFirst {
            if (key >= 0) it.key == key else it.text == text && it.pos == pos
        }
        if (at < 0) return null
        val done = playedCache.removeAt(at)
        if (!done.file.exists() || done.rate != rateFor(done.role)) {
            runCatching { done.file.delete() }
            return null
        }
        Diag.log(
            appContext, "sound",
            "играю из кэша сыгранных (${done.file.name}, ${done.file.length()} байт) «${FilePlayback.brief(text)}»"
        )
        return done
    }

    /** Забыть кэш сыгранных фраз со стиранием файлов: голос, движок или скорость
     *  сменились — прежний звук для новых фраз не годится. */
    private fun clearPlayedCache() {
        playedCache.forEach { runCatching { it.file.delete() } }
        playedCache.clear()
    }

    /** Выбросить заготовки, сделанные прежней скоростью ([speed]). Текущий звук
     *  не трогаем: он уже звучит. Фразу в работе ([awaitingPlayText]) тоже не
     *  снимаем — её судьбу решит [synthFinished] по скорости самого файла. */
    private fun dropStaleRate() {
        prewarmOnly = false
        clearPrefetch()
        // 29.09.2026 (журнал 18:02, «покрутил всё»): в новом пути заготовки уезжают
        // в СПИСОК ПЛЕЕРА, и чистка очереди их не задевала. После смены скорости
        // там оставались файлы прежней скорости — они и звучали, а свежий файл на
        // тот же текст отбрасывался как «такая фраза уже есть в списке» (в журнале
        // это рядом: «синтез готов ... скорость 2.4» и «лишнюю не беру»). Хвост
        // списка убираем; звучащую фразу не трогаем — она дотягивается отношением
        // в [exoSyncSpeed].
        exoDropTail()
        keptPhrase?.let { runCatching { it.file.delete() } }
        keptPhrase = null
        // 07.10.2026: кэш сыгранных фраз сделан прежней скоростью — он тоже
        // устарел. Сверка скорости в [takePlayed] это поймала бы, но файлы тогда
        // просто лежали бы мёртвым грузом до вытеснения.
        clearPlayedCache()
    }

    fun shutdown() {
        onDone = null
        onNeedNext = null
        onNeedAfter = null
        // 07.10.2026: звук сыгранных фраз стираем сразу, не дожидаясь удаления
        // каталога: вдруг каталог уцелеет (чужой экземпляр, отказ диска).
        clearPlayedCache()
        stop()
        Diag.log(appContext, "tts", "закрываю плеер: ${replyCountersLine()}")
        dropReplyEngine()
        // 30.09.2026: усилитель прямого звука — отпускаем вместе с плеером.
        runCatching { boostEffect?.release() }
        boostEffect = null
        runCatching { tts?.shutdown() }
        tts = null
        ready = false
        // Чистим ТОЛЬКО свой каталог: общий вычищал бы заготовки соседнего
        // экземпляра (например, читалки, если закрывается пробный плеер настроек).
        runCatching { synthDir.deleteRecursively() }
    }

    companion object {
        /** Номер экземпляра: по нему у каждого свой каталог временных файлов
         *  (см. [synthDir]). 30.09.2026 — чтобы временный плеер настроек не мог
         *  вычистить заготовки читалки. */
        private val instanceSeq = java.util.concurrent.atomic.AtomicInteger(0)

        /** Сколько фраз помнить для проверки «движок слушает нашу скорость»
         *  (см. [noteRateIgnored]). Больше не нужно: пара находится на соседних
         *  заявках одной и той же фразы. */
        private const val RATE_MEMO_MAX = 16

        /** Сколько последних СЫГРАННЫХ фраз держим готовыми (07.10.2026, кэш
         *  «повторить/шаг назад»): см. [playedCache]. Три — потому что повторов
         *  подряд бывает два-три, а каждый файл это до ~1 МБ. */
        private const val PLAYED_CACHE_MAX = 3

        /** Сколько фраз подряд движок может «прочитать» без признаков речи,
         *  прежде чем чтение встанет и скажет об этом (см. [ackLooksSilent]).
         *  08.10.2026, движок-прослойка тестера: отвечал «готово» мгновенно, и
         *  чтение уходило вперёд на десятки предложений. */
        private const val ACK_SILENT_STOP = 5

        /** Проверка «сломанный движок» (24.10.2026): через сколько миллисекунд
         *  после заказа фразы рапортуем «готово», не отдавая её движку. Мгновенно
         *  (ноль) не годится: настоящий сломанный движок всё-таки тратит на ответ
         *  десятки миллисекунд, и защита должна видеть правдоподобный срок. */
        private const val BROKEN_ENGINE_ACK_MS = 25L

        /** Сколько строк про проверку «сломанный движок» писать в журнал за сессию. */
        private const val BROKEN_ENGINE_LOG_MAX = 12

        /** Фраза короче этого (значащих знаков) в счёт подозрительных не идёт: у
         *  коротких реплик расчётное время слишком мало, чтобы что-то утверждать. */
        private const val ACK_MIN_CHARS = 20

        /** Потолок придержки чтения: дальше ждать бессмысленно (см. [directAckHoldMs]). */
        private const val ACK_HOLD_MAX_MS = 20_000L

        /** Сколько миллисекунд занимает произнесение ОДНОГО знака у самого
         *  быстрого голоса при скорости 1.0 (см. [directImpossibleMs]). 4 мс на
         *  знак — это 250 знаков в секунду: заведомо быстрее любой речи, поэтому
         *  всё, что «отзвучало» раньше, — молчание. */
        private const val FASTEST_MS_PER_CHAR = 4f

        /** Нижняя граница того же пола: у коротких реплик расчёт по длине даёт
         *  единицы миллисекунд, а движку нужно время хотя бы начать фразу. */
        private const val FASTEST_FLOOR_MS = 60L

        /** Сколько раз за сессию пишем в журнал «отчитался быстрее, чем можно
         *  произнести» (см. [directAckHoldMs]): строки одинаковые, а спамить
         *  журнал нельзя — по нескольким подряд причина уже видна. */
        private const val ACK_FAST_LOG_MAX = 20

        /** Придержку короче этого в журнал не пишем: она ничего не объясняет
         *  (см. [synthFinished]). */
        private const val ACK_HOLD_LOG_MIN_MS = 50L

        /** Запас к замеру «сколько движок готовит первую фразу»: ждём столько же
         *  плюс эти секунды (07.10.2026, см. [warmWindow]). */
        private const val FIRST_PREP_MARGIN_MS = 3_000L

        /** Меньше этого замер не сохраняем: движок ответил сразу, мерить нечего
         *  (см. [noteFirstPrep]). */
        private const val FIRST_PREP_MIN_MS = 2_000L

        // 05.10.2026, упрощение (Серж: «не перемудрили ли мы с нагромождением
        // кучи правил»): сроки ожидания синтеза, прямой речи, прогрева голоса и
        // холодного старта переехали в таблицу [Timing] — два набора, локальный
        // движок и медленный (сетевой или помеченный медленным). Здесь остались
        // только числа, общие для обоих наборов.

        /** Срок сторожа, когда фразу ждёт чтение, А ЗВУКА НЕТ ВОВСЕ
         *  (29.09.2026, см. [synthFuseFor]). Жалоба Сержа: «смущает паузы, когда
         *  он замолчал тогда на 5 секунд». Обычная заявка доспевает за 0,2–0,5 с,
         *  а если её нет и полсекунды — человек уже слышит тишину, и ждать полный
         *  срок нечего. */
        private const val SYNTH_SILENT_MS = 2_500L

        /** Сколько раз спасаем фразу, которую движок не отдал (29.09.2026,
         *  просьба Сержа). Сетевому движку терять фразу нельзя: сначала
         *  пробуем синтез в файл ещё раз, потом прямую речь ещё раз, и только
         *  после этого пропускаем. У локальных движков поведение прежнее. */
        private const val RESCUE_TRIES = 2

        /** Сколько раз подряд движок должен не отдать фразу (переспрос и
         *  перезапуски не помогли), чтобы мы пометили его медленным. Второй раз,
         *  а не первый: локальный движок иногда теряет одну заявку, и перезапуск
         *  для него — рабочая мера, терять её из-за одного случая нельзя. */
        private const val SLOW_HITS_TO_MARK = 2

        /** Пометки «этот движок с этим голосом медленный» — их ставит
         *  [markSlowSynth] после [SLOW_HITS_TO_MARK] обрывов подряд. Хранятся
         *  набором строк в настройках чтения: набор переживает перезапуск
         *  приложения, а формат тот же, что у остальных настроек. */
        private const val KEY_SLOW_SYNTH = "slow_synth_marks"

        /** Пометки «этому движку с этим голосом файлы не заказывать»: файловый
         *  путь провалился дважды подряд, читаем голосом движка напрямую
         *  (см. [markNetDirect]). */
        private const val KEY_DIRECT_SYNTH = "direct_synth_marks"

        /** Сколько раз подряд движок должен не отдать файл, чтобы мы перестали
         *  заказывать их вовсе и перешли на прямую речь. Два, а не один: один
         *  промах случается у любого движка. */
        private const val DIRECT_MODE_HITS = 2

        /** Сколько ПУСТЫХ файлов подряд (заголовок без звука) должны прийти от
         *  одной пары «движок + голос», чтобы это сочли провалом файлового пути
         *  (06.10.2026, MultiTTSLexx: звук он играет сам, а в файл не пишет
         *  ничего). Два — как и [DIRECT_MODE_HITS]: у локального движка пустой
         *  файл случается и сам по себе, из-за одной случайности менять путь
         *  нельзя. */
        private const val EMPTY_SOUND_HITS = 2

        /** Сколько РАЗНЫХ сетевых голосов одного движка должны не отдать файл,
         *  чтобы считать бесполезной саму пробу файла для ВСЕХ его сетевых
         *  голосов (30.09.2026, сборка 227, см. [engineFileFailVoices]).
         *  Два — как и [DIRECT_MODE_HITS]: один промах бывает у любого движка, а
         *  два разных голоса сразу означают, что движок файлов не умеет вовсе
         *  (MultiTTS: ни один его сетевой голос файл не отдаёт, и каждый новый
         *  голос стоил 5 секунд тишины в начале чтения). */
        private const val ENGINE_NO_FILES_VOICES = 2

        /** Сколько сроков ожидания даём движку реплик, прежде чем бросить роли до
         *  конца сеанса (29.09.2026): один промах — это просто медленный сетевой
         *  голос, из-за него роли терять нельзя. */
        private const val REPLY_MISS_LIMIT = 1

        /** Через сколько пробуем поднять отказавший движок реплик заново
         *  (29.09.2026). Таймера нет: попытка идёт по делу, на очередной реплике. */
        private const val REPLY_RETRY_MS = 60_000L

        /** Сколько ждём, что звук начнётся, прежде чем сказать фразу напрямую.
         *  23.09.2026: было 12 с. Файл лежит на диске и готовится десятые доли
         *  секунды; если за пять секунд не заиграл — не заиграет, и выгоднее
         *  сразу перейти к прямой речи, чем держать тишину. */
        private const val PLAY_STALL_MS = 5_000L

        /** Сколько ждать звука, когда чтение попросило фразу (см. [armSoundWatch]).
         *  Больше, чем [PLAY_STALL_MS]: там речь о «не началось», а здесь — о полной
         *  тишине, и спешить некуда: самая длинная фраза синтезируется дольше. */
        private const val SOUND_STALL_MS = 8_000L

        /** Сторож замершей позиции у ExoPlayer: как часто проверяем и сколько
         *  проверок подряд должны увидеть одинаковую позицию, чтобы счесть фразу
         *  потерянной (2 с × 3 = 6 с). */
        private const val EXO_POS_STEP_MS = 2_000L
        private const val EXO_POS_STUCK_HITS = 3

        /** Сколько ждать тишины ползунка скорости, прежде чем перечитать текущую
         *  фразу в прямом чтении (см. [onDirectRateChanged]). Ползунок ходит по
         *  одной десятой, и на каждом шаге перечитывать фразу нельзя: она бы
         *  топталась на своём начале. Семьсот миллисекунд — человек успевает
         *  отпустить кнопку или перестать двигать ползунок. */
        private const val DIRECT_RATE_SETTLE_MS = 700L

    /** 24.10.2026: границы срока ожидания сетевого голоса. По умолчанию у @Voice
     *  15 с — и это ровно столько, сколько мы ждём сетевой голос, прежде чем
     *  считать, что он не ответил. Больше 60 с ждать бессмысленно: человек решит,
     *  что чтение встало. */
    private const val NET_TIMEOUT_MAX_MS = 60_000L

        /** Границы срока по длине фразы в прямом чтении: меньше шести секунд ждать
         *  нечего, а больше сорока пяти — уже ни к чему (наша фраза ≤220 знаков).
         *  Общие для обоих наборов [Timing]: у сетевого другие запас и хвост, а
         *  границы те же. */
        private const val DIRECT_MIN_MS = 6_000L
        private const val DIRECT_MAX_MS = 45_000L

        /** Сколько фраз подряд движок может НЕ дать звука, прежде чем мы поднимем
         *  его заново и вовсе встанем.
         *  Повод — журнал 22:43: заглючивший TeraTTS отдавал «готово» без файла
         *  на каждую фразу, и чтение убежало с главы 6 на главу 21 за 9 секунд. */
        // Пороги молчания теперь в таблице сроков: Timing.silentRestartAt и
        // Timing.silentStopAt (17.10.2026 — у локального и сетевого они разные:
        // локальному хватает трёх молчащих фраз, сетевому — четырёх).

        /** Сколько ОТКАЗОВ синтеза подряд означают «движок не работает». Два, а не
         *  пять, как у молчания: молчание бывает медленной подготовкой фразы, а
         *  отказ — уже ответ движка (16.10.2026, сборка 264x). */
        private const val TTS_DEAD_ERRORS = 1

        /** Перерыв между кусками речи, с которого пишем его в журнал (см.
         *  [onRangeStart]). Меньшие — это обычный ход речи: движок сообщает о
         *  каждом новом куске, и молчать по ним нельзя, журнал распухнет. */
        private const val RANGE_PAUSE_MS = 900L

        /** Сколько ждём движок реплик, если первая реплика пришла раньше, чем он
         *  поднялся (27.09.2026). По журналу Сержа движок поднимается за
         *  0,19 с, так что запас трёх секунд огромный; не поднялся — читаем
         *  реплики основным голосом, как было раньше. */
        private const val REPLY_WAIT_MS = 3_000L

        /** Как часто переспрашиваем движок реплик, пока он поднимается. */
        private const val REPLY_WAIT_STEP_MS = 150L

        /** Резервный способ перечислить движки через PackageManager, если getEngines пуст. */
        private fun queryEngines(context: Context): List<Pair<String, String>> {
            val pm = context.packageManager
            val intent = Intent(TextToSpeech.Engine.INTENT_ACTION_TTS_SERVICE)
            val services = runCatching {
                pm.queryIntentServices(intent, PackageManager.GET_META_DATA)
            }.getOrElse { emptyList() }
            return services.mapNotNull { ri ->
                val pkg = ri.serviceInfo?.packageName ?: return@mapNotNull null
                val label = runCatching { ri.loadLabel(pm).toString() }
                    .getOrNull()?.takeIf { it.isNotBlank() } ?: pkg
                pkg to label
            }.distinctBy { it.first }.sortedBy { it.second.lowercase() }
        }
    }
}
